MultiLanguageItemData['mx'][133872] = {name = "Receta: tocino crujiente", additional_info = "Rango 2\nSe liga al recogerlo\n[q2]Uso: Te enseña a cocinar tocino crujiente de manera más eficiente.\n[q2]Prepara más tocino crujiente en cada lote.\nRequiere Cocina de Legion (1)\nPrecio de venta:\nTocino crujiente\n[q2]Uso: ¡Come un poco de tocino!\n\n Extiende los beneficios de Bien alimentado de las Islas Quebradas entre 1 hora hasta un máximo de 6.\nPrecio de venta: \nRequiere Tajada de tocino (5), Pimiento dalapeño (5)"}
MultiLanguageItemData['mx'][133873] = {name = "Receta: tocino crujiente", additional_info = "Rango 3\nSe liga al recogerlo\n[q2]Uso: Te enseña a cocinar tocino crujiente de manera más eficiente.\n[q2]No desperdicias ni un solo ingrediente y preparas mucho más tocino crujiente en cada lote.\nRequiere Cocina de Legion (1)\nPrecio de venta:\nTocino crujiente\n[q2]Uso: ¡Come un poco de tocino!\n\n Extiende los beneficios de Bien alimentado de las Islas Quebradas entre 1 hora hasta un máximo de 6.\nPrecio de venta: \nRequiere Tajada de tocino (5), Pimiento dalapeño (5)"}
