MultiLanguageItemData['mx'][136812] = {name = "Sulfato de sabelita", additional_info = "Objeto de misión\n[q]\"Una versión refinada de la roca en la que se excavó el Fuerte Torre Oscura.\""}
MultiLanguageItemData['mx'][136819] = {name = "Polvo de Dragur", additional_info = "Objeto de misión\n[q]\"Un cajón lleno de polvo húmedo y apestoso. Se parece mucho al polvo de huesos.\""}
MultiLanguageItemData['mx'][136820] = {name = "Corazón de Nythendra", additional_info = "Objeto de misión\n[q]\"El corazón corrupto del dragón verde Nythendra. Si bien la corrupción sofocó su fuego exterior, el fuego interior sigue ardiendo con el calor del sol.\""}
MultiLanguageItemData['mx'][136821] = {name = "Pigmento ley", additional_info = "Objeto de misión\n[q]\"Un pigmento púrpura y brillante. Bueno para tatuar.\""}
MultiLanguageItemData['mx'][136822] = {name = "Reliquia de Nar'thalas robada", additional_info = "Objeto de misión\n[q]\"Saqueado por los naga Odio Espiral de la ruinas de Nar'thalas.\""}
MultiLanguageItemData['mx'][136823] = {name = "Lista de conductos de Deucus", additional_info = "Objeto de misión\n[q]\"Una lista que detalla los ingredientes y la construcción de un conducto de decocción nuevo.\""}
