MultiLanguageItemData['mx'][136827] = {name = "Jarabe onírico de Ysera", additional_info = "Objeto de misión\n[q]\"Un antiguo brebaje de los elfos de la noche que, según se dice, abre los ojos para ver un mundo desconocido.\""}
MultiLanguageItemData['mx'][136831] = {name = "[q0]Glifo de Absorber magia", additional_info = "Clases: Paladín\n[q]\"Aunque parezca que este glifo está quemado por completo y ya no contiene magia, puede que un vendedor no note la diferencia...\"\nPrecio de venta:"}
