MultiLanguageItemData['mx'][137014] = {name = "[q5]Achor, el Hambre eterna", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Cuero}\n8 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 200 / 200\nClases: Cazador de Demonios\n[q2]Equipar: Retirada vengativa te sana por un 25% de tu salud máxima y te otorga un 20% de robo de salud durante 8 s.\n[q]\"Los cazadores de demonios tienen una sed de batalla tan enorme como las legiones de sus más odiados enemigos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137015] = {name = "[q5]Ekowraith, creador de mundos", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Cuero}\n8 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 6 p.\nDurabilidad 200 / 200\nClases: Druida\n[q2]Equipar: Aumenta un 75% el efecto de Pellejo grueso, Influencia astral, Presteza felina y Don de Ysera.\n[q]\"No solo podemos evocar, sino conjurar nuestro propio lugar. Y todo... lo que siempre ha existido... se encuentra al servicio de nuestro sueño. Ahora, por favor... escúchame.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137016] = {name = "[q5]Túnica perdida de Sal'salabim", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Cuero}\n8 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 200 / 200\nClases: Monje\n[q2]Equipar: Cuando uses Embate con barril, el tiempo de reutilización restante de tu Aliento de Fuego se reinicia.\n[q]\"Puede que Sal'salabim perdiera esto cuando se desmayó por 6 horas...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137017] = {name = "[q5]Coraza del Val'kyr dorada", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Placas}\n18 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]+ 4 Versatilidad\nDurabilidad 200 / 200\nClases: Paladín\n[q2]Equipar: Cada vez que un enemigo te golpea con Escudo de vengador, reduce 3 s el tiempo de reutilización restante de Guardián de los antiguos reyes.\n[q]\"Los restos de una gran comandante que bajo desde el cielo ante sus enemigos, brillando con la energía del sol.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137018] = {name = "[q5]Conductor del destino", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Placas}\n18 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 200 / 200\nClases: Guerrero\n[q2]Equipar: Los ataques interceptados te otorgan a ti y al objetivo de Interceptar un escudo de absorción equivalente al 50% del daño infligido por el ataque durante 10 s.\n[q]\"Controla el mismísimo tiempo para proteger al mundo de la devastación.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137019] = {name = "[q5]Cenedril, Reflector del odio", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nEspalda\n3 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nClases: Monje\n[q2]Equipar: Toque de karma inflige un 150% más de daño.\n[q]\"Si conoces al enemigo y a ti mismo, no tienes que temerle al resultado de cien batallas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137020] = {name = "[q5]Susurro de los Nathrezim", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nEspalda\n3 armadura\n+3 [Fuerza o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nClases: Paladín\n[q2]Equipar: Veredicto del templario y Tormenta divina aumentan un 15% el daño de uno de los dos hechizos en los siguientes 4 s s.\n[q]\"Patético... ¿Es lo mejor que tienes?\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137021] = {name = "[q5]El engaño del Señor del Terror", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nEspalda\n3 armadura\n+3 agilidad\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nClases: Pícaro\n[q2]Equipar: Sutileza\n Cada 2 s, obtienes un 25% más de daño para tu siguiente Tormenta de shurikens. Se acumula hasta 30 veces.\n\nAsesinato, Forajido\n Cada 2 s, obtienes un 35% más de daño para tu siguiente Abanico de cuchillos. Se acumula hasta 30 veces.\n[q]\"Te estuve esperando, joven príncipe. Soy Mal'Ganis. Como verás, tu gente ahora me pertenece...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137022] = {name = "[q5]Sacrificio de Loramus Thalimedes", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pies} {Cuero}\n5 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 5 p.\nDurabilidad 95 / 95\nClases: Cazador de Demonios\n[q2]Equipar: Acometida vil inflige un 10% más de daño por cada objetivo golpeado.\n[q]\"Estas botas son lo único que quedó luego de que el Cuchillo de piedra de estampa atrapó a Rakh'likh en el profanado cuerpo de Loramus.\"\nPrecio de venta:"}
