MultiLanguageItemData['mx'][137098] = {name = "[q5]Grilletes de entrenamiento de la familia Zoldyck", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Cuero}\n4 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 2 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 70 / 70\nClases: Pícaro\n[q2]Equipar: Tus venenos y sangrados infligen un 30% de daño aumentado a los objetivos con menos del 30% de salud.\n[q]\"La familia Zoldyck son entrenados desde el nacimiento en el arte del asesinato. En los niveles más bajos de su estamento, los miembros aprenden a resistir los efectos de venenos mortales y a usarlos a la perfección.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137099] = {name = "[q5]Esposas caladas de Verdetez", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Cuero}\n4 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nDurabilidad 70 / 70\nClases: Pícaro\n[q2]Equipar: Entre los ojos tiene un 20% de probabilidad por punto de combo de aumentar en 200% el daño de tu siguiente Disparo de pistola.\n[q]\"En el mundo sin ley de las peleas de taberna y duelos espontáneos, la precisión es de vital importancia.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137100] = {name = "[q5]Negación de los semigigantes", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Cuero}\n4 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 70 / 70\nClases: Pícaro\n[q2]Equipar: Tus remates extienden la duración de las Espadas de las Sombras 0.2 s por cada punto de combo gastado.\n[q]\"Si crees que un tauren tratando de esconderse en las sombras es risible, ¡deberías ver a uno de esos vrykul semigigantes tratando de ser sigilosos en plena luz del día!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137101] = {name = "[q5]El llamado de la selva", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Malla}\n6 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nDurabilidad 70 / 70\nClases: Cazador\n[q2]Equipar: Reduce un 35% el tiempo de reutilización de todos los Aspectos.\n[q]\"Los cazadores tiene una poderosa conexión con la naturaleza: la habilidad para invocar aspectos animales para empoderarse y para crear amistad hasta con las bestias más salvajes.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137102] = {name = "[q5]Acritud de Al'Akir", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Malla}\n6 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Chamán\n[q2]Equipar: Cadena de relámpagos inflige un 5% de daño aumentado a cada objetivo subsecuente.\n[q]\"El relámpago aún recorre estos edificios. Tu poder se siente infinito y siempre aumentando...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137103] = {name = "[q5]Tempestades tormentosas", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Malla}\n7 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 70 / 70\nClases: Chamán\n[q2]Equipar: Los enemigos que ataques con Golpe de tormenta quedan cargados con relámpagos durante 15 s. Este efecto golpea a un enemigo cercano cada 1 s y le inflige 5% p. de daño de naturaleza.\n[q]\"Creados con las escamas de un antiguo dragón de las tormentas, liberan magia incontrolable a todo lo que esté cerca.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137104] = {name = "[q5]Redención de Nobundo", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Malla}\n6 armadura\n+3 [Agilidad o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Chamán\n[q2]Equipar: Sanación en cadena reduce un 50% el costo de maná de tu próxima Oleada de sanación.\n[q]\"El Clarividente Nobundo dejó la ciudad en pedazos, pero volvió empoderado por los elementos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][137105] = {name = "[q5]Guardia de Uther", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Placas}\n9 armadura\n+3 [Fuerza o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Paladín\n[q2]Equipar: Tu Bendición de libertad[Bendición de hechizos conjurados][Bendición de protección] duran un 50% más y sanan un 15% de la salud máxima del objetivo.\n[q]\"Uther el Iluminado, líder de la Mano de plata, imponía tanta presencia en el campo de batalla que sus caballeros algunas veces parecían invencibles e imparables.\"\nPrecio de venta:"}
