MultiLanguageItemData['mx'][137605] = {name = "Diseño: Botas de piedra ley", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer botas de piedra Ley.\n[q2]Reduce en gran cantidad los materiales requeridos para crear botas de piedra ley.\nRequiere Herrería de Legion (1)\n\n\n[q3]Botas de piedra ley\nSe liga al equiparlo\n{Pies} {Placas}\n11 armadura\n+4 [Fuerza o Intelecto]\n+5 aguante\nDurabilidad 65 / 65\nPrecio de venta:\nRequiere Mena de piedra ley (12), Flujo de vulpinia (2)\n Componentes opcionales: [] (#48)"}
MultiLanguageItemData['mx'][137606] = {name = "Diseño: Guanteletes de piedra ley", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer Guanteletes de piedra ley.\n[q2]Reduce en gran cantidad los materiales necesarios para crear guanteletes de piedra ley.\nRequiere Herrería de Legion (1)\n\n\n[q3]Guanteletes de piedra ley\nSe liga al equiparlo\n{Manos} {Placas}\n10 armadura\n+4 [Fuerza o Intelecto]\n+6 aguante\nDurabilidad 50 / 50\nPrecio de venta:\nRequiere Mena de piedra ley (12), Flujo de vulpinia (3)\n Componentes opcionales: [] (#48)"}
