MultiLanguageItemData['mx'][138937] = {name = "[q0]Moneda de Izal Lunablanca", additional_info = "Se liga al recogerlo\n[q]\"Estos magos me permitieron aterrizar aquí. Mientras la mayoría no hace más que mirar con sospecha y desprecio, o incluso algo peor, algunos aún pueden ver más allá de las apariencias. Mi deseo es que todos trabajemos juntos y reconozcamos a nuestro verdadero enemigo: la Legión Ardiente.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138938] = {name = "[q0]Moneda de Jace Tejeoscuro", additional_info = "Se liga al recogerlo\n[q]\"En mi vida anterior, me habría encantado poder vivir en esta maravilla flotante. Habría pasado días pescando en esta fuente mágica entre cada práctica de las artes arcanas, pero esos días pasaron hace mucho tiempo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138939] = {name = "[q0]Moneda de Kayn Furia del Sol", additional_info = "Se liga al recogerlo\n[q]\"Un fuerte liderazgo y una visión clara son la única ruta a la victoria.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138940] = {name = "[q0]Moneda de Kor'vas Espinosangriento", additional_info = "Se liga al recogerlo\n[q]\"No tengo la suerte de poder pescar ni de desear, hay demonios que exterminar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138941] = {name = "[q0]La moneda", additional_info = "Se liga al recogerlo\n[q]\"Obtienes 1 cristal de maná solo en este turno.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138942] = {name = "[q0]Monedabot de Joyatrón", additional_info = "Se liga al recogerlo\n[q]\"El módulo de deseos está ocupado en este momento. Intenta nuevamente más tarde. (Error 37)\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138943] = {name = "[q0]Moneda de Lady Liadrin", additional_info = "Se liga al recogerlo\n[q]\"Que la luz bañe toda esta tierra con toda su gloria.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138944] = {name = "[q0]Moneda de Lunara", additional_info = "Se liga al recogerlo\n[q]\"¿Qué es el llamado de la naturaleza? La verdad es que me gustaría que alguien me explicara qué es \"el llamado de la naturaleza\".\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138945] = {name = "[q0]Moneda de Illidan", additional_info = "Se liga al recogerlo\n[q]\"El fin de la Legión Ardiente.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138946] = {name = "[q0]Sello real de la Reina Azshara", additional_info = "Se liga al recogerlo\n[q]\"¡Pronto, TODOS sentirán mi ira!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138947] = {name = "[q0]Moneda con hilo de Gallywix", additional_info = "Se liga al recogerlo\n[q]\"¡Sí! Así puedo tener mi deseo y no perder mi moneda, ¡Ja! Oh no, ¡la cuerda se rompió! Estúpida fuente, devuélveme mi moneda..\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138948] = {name = "[q0]Moneda de Li Li", additional_info = "Se liga al recogerlo\n[q]\"Mi deseo es jamás quedarme sin continentes recientemente descubiertos que explorar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138949] = {name = "[q5]Kirel Narak", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pies} {Cuero}\n5 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]+ 3 Versatilidad\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 95 / 95\nClases: Cazador de Demonios\n[q2]Equipar: El daño inicial instantáneo de tu Aura de inmolación reduce el tiempo de reutilización restante de tu Marca ardiente en 2 s por cada enemigo impactado.\n[q]\"Contempla las flamas que han consumido incontables mundos. ¡Todo arderá bajo el fuego de la Legión\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][138951] = {name = "Remanente de fuego", additional_info = "Objeto de misión\n[q]\"Prueba de tu autoridad sobre el elemento del fuego.\""}
