MultiLanguageItemData['mx'][138956] = {name = "Señuelo hipermagnético", additional_info = "Único\n[q2]Uso: Coloca tu carnada en tu caña de pescar. Te podría ayudar a pescar algunas monedas de la fuente de Dalaran.\nPrecio de venta:"}
