MultiLanguageItemData['mx'][138958] = {name = "Gota de pegamento muy pegajoso", additional_info = "Único\n[q2]Uso: Colócale pegamento a tu gancho de pescar. Te podría ayudar a pescar algunas monedas de la fuente de Dalaran.\nPrecio de venta:"}
MultiLanguageItemData['mx'][138959] = {name = "Generador de microvórtices", additional_info = "Único\n[q2]Uso: Coloca el aparato en tu caña de pescar para crear un pequeño vórtice donde sea que pesques. Podría ayudarte a pescar ciertas monedas de la fuente de Dalaran.\nPrecio de venta:"}
MultiLanguageItemData['mx'][138960] = {name = "Cristal del deseo", additional_info = "Único\n[q2]Uso: Coloca el cristal en tu caña de pescar. Algunos pescadores draenei creen que esto te puede ayudar a pescar monedas de algunas fuentes.\nPrecio de venta:"}
MultiLanguageItemData['mx'][138961] = {name = "Agente enlazante alquímico", additional_info = "Único\n[q2]Uso: Esparce el agente enlazante en tu caña de pescar para lograr que se vincule mejor al metal. Podría ayudarte a pescar ciertas monedas en la fuente de Dalaran.\nPrecio de venta:"}
MultiLanguageItemData['mx'][138962] = {name = "Estrella de mar encordada", additional_info = "Único\n[q2]Uso: Ata la estrella de mar a tu caña de pescar. La estrella de mar podría ayudarte a pescar ciertas monedas de la fuente de Dalaran al atraparlas con sus pequeñas ventosas.\nPrecio de venta:"}
MultiLanguageItemData['mx'][138963] = {name = "Aparatito agarrador", additional_info = "Único\n[q2]Uso: Coloca el aparato en tu caña de pescar. Podría ayudarte a pescar ciertos tipos de monedas en la fuente de Dalaran.\nPrecio de venta:"}
