MultiLanguageItemData['mx'][139010] = {name = "[q3]Filoseda petrificada", additional_info = "Se liga al recogerlo\n[q2]Uso: Aumenta en 25 % la salud de tus tropas marchitas.\n\n Este efecto es permanente y se activará la próxima vez que entres al escenario El derrumbamiento."}
MultiLanguageItemData['mx'][139011] = {name = "[q4]Yelmo rabioso de Ondry'el", additional_info = "Se liga al recogerlo\n[q2]Uso: Uno de los miembros de tu ejército de marchitos puede usar el yelmo, lo que provoca que se convierta en un marchito rabioso.\n\n Este efecto es permanente y se activará la próxima vez que entres al escenario El derrumbamiento."}
