MultiLanguageItemData['mx'][139439] = {name = "[q6]El resguardo del alto guardián", additional_info = "Se liga al recogerlo\nÚnico\n{Mano izquierda} {Escudo}\n52 armadura\n+2 fuerza\n+7 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nPrecio de venta:"}
