MultiLanguageItemData['mx'][139445] = {name = "Lexicón vil", additional_info = "Objeto de misión\n[q]\"Las páginas negras del tomo están cerradas con un broche de metal pesado.\""}
MultiLanguageItemData['mx'][139447] = {name = "[q2]Vial de luz pura", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Invoca un Engendro de luz para que luche a tu lado durante 10 min.\n\n El Engendro de luz es muy resistente y se encargará de provocar a todos los enemigos cercanos.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139448] = {name = "[q2]Vial de sombras oscuras", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Invoca un Ignoto para que luche a tu lado durante 10 min.\n\n El Ignoto es muy resistente y se encargará de provocar a todos los enemigos cercanos.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139449] = {name = "[q2]Esencia de los naaru", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Enfoca la Luz de los naaru para quemar a todos los enemigos que están en un radio de 15 m e infligirles ([2000% of Spell Power]) p. de daño sagrado dos veces durante 4 s.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139450] = {name = "[q2]Esfera de vacío", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Invoca dos tentáculos del vacío para que aplasten a todos los enemigos que están frente a ti en un radio de 8 m e inflijan ([2000% of Spell Power]) p. de daño de las sombras.\n\n Solo puede usarse en las Islas Quebradas y Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139451] = {name = "[q2]Poción de vacío turbulento", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Bebe de la poción oscura para entregar tu mente al Vacío.\n\n Durante los siguientes 10 min, generarás 10 p. de demencia por segundo.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139452] = {name = "[q2]Esencia de la Luz", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Liberas la energía de la Luz, lo que hace que todos los miembros del grupo sanen por un 5% de su salud máxima cada 2 s.\n\n Solo puede usarse en las Islas Quebradas y en Argus.\nPrecio de venta:"}
