MultiLanguageItemData['mx'][139458] = {name = "Bálsamo para toxina de murciélago vil", additional_info = "Objeto de misión\n[q]\"Combate la toxina que causa que las mordidas de murciélago vil se infecten y pudran.\""}
MultiLanguageItemData['mx'][139459] = {name = "[q2]Protección de la Luz", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Concede la Bendición de la Luz cuando se usa. En caso de que recibas daño fatal, la Luz te devolverá toda tu salud y derribará a los enemigos que te rodeen.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139460] = {name = "Sello del Destino quebrado", additional_info = "[q]\"Altera el destino para proporcionar una oportunidad de obtener un tesoro más en la Pesadilla Esmeralda o en la Fortaleza Nocturna.\""}
MultiLanguageItemData['mx'][139461] = {name = "[q2]Runa de Oscuridad", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 18 h\n[q2]Uso: Activa la runa para ganar un Sudario de oscuridad. En caso de que recibas daño fatal, la oscuridad te devolverá toda la salud y derribará a los enemigos que te rodean.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\nPrecio de venta:"}
MultiLanguageItemData['mx'][139463] = {name = "Bálsamo para toxina de murciélago vil", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Aplica una sola dosis del antídoto para la toxina de murciélago vil a tu objetivo. (4 Seg Reutilización)\n[q]\"Combate la toxina que causa que las mordidas de murciélago vil se infecten y pudran.\""}
