MultiLanguageItemData['mx'][139471] = {name = "[q3]Misiva de Torre Oscura", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\n[q]\"Señor Cresta Cuervo, la Legión acepta tus condiciones. Los refuerzos llegarán según los planes. Será mejor que cumplas tu parte del trato.\""}
MultiLanguageItemData['mx'][139472] = {name = "[q3]Elegante invitación a una fiesta", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\n[q]\"Recibe nuestra cordial invitación al Dominio Enjoyado, en el que disfrutaremos de exquisitos festines y bebidas, con la posible presencia de un invitado sorpresa...\""}
