MultiLanguageItemData['mx'][139544] = {name = "[q0]Estandarte de guerra de los Marvilis deteriorado", additional_info = "Se liga al recogerlo\n[q]\"Alguna vez se ondeó orgullosamente en los mástiles de drakkares vrykul.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][139545] = {name = "[q0]Campana oxidada de marinero", additional_info = "Se liga al recogerlo\n[q]\"Se usa para enviar señales a otros barcos en niebla densa.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][139546] = {name = "[q6]Ánima tortuosa de las almas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Caballero de la muerte\n[q2]Uso: Desbloquea la apariencia del Toque de los No-muertos para las Fauces de los Malditos .\n[q]\"Un experimento fallido para robar por arte de magia la energía de los muertos de hace mucho tiempo. La masa resultante se retuerce y ondula de modo inquietante.\""}
MultiLanguageItemData['mx'][139547] = {name = "[q6]Runas del oscurecer", additional_info = "Se liga al recogerlo\nÚnico\nClases: Caballero de la muerte\n[q2]Uso: Desbloquea la apariencia de la Hojarruna Oscura para las Espadas del Príncipe Caído .\n[q]\"Aunque están escritas en un idioma antiguo que ningún alma viva recuerda, las palabras saltan a tu boca, ansiosas por ser leídas.\""}
MultiLanguageItemData['mx'][139548] = {name = "[q6]El anzuelo del segahuesos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Caballero de la muerte\n[q2]Uso: Desbloquea la apariencia del Segador de huesos para Apocalipsis .\n[q]\"Esta arma tosca y brutal, alimentada por la energía constante de la Ciudadela de la Corona de Hielo, podría convertirse fácilmente en un instrumento de muerte.\""}
MultiLanguageItemData['mx'][139549] = {name = "[q6]Disfraz del Caminamuerte", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador de Demonios\n[q2]Uso: Desbloquea la apariencia del Caminamuerte para las Espadas Gemelas del Falsario .\n[q]\"Un arma oscura cuyo dueño murió hace mucho y que ansía volver a probar la sangre.\""}
MultiLanguageItemData['mx'][139550] = {name = "[q6]Baluarte de la Celadora de hierro", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador de Demonios\n[q2]Uso: Desbloquea la apariencia de la Celadora de hierro para las Hojas de guerra Aldrachi .\n[q]\"La Celadora de hierro, un ensamblaje de los draenei convertido en instrumento de destrucción por la Legión, cayó hace tiempo, durante la conquista del mundo natal Aldrachi.\""}
MultiLanguageItemData['mx'][139551] = {name = "[q6]El brotesol", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Desbloquea la apariencia del Alcance de Guardasol para la Guadaña de Elune .\n[q]\"Una rara flor del Sueño Esmeralda que no se ve en Azeroth desde la Guerra de los ancestros.\""}
MultiLanguageItemData['mx'][139552] = {name = "[q6]Pluma del espíritu lunar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Desbloquea la apariencia de Espíritu lunar para Colmillos de Ashamane .\n[q]\"Una única pluma de un solitario dios salvaje. Con ella, un druida de la Zarpa podría aprender a dominar una forma antes oculta.\""}
MultiLanguageItemData['mx'][139553] = {name = "[q6]Marca del guardián del claro", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Desbloquea la apariencia del Guardián del Claro para las Garras de Ursoc .\n[q]\"Una poderosa marca que Ursol coloca en los osos salvajes para potenciarlos como defensores de la naturaleza en tiempos de necesidad.\""}
MultiLanguageItemData['mx'][139554] = {name = "[q6]Bellota de la Eternidad", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Desbloquea la apariencia de la Corona de la Celadora para G'Hanir, el Árbol Madre .\n[q]\"De uno de los árboles más antiguos del ensueño se salvaron varias de estas bellotas mágicas antes de la caída ante la Pesadilla.\""}
MultiLanguageItemData['mx'][139555] = {name = "[q6]Diseños del gran arquitecto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Uso: Desbloquea la apariencia del Alcance del titán para la Titánica .\n[q]\"Planos detallados para crear un magistral arco tecnomágico. Se empleó como núcleo una poderosa fuente de energía que crearon los titanes. Se desconoce cómo llegaron a los archivos de Mimiron.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][139556] = {name = "[q6]Notas de Syriel Lunabaja: Guardia cuervo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Uso: Desbloquea la apariencia de Guardia cuervo para Thas'dorah, legado de los Brisaveloz .\nRequiereCorte de Farondis\n: Reverenciado\n[q]\"Planos detallados para construir una ballesta elegante y potente. Se perdieron porque los materiales necesarios no existían.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][139557] = {name = "[q6]Último aliento del bosque", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Uso: Desbloquea la apariencia de Fortaleza del oso para Garfa Corva, Lanza de los Dioses Salvajes .\n[q]\"Ursoc sacrificó su vida dos veces por la naturaleza, pero deja atrás su legado para que otros nobles protectores sigan sus pasos.\""}
MultiLanguageItemData['mx'][139558] = {name = "[q6]Carga del lanomante", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q]\"Cote \"El pastor\" Metcalf no logró develar los secretos del misterioso bastón que bala.\""}
MultiLanguageItemData['mx'][139559] = {name = "[q6]El diseño de las estrellas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Desbloquea la apariencia de Diseño de las estrellas para Felo'melorn .\n[q]\"Diseños de los natos nocturnos para una hoja de hechizo que refleja una constelación muy querida por este pueblo.\""}
MultiLanguageItemData['mx'][139560] = {name = "[q6]Cristal siempreardiente", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Desbloquea la apariencia de Recuerdo de Pirofrío para Frío del ébano .\n[q]\"Un cristal congelado iluminado por un fuego frío imperecedero. Se puede tocar y no muestra signos de derretirse.\""}
MultiLanguageItemData['mx'][139561] = {name = "[q6]Leyenda del Rey Mono", additional_info = "Se liga al recogerlo\nÚnico\nClases: Monje\n[q2]Uso: Desbloquea la apariencia de Guardián de brebajes anciano para Fu Zan, el Compañero del Vagabundo .\n[q]\"Un potentísimo brebaje especial, supuestamente preparado por el propio Rey Mono. El barril es exquisito y podría servir para algo más que para un brebaje.\""}
MultiLanguageItemData['mx'][139562] = {name = "[q6]Aliento de la serpiente indestructible", additional_info = "Se liga al recogerlo\nÚnico\nClases: Monje\n[q2]Uso: Desbloquea la apariencia de Aliento de la serpiente indestructible para Sheilun, Bastón de la Niebla .\n[q]\"Una fuente arremolinada de energía mágica, supuestamente nacida del vientre de un dragón más antiguo que el tiempo.\""}
MultiLanguageItemData['mx'][139563] = {name = "[q6]El puño de tormenta", additional_info = "Se liga al recogerlo\nÚnico\nClases: Monje\n[q2]Uso: Desbloquea la apariencia de Puño Tormenta para los Puños de los Cielos .\n[q]\"Poco se sabe de la creación del Puño de tormenta, aunque la energía que contiene parece nacer de Therazane y Al'Akir, una unión inesperada.\""}
MultiLanguageItemData['mx'][139564] = {name = "[q6]Edictos perdidos del vigía", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Uso: Desbloquea la apariencia de Armamento del Vigía para La Mano de plata .\n[q]\"Juramos devolverle la esperanza a este afligido mundo. Y buscar la tiranía y la maldad donde sea que se afinquen... para aplastar con un martillo de justicia a los malvados.\""}
MultiLanguageItemData['mx'][139565] = {name = "[q6]Centella del exarca caído", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Uso: Desbloquea la apariencia de Baluarte del vindicador para Veraguardia .\n[q]\"Al caer el exarca Kelios, desapareció toda esperanza de conservar el templo. La Legión venció. La única paz que encontrarían ahora era pensar en los pocos que lograron escapar, aunque la Legión también les arrebataría eso poco después.\""}
MultiLanguageItemData['mx'][139566] = {name = "[q6]Corazón de la Corrupción", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Uso: Desbloquea la apariencia de Recuerdo corrupto para Crematoria .\n[q]\"Un siniestro vistazo a un pasado que Crematoria dejó atrás y que muchos esperaban que jamás se reavivara.\""}
MultiLanguageItemData['mx'][139567] = {name = "[q6]Escrituras del fin", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Uso: Desbloquea la apariencia de Cumbre del guardalibros para Cólera de luz .\n[q]\"Palabras reunidas de los tomos dispersos del Archivista que predicen tiempos terribles.\""}
MultiLanguageItemData['mx'][139568] = {name = "[q6]Bastón del natoluz", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Uso: Desbloquea la apariencia de Blasón del natoluz para T'uure, Guía de los Naaru .\n[q]\"El bastón resuena levemente con el poder de los valkyra. El sonido desaparece al tocarlo.\""}
MultiLanguageItemData['mx'][139569] = {name = "[q6]Zarpa de N'Zoth", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Uso: Desbloquea la apariencia de Zarpa de N'Zoth para Xal'atath, Daga del Imperio Negro .\n[q]\"Los ojos parpadean. La carne palpita. Sigue bastante vivo.\""}
MultiLanguageItemData['mx'][139570] = {name = "[q6]La clave del hueso roto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Uso: Desbloquea la apariencia de Rompehuesos para Las Matarreyes .\n[q]\"Los secretos de una asesina muerta hace tiempo, conocida solo como \"Rompehuesos\". Se dice que tenía la costumbre de romper las piernas de sus víctimas ya muertas cuando una de ellas regresó de la tumba buscando venganza.\""}
MultiLanguageItemData['mx'][139571] = {name = "[q6]Tomo de los venenos sobrenaturales", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Uso: Desbloquea la apariencia de Venenonte para Colmillos del Devorador .\n[q]\"Un texto pasado de generación en generación de cazasombras zandalari. Detalla algunas de las armas y venenos más exóticos que usaban para matar a sus enemigos.\""}
MultiLanguageItemData['mx'][139572] = {name = "[q6]Códice perdido de los Amani", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Uso: Desbloquea la apariencia de Prestigio de los Amani para El Puño de Ra-Den .\n[q]\"Un texto trol perdido hace tiempo que describe a muchos de los líderes que surgieron y cayeron a lo largo de las generaciones. Se detiene en un trol llamado Atai'natha y una poderosa garra mágica que usaba para imponer su gobierno.\""}
MultiLanguageItemData['mx'][139573] = {name = "[q6]La maza de guerra de Shirvallah", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Uso: Desbloquea la apariencia de Campeón de Zandalar para Martillo maldito .\n[q]\"A pesar de su mango ornado, esta maza brutal reclamó muchas vidas en un intento voluntario de honrar al dios primigenio Shirvallah. Se perdió hace mucho en el mar, junto al sumo sacerdote que la empuñaba.\""}
MultiLanguageItemData['mx'][139574] = {name = "[q6]Espiral de la reina ahogada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Uso: Desbloquea la apariencia de Serpiente Enroscada para Sharas'dal, Cetro de las Mareas .\n[q]\"Deslizándose bajo las olas, los altonatos poco tenían que ver con su antigua naturaleza. Ahora pertenecen a las profundidades y sirven a algo más oscuro...\""}
MultiLanguageItemData['mx'][139575] = {name = "[q6]Esencia del verdugo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Desbloquea la apariencia El final del destino para Ulthalesh, la Cosechadora Vientomuerto .\n[q]\"Esta esencia, destilada de las calaveras de grandes campeones, ofrece un gran poder a quienes desean pagar el siniestro costo.\""}
MultiLanguageItemData['mx'][139576] = {name = "[q6]Semblante del primer heraldo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Desbloquea la apariencia de Faz de Thal'kiel para Cráneo de los Man'ari .\n[q]\"Entre los frenólogos más importantes del periodo estaban Thal'kiel y Archimonde. En particular, Thal'kiel era célebre por tener la calavera arquetípica de los hechiceros, por la que era muy admirado.\""}
MultiLanguageItemData['mx'][139577] = {name = "[q6]La joya ardiente de Sargeras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Desbloquea la apariencia de Terror de la Legión para Cetro de Sargeras .\n[q]\"Dentro de esta joya carmesí arde una llama oscura que se aproxima con ansia al borde cuando te acercas.\""}
MultiLanguageItemData['mx'][139578] = {name = "[q6]El rompehojas de arcanita", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Uso: Desbloquea la apariencia de Rompehojas de arcanita para Strom'kar, la Belicista .\n[q]\"Esta hacha, fabricada a mano por Helgar, maestro herrero de Bastión del Cielo, debería superar a cualquier acero encontrado en Azeroth.\""}
MultiLanguageItemData['mx'][139579] = {name = "[q6]Los matadragones", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Uso: Desbloquea la apariencia de Filo del Asesino de Dragones para Espadas de Guerra de los Valarjar .\n[q]\"Dos temibles hachas con sendas calaveras de dragones asesinados, fabricadas con madera rúnica vrykul encantada. Unas armas impresionantes para cualquier guerrero.\""}
MultiLanguageItemData['mx'][139580] = {name = "[q6]Placa ardiente del Rompemundos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Uso: Desbloquea la apariencia de Último aliento del Rompemundos para Escama del Guardián de la Tierra .\n[q]\"Sangre oscura derretida del propio Neltharion supura por sus bordes y arde en su antigua guarida desde hace incontables años, esperando a reunirse con una escama perdida del mismo padre.\""}
MultiLanguageItemData['mx'][139583] = {name = "Runa demoníaca", additional_info = "Objeto de misión\n[q]\"Hay caracteres indescifrables grabados en la piedra.\""}
MultiLanguageItemData['mx'][139584] = {name = "[q2]Bombas pegajosas", additional_info = "Se liga al recogerlo\n[q2]Uso: Lanza una bomba pegajosa a tu objetivo, que detonará después de 5 s para infligir ([375% of Attack Power]) p. de daño a todos los enemigos en un radio de 5 m.\n\n Solo se puede usar en las Islas Quebradas y en Argus. (30 Seg Reutilización)\n15 cargas"}
MultiLanguageItemData['mx'][139585] = {name = "[q2]Polvo de humo", additional_info = "Se liga al recogerlo\n[q2]Uso: Arroja el Polvo de humo al suelo y aplica Esfumarse, lo que te hace desaparecer en una nube de humo.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\n10 cargas"}
MultiLanguageItemData['mx'][139586] = {name = "[q2]Té de cardo", additional_info = "Se liga al recogerlo\n[q2]Uso: Restaura 100 p. de energía.\n\n Solo puede usarse en las Islas Quebradas. (5 Seg Reutilización)\n10 cargas"}
MultiLanguageItemData['mx'][139587] = {name = "[q3]Cajón sospechoso", additional_info = "Se liga al recogerlo\nJuguete\nClases: Pícaro\n[q2]Uso: Disfrázate de una caja de madera. (30 Min Reutilización)"}
MultiLanguageItemData['mx'][139588] = {name = "[q2]Paquete de pociones de batalla", additional_info = "Se liga al recogerlo\n[q2]Uso: Bebe una útil poción de batalla del alijo personal de uno de los Descoronados.\n\n Solo se puede usar en las Islas Quebradas y en Argus. (30 Seg Reutilización)\n6 cargas"}
MultiLanguageItemData['mx'][139589] = {name = "[q2]Cuchillos para lanzar envenenados", additional_info = "Se liga al recogerlo\n[q2]Uso: Lanza un cuchillo envenenado al objetivo, que lo incapacita durante 1 min.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\n8 cargas"}
MultiLanguageItemData['mx'][139590] = {name = "[q3]Pergamino de teletransportación: Ravenholdt", additional_info = "Se liga al recogerlo\n[q2]Uso: Te teletransporta a la Mansión Ravenholdt. (1 Hora Reutilización)"}
MultiLanguageItemData['mx'][139591] = {name = "[q0]Tomo robado de conocimiento de artefactos", additional_info = "Se liga al recogerlo\nPrecio de venta:"}
MultiLanguageItemData['mx'][139592] = {name = "[q2]Botas humeantes", additional_info = "Se liga al recogerlo\n[q2]Uso: Según parece, este dispositivo mejora tu velocidad un 15% durante 1 h mientras estás en sigilo.\n\n Solo se puede usar en las Islas Quebradas y en Argus.\n3 cargas"}
MultiLanguageItemData['mx'][139593] = {name = "Saco de mercancías recuperadas", additional_info = "Se liga al recogerlo\n[q2]Uso: Hurgas en el cofre en busca de tesoros ocultos. Solo disponible en tu Patio de rescate."}
MultiLanguageItemData['mx'][139594] = {name = "[q2]Cajón rescatado", additional_info = "Se liga al recogerlo\n[q2]Uso: Hurgas en el cofre en busca de tesoros ocultos. Solo disponible en tu Patio de rescate."}
MultiLanguageItemData['mx'][139595] = {name = "[q4]Leotardos Nar'thalas otrora a la moda", additional_info = "Se liga al recogerlo\n{Piernas} {Tela}\n4 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 120 / 120\nRequiereCorte de Farondis\n: Exaltado\n[q]\"La moda ha evolucionado en los últimos diez mil años.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][139596] = {name = "[q4]Espaldares de raíces enredadas", additional_info = "Se liga al recogerlo\n{Hombro} {Cuero}\n6 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 100 / 100\nRequiereTejesueños\n: Exaltado\nPrecio de venta:"}
MultiLanguageItemData['mx'][139597] = {name = "[q4]Camisote de anillas forjado en la montaña", additional_info = "Se liga al recogerlo\n{Pecho} {Malla}\n12 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 165 / 165\nRequiereTribu Altamontaña\n: Exaltado\nPrecio de venta:"}
MultiLanguageItemData['mx'][139598] = {name = "[q4]Quijotes del mito olvidado", additional_info = "Se liga al recogerlo\n{Piernas} {Placas}\n16 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 120 / 120\nRequiereValarjar\n: Exaltado\nPrecio de venta:"}
MultiLanguageItemData['mx'][139599] = {name = "[q4]Anillo del Kirin Tor potenciado", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nDedo\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 9 p.\n[q2]Uso: Teletransporta al taumaturgo a Dalaran. (30 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][139600] = {name = "[q3]Cincho trenzado de cuerda de maná", additional_info = "Se liga al recogerlo\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 50 / 50\nRequiereLos caídos de la noche\n: Honorable\nPrecio de venta:"}
MultiLanguageItemData['mx'][139601] = {name = "[q3]Guantes de cazador de arpías", additional_info = "Se liga al recogerlo\n{Manos} {Cuero}\n5 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 50 / 50\nRequiereTribu Altamontaña\n: Reverenciado\nPrecio de venta:"}
MultiLanguageItemData['mx'][139602] = {name = "[q3]Vestiduras del sacerdote de runas Valarjar", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n9 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]+ 4 Versatilidad\nDurabilidad 85 / 85\nRequiereValarjar\n: Reverenciado\nPrecio de venta:"}
MultiLanguageItemData['mx'][139603] = {name = "[q3]Botas de guerra de la patrulla de la bóveda", additional_info = "Se liga al recogerlo\n{Pies} {Placas}\n11 armadura\n+4 [Fuerza o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 65 / 65\nRequiereLas Celadoras\n: Reverenciado\nPrecio de venta:"}
