MultiLanguageItemData['mx'][140104] = {name = "[q6]El guardián falso", additional_info = "Objeto de misión\nÚnico\n[q]\"Informes históricos de investigación acerca de los eventos relacionados con la traición a Loken por parte de sus guardianes aliados, por el historiador Llore.\""}
MultiLanguageItemData['mx'][140105] = {name = "[q6]Las historias jamás contadas de la Guerra de los Ancestros", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q]\"Análisis en profundidad de los eventos menos escuchados de la Guerra de los Ancestros y el impacto que tuvieron en el futuro de Azeroth.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][140106] = {name = "[q6]El sacrificio del Emperador Shaohao", additional_info = "Objeto de misión\nÚnico\n[q]\"La historia del gran sacrificio de Shaohao y las generaciones que siguieron sin gobernante.\""}
MultiLanguageItemData['mx'][140107] = {name = "[q6]El Códice de los Muertos", additional_info = "Objeto de misión\nÚnico\n[q]\"Un texto nathrezim casi indescifrable para las razas mortales de Azeroth.\""}
MultiLanguageItemData['mx'][140108] = {name = "[q6]Más allá del Trono del Aire", additional_info = "Objeto de misión\nÚnico\n[q]\"Historia del reino de los elementales de aire, el momento de su desterramiento y el conflicto eterno de los señores elementales.\""}
MultiLanguageItemData['mx'][140109] = {name = "[q6]Cómo meditar en medio de un huracán", additional_info = "Se liga al recogerlo\nÚnico\nClases: Monje\n[q]\"Instrucciones para practicar el arte de rodearse de paz, incluso en medio de una gran vorágine externa, por el maestro Xunsu.\""}
MultiLanguageItemData['mx'][140110] = {name = "[q6]Monasterio de Líber", additional_info = "Objeto de misión\nÚnico\n[q]\"Un texto sagrado, del que solo se realizaron 12 copias, muchas de las cuales se cree fueron destruidas.\""}
MultiLanguageItemData['mx'][140111] = {name = "[q6]La guerra de Inbjerskorn", additional_info = "Objeto de misión\nÚnico\n[q]\"Texto traducido de varias tablillas terráneas en el que se describe una guerra vrykul antigua.\""}
MultiLanguageItemData['mx'][140112] = {name = "[q6]La era de Galakrond", additional_info = "Objeto de misión\nÚnico\n[q]\"Fascinantes historias sobre los primeros dragones, los guardianes de Ulduar y cómo llegó el poder a los cinco aspectos de dragón, según los relatos de la historiadora Evelyna.\""}
MultiLanguageItemData['mx'][140113] = {name = "[q6]Leyendas de la Mano de plata", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q]\"Históricas leyendas que se remontan al inicio de la humanidad, detallando los orígenes de los paladines y su relación con la Luz, contadas por la historiadora Evelyna.\""}
MultiLanguageItemData['mx'][140114] = {name = "[q6]Toque del Abismo", additional_info = "Objeto de misión\nÚnico\n[q]\"Enseñanzas prohibidas de la investigación de los poderes del vacío y cómo convertir los peligros en armas, por Natalie Seline.\""}
MultiLanguageItemData['mx'][140115] = {name = "[q6]La corrupción de los eredar y la pelea de los draenei", additional_info = "Objeto de misión\nÚnico\n[q]\"Un texto antiguo traído a Azeroth por los draenei, pero perdido los primeros meses fuera del Exodar.\""}
MultiLanguageItemData['mx'][140116] = {name = "[q6]Fatalidad de Modgud", additional_info = "Objeto de misión\nÚnico\n[q]\"Una historia nefasta de una sacerdotisa Hierro Negro que adquirió una herramienta de los dioses antiguos, solo para caer en una inevitable corrupción.\""}
MultiLanguageItemData['mx'][140117] = {name = "[q6]A la caza de la Cólera de luz", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q]\"Esta compilación del Kirin Tor de Dalaran es una advertencia acerca de los peligros que representan las poderosas armas inestables, incluso en las manos de magos experimentados.\""}
MultiLanguageItemData['mx'][140118] = {name = "[q6]El día en que llegó la Horda", additional_info = "Objeto de misión\nÚnico\n[q]\"Un informe personal acerca de los primeros conflictos entre humanos y orcos, escrito por un consejero y dirigido al Rey Llane de Ventormenta.\""}
MultiLanguageItemData['mx'][140119] = {name = "[q6]El Códice de los Muertos", additional_info = "Objeto de misión\nÚnico\n[q]\"Un texto nathrezim casi indescifrable para las razas mortales de Azeroth.\""}
MultiLanguageItemData['mx'][140120] = {name = "[q6]El tomo vil de Vorgalus Dor", additional_info = "Objeto de misión\nÚnico\n[q]\"Garabatos demoníacos del difunto brujo Vorgalus Dor. Cuenta sobre muchas armas antiguas y poderosas originarias de lejanos mundos de la Legión.\""}
