MultiLanguageItemData['mx'][140123] = {name = "[q6]La canción de las escamas", additional_info = "Objeto de misión\nÚnico\n[q]\"Sobre el origen de los naga, por un autor desconocido.\""}
MultiLanguageItemData['mx'][140124] = {name = "[q6]Más allá del Trono del Aire", additional_info = "Objeto de misión\nÚnico\n[q]\"Historia del reino de los elementales de aire, el momento de su desterramiento y el conflicto eterno de los señores elementales.\""}
MultiLanguageItemData['mx'][140125] = {name = "[q6]La caída del Jefe de Guerra", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q]\"Informes históricos sobre la muerte de Orgrim Martillo Maldito, tomados de muchos de los que pelearon a su lado.\""}
MultiLanguageItemData['mx'][140126] = {name = "[q6]Magia antigua y cómo aplicarla sin destruir el mundo", additional_info = "Objeto de misión\nÚnico\n[q]\"Un compendio de conocimiento acumulado de muchos archimagos del Kirin Tor, con recuentos detallados de las estupideces de magos imprudentes de épocas pasadas.\""}
