MultiLanguageItemData['mx'][140337] = {name = "Cecina dura importada", additional_info = "[q2]Uso: Restaura ( 38 * 18 / 5) p. de salud durante 18 s. Debes permanecer sentado mientras comes.\n[q]\"Gracias al uso excesivo de sal, es muy popular en las pequeñas aldeas de Azeroth.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][140338] = {name = "Pastel de hígado de dentosangre envuelto en maná", additional_info = "[q2]Uso: Restablece ( 38 * 21 / 5) p. de salud durante 21 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 1 p. de aguante y versatilidad durante 15 min.\n[q]\"Este pastel, elaborado en un lugar llamado Páramos de Poniente, se envolvió en maná para preservar su frescura.\"\nPrecio de venta:"}
