MultiLanguageItemData['mx'][142226] = {name = "[q4]Confianza de lobohalcón feroz", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un lobohalcón feroz del Maestro de caza que se puede montar.\n[q2]Invoca y retira a tu Lobohalcón feroz del Maestro de caza. Es una montura voladora.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Una mezcla de garfas y garras que vuela y nada. Nadie está a salvo.\"\nVendedora:\nPan, la Mano amable\nZona:\nRecinto del Disparo Certero"}
MultiLanguageItemData['mx'][142227] = {name = "[q4]Confianza de lobohalcón leal", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un lobohalcón leal del Maestro de caza que se puede montar.\n[q2]Invoca y retira a tu Lobohalcón leal del Maestro de caza. Es una montura voladora.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El espíritu del gran cazador ha decidido que eres digno, y ahora sus hijos siempre responderán a tu llamado.\"\nMisión:\nNoche de la naturaleza"}
MultiLanguageItemData['mx'][142228] = {name = "[q4]Confianza de lobohalcón temible", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un lobohalcón temible del Maestro de caza que se puede montar.\n[q2]Invoca y retira a tu Lobohalcón temible del Maestro de caza. Es una montura voladora.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Si juegas a la pelota con él, lo más probable es que regrese con la cabeza de un mamífero o un humanoide pequeño.\"\nVendedora:\nPan, la Mano amable\nZona:\nRecinto del Disparo Certero"}
MultiLanguageItemData['mx'][142231] = {name = "[q4]Riendas putrefactas del Vencedor vilretama", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a un Vencedor vilretama del Señor de la muerte.\n[q2]Invoca y retira a tu Vencedor vilretama del Señor de la muerte. Es una montura voladora.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un poderoso dragón rojo renacido en la no-muerte con sus propias energías vitales, una verdadera burla a la vida.\"\nMisión:\nEl Glaciar Perdido"}
MultiLanguageItemData['mx'][142232] = {name = "[q4]Riendas de hierro del Vermis de guerra sanguinario", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Vermis de guerra sanguinario del Señor de la batalla.\n[q2]Invoca y retira a tu Vermis de guerra sanguinario del Señor de la batalla. Es una montura voladora.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"También responde al nombre de \"Señor Mordisquitos\".\"\nMisión:\nLa prueba de ira"}
MultiLanguageItemData['mx'][142233] = {name = "[q4]Riendas sombrías del Corcel iracundo detestable", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Corcel iracundo detestable del Señor abisal.\n[q2]Invoca y retira a tu Corcel iracundo detestable del Señor abisal. Es una montura voladora.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Sombra y fuego. ¿Qué podría malir sal?\"\nBotín:\nLord Hel'Nurath\nZona:\nCosta Quebrada"}
