MultiLanguageItemData['mx'][142383] = {name = "Diseño: Lanza Negra", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una Lanza Negra.\nRequiere Herrería clásica (1)\nPrecio de venta:\n[q3]Lanza Negra\nSe liga al equiparlo\n{Dos manos} {Arma de asta}\n{6 - 13 p. de daño} {Velocidad 3.60}\n(2.6 p. de daño por segundo)\nDurabilidad 100 / 100\n[q2]Probabilidad al acertar: Los miembros del grupo tienen la posibilidad de aumentar su golpe crítico 17 p. Dura 20 s.\nPrecio de venta: \nRequiere Barra de torio encantado (20), Mojo potente (20), Esmeralda enorme (2), Diamante de Azeroth (2), Piedra de pulir densa (2)"}
MultiLanguageItemData['mx'][142384] = {name = "[q6]Cristal abisal agotado", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\n[q]\"Este cristal inscrito con runas apenas late con un resto de energía oscura.\""}
MultiLanguageItemData['mx'][142385] = {name = "Barra de torio encantado robada", additional_info = "Objeto de misión\n[q]\"Hurtadas de los campos alrededor de Un'Goro, estas barras son muy útiles a la hora de realizar trabajos de herrería.\""}
