MultiLanguageItemData['mx'][142401] = {name = "Orbes de telemancia", additional_info = "Único\n[q2]Uso: Lanza un Orbe de telemancia a la ubicación y hace aparecer Marchitados hambrientos. Solo funciona en el Distrito noble de la ciudad de Suramar. (45 Seg Reutilización)\n[q]\"Un escuadrón de marchitos, entregado al instante.\""}
