MultiLanguageItemData['mx'][142406] = {name = "[q2]Tambores de la montaña", additional_info = "[q2]Uso: Aumenta un 15% la celeridad de todos los miembros del grupo y banda. Dura 40 s.\n\n Los aliados que reciban este efecto quedarán Agotados y no podrán beneficiarse de Ansia de sangre, Heroísmo o Distorsión temporal nuevamente durante 10 min.\n\n No afecta a los aliados con nivel superior a 50. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][142407] = {name = "Patrón: Tambores de la montaña", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer unos Tambores de la montaña.\n[q2]Fabricar Tambores de la montaña.\nRequiere Peletería de Legion (1)\nPrecio de venta:\n[q2]Tambores de la montaña\n[q2]Uso: Aumenta un 15% la celeridad de todos los miembros del grupo y banda. Dura 40 s.\n\n Los aliados que reciban este efecto quedarán Agotados y no podrán beneficiarse de Ansia de sangre, Heroísmo o Distorsión temporal nuevamente durante 10 min.\n\n No afecta a los aliados con nivel superior a 50. (2 Min Reutilización)\nPrecio de venta:\nRequiere Cuero de petrapiel (10), Garra intacta (5), Diente intacto (5)"}
MultiLanguageItemData['mx'][142408] = {name = "Patrón: Tambores de la montaña", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer unos Tambores de la montaña.\n[q2]Reduce la cantidad de materiales necesarios para crear unos Tambores de la montaña.\nRequiere Peletería de Legion (1)\nRequiereTribu Altamontaña\n: Reverenciado\nPrecio de venta:\n[q2]Tambores de la montaña\n[q2]Uso: Aumenta un 15% la celeridad de todos los miembros del grupo y banda. Dura 40 s.\n\n Los aliados que reciban este efecto quedarán Agotados y no podrán beneficiarse de Ansia de sangre, Heroísmo o Distorsión temporal nuevamente durante 10 min.\n\n No afecta a los aliados con nivel superior a 50. (2 Min Reutilización)\nPrecio de venta:\nRequiere Cuero de petrapiel (8), Garra intacta (3), Diente intacto (3)"}
MultiLanguageItemData['mx'][142409] = {name = "Patrón: Tambores de la montaña", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer unos Tambores de la montaña.\n[q2]Reduce significativamente la cantidad de materiales necesarios para crear unos Tambores de la montaña.\nRequiere Peletería de Legion (1)\nRequiereTribu Altamontaña\n: Exaltado\nPrecio de venta: \n[q2]Tambores de la montaña\n[q2]Uso: Aumenta un 15% la celeridad de todos los miembros del grupo y banda. Dura 40 s.\n\n Los aliados que reciban este efecto quedarán Agotados y no podrán beneficiarse de Ansia de sangre, Heroísmo o Distorsión temporal nuevamente durante 10 min.\n\n No afecta a los aliados con nivel superior a 50. (2 Min Reutilización)\nPrecio de venta:\nRequiere Cuero de petrapiel (5), Garra intacta (2), Diente intacto (2)"}
