MultiLanguageItemData['mx'][143750] = {name = "Glifo de Brote crepuscular", additional_info = "Clases: Druida\n[q2]Uso: Te enseña permanentemente este glifo.\n\nModifica tu Flor de vida para que parezca una gran flor crepuscular.\nPrecio de venta:"}
MultiLanguageItemData['mx'][143751] = {name = "Técnica: Glifo de Brote crepuscular", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar un Glifo de Brote crepuscular.\n[q2]Fabrica un glifo de Brote crepuscular.\nRequiere Inscripción de Legion (1)\nPrecio de venta: \nGlifo de Brote crepuscular\nClases: Druida\n[q2]Uso: Te enseña permanentemente este glifo.\n\nModifica tu Flor de vida para que parezca una gran flor crepuscular.\nPrecio de venta:\nRequiere Papiro ligero , Pigmento cetrino (4), Pigmento róseo (60)"}
MultiLanguageItemData['mx'][143752] = {name = "Montura de prueba de sonido", additional_info = "[q4]Montura de prueba de sonido\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar la montura de prueba de sonido.\n[q2]Invoca y retira a tu Lobo temible mag'har.\nRequiere nivel 1 - 80 ( 80)\nPrecio de venta:\n[q]\"Originarios de Draenor, estos lobos son los preferidos de los Mag'har debido a su ferocidad y su lealtad, y también porque siempre es bueno tener algo suave para abrazar en las frías noches de invierno.\"\nLogro:\nRazas aliadas: Orco mag'har"}
MultiLanguageItemData['mx'][143753] = {name = "Suministros para mascotas mojados", additional_info = "Se liga al recogerlo\n[q2]Uso: Abre la bolsa.\n[q]\"Por lo general contienen unos pocos vendajes para mascotas y algunos talismanes de mascotas, pero de vez en cuando pueden incluir una mascota especial.\""}
MultiLanguageItemData['mx'][143754] = {name = "[q2]Mocasín cavernoso", additional_info = "[q2]Uso: Te enseña a invocar y retirar a este compañero.\n[q2]Haz clic con el botón derecho para invocar y retirar a un Mocasín cavernoso.\nRequiere nivel 1 - 80 ( 80)"}
