MultiLanguageItemData['mx'][143757] = {name = "[q0]Celada del Consejo de la Sombra", additional_info = "Se liga al recogerlo\n[q]\"A la cabeza del Bastón de Gul'dan, la celada es el símbolo del Consejo de la Sombra. Fue un poderoso instrumento en manos de Gul'dan y sus maestros de la Legión, con una profunda conexión con las Tierras de las Sombras.\"\nPrecio de venta:"}
