MultiLanguageItemData['mx'][144279] = {name = "[q5]Delirios de grandeza", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Hombro} {Cuero}\n6 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 120 / 120\nClases: Cazador de Demonios\n[q2]Equipar: El tiempo de reutilización restante de Metamorfosis se reduce 1 s por cada 30 p. de Furia que gastes.\n[q]\"Gran poder... a cualquier costo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][144280] = {name = "[q5]Marcha mortal", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cabeza} {Placas}\n13 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 120 / 120\nClases: Caballero de la muerte\n[q2]Equipar: Golpe letal y Espiral de la muerte infligen un 10% más de daño y reducen 2.0 s el tiempo de reutilización restante de [ Profanar / Muerte y descomposición].\n[q]\"En este mundo, nada es tan inexorable como la muerte.\"\nPrecio de venta:"}
