MultiLanguageItemData['mx'][151703] = {name = "Receta: Lágrimas de los Naaru", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer las lágrimas de los Naaru.\n[q2]Crea lágrimas de los Naaru.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nLágrimas de los Naaru\n[q2]Uso: Muestra la ubicación de demonios cercanos en el minimapa durante 30 min. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Gloria astral (20), Sargerita primigenia , Vial de cristal"}
MultiLanguageItemData['mx'][151704] = {name = "Receta: Lágrimas de los Naaru", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer las lágrimas de los Naaru de manera más eficiente.\n[q2]Crea lágrimas de los Naaru de manera más eficiente\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nLágrimas de los Naaru\n[q2]Uso: Muestra la ubicación de demonios cercanos en el minimapa durante 30 min. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Gloria astral (15), Vial de cristal"}
MultiLanguageItemData['mx'][151705] = {name = "Receta: Lágrimas de los Naaru", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a crear las lágrimas de los Naaru de manera aún más eficiente, con una probabilidad de crear varias pociones.\n[q2]Probabilidad de crear varias pociones.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nLágrimas de los Naaru\n[q2]Uso: Muestra la ubicación de demonios cercanos en el minimapa durante 30 min. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Gloria astral (10), Vial de cristal"}
MultiLanguageItemData['mx'][151706] = {name = "Receta: Piedra de alquimista astral", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una piedra de alquimista astral.\n[q2]Crea una piedra de alquimista astral.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \n[q4]Piedra de alquimista astral\nSe liga al equiparlo\nÚnico-Equipado\nAbalorio\n[q2]+ 7 Versatilidad\n[q2]Equipar: Cuando sanas o infliges daño tienes la probabilidad de aumentar tu fuerza, agilidad o intelecto 19 p. durante 15 s. Siempre se elige la estadística más elevada.\n[q2]Equipar: Aumenta el efecto de las pociones de sanación y maná en su portador en un 40%. Este efecto no se acumula.\nRequiere Alquimia de Legion (1)\n[q]\"Puede usarse para transmutar en lugar de una piedra filosofal.\"\nPrecio de venta: \nRequiere Gloria astral (75), Piedra de alquimista infernal , Sargerita primigenia (5)"}
MultiLanguageItemData['mx'][151707] = {name = "Receta: Piedra de alquimista astral", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una piedra de alquimista astral de manera más eficiente.\n[q2]Crea una piedra de alquimista astral de manera más eficiente.\nRequiere Alquimia de Legion (1)\nRequiereDominio argusiano\n: Reverenciado\nPrecio de venta: \n[q4]Piedra de alquimista astral\nSe liga al equiparlo\nÚnico-Equipado\nAbalorio\n[q2]+ 7 Versatilidad\n[q2]Equipar: Cuando sanas o infliges daño tienes la probabilidad de aumentar tu fuerza, agilidad o intelecto 19 p. durante 15 s. Siempre se elige la estadística más elevada.\n[q2]Equipar: Aumenta el efecto de las pociones de sanación y maná en su portador en un 40%. Este efecto no se acumula.\nRequiere Alquimia de Legion (1)\n[q]\"Puede usarse para transmutar en lugar de una piedra filosofal.\"\nPrecio de venta: \nRequiere Gloria astral (60), Piedra de alquimista infernal , Sargerita primigenia (4)"}
MultiLanguageItemData['mx'][151708] = {name = "Receta: Piedra de alquimista astral", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una piedra de alquimista astral con mucha más eficiencia.\n[q2]Crea una piedra de alquimista astral de manera incluso más eficiente.\nRequiere Alquimia de Legion (1)\nRequiereDominio argusiano\n: Exaltado\nPrecio de venta: \n[q4]Piedra de alquimista astral\nSe liga al equiparlo\nÚnico-Equipado\nAbalorio\n[q2]+ 7 Versatilidad\n[q2]Equipar: Cuando sanas o infliges daño tienes la probabilidad de aumentar tu fuerza, agilidad o intelecto 19 p. durante 15 s. Siempre se elige la estadística más elevada.\n[q2]Equipar: Aumenta el efecto de las pociones de sanación y maná en su portador en un 40%. Este efecto no se acumula.\nRequiere Alquimia de Legion (1)\n[q]\"Puede usarse para transmutar en lugar de una piedra filosofal.\"\nPrecio de venta: \nRequiere Gloria astral (50), Piedra de alquimista infernal , Sargerita primigenia (3)"}
MultiLanguageItemData['mx'][151709] = {name = "Diseño: Ancla de laja vil", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer a hacer un ancla de laja vil.\n[q2]Fabrica un ancla de laja vil.\nRequiere Herrería de Legion (1)\n\n\nAncla de laja vil\n[q2]Uso: Ata un ancla a tus pies que te envía directamente al fondo del océano. Solo puede usarse en el agua. (30 Seg Reutilización)\nRequiere Laja vil (50)"}
MultiLanguageItemData['mx'][151710] = {name = "Receta: Transmutar sargerita primigenia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a transmutar la sangre de Sargeras a sargerita primigenia.\n[q2]Transmutar sangre de Sargeras en sargerita primigenia.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \n[q3]Sargerita primigenia\nSe liga al recogerlo\nMaterial de profesión\n[q]\"Puede usarse en la creación de objetos comerciales o bien entregarse al comerciante Caelen en la foja de obliterium de Dalaran.\"\nPrecio de venta: \nRequiere Sangre de Sargeras (25)"}
