MultiLanguageItemData['mx'][151811] = {name = "[q5]Viento incesante", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cabeza} {Cuero}\n6 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 120 / 120\nClases: Monje\n[q2]Equipar: Aumenta un 3% el daño infligido.\n[q2]Equipar: Reduce un 20% el tiempo de reutilización de Golpe del Señor del viento y tu siguiente Patada oscura no cuesta chi. (1s de reutilización)\n[q]\"El sol se alza, el viento sopla y los poderosos caen.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151812] = {name = "[q5]Pilares de la luz recóndita", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Hombro} {Placas}\n12 armadura\n+4 [Fuerza o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 120 / 120\nClases: Paladín\n[q2]Equipar: El tiempo de reutilización de Defensor candente se reduce un 25%.\n[q2]Equipar: Ojo de Tyr inflige un 300% más de daño y su tiempo de reutilización se reduce un 25%.\n[q]\"La luz brilla más fuerte en aquellos a quienes consume.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151813] = {name = "[q5]Expurgación del Inquisidor Escarlata", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Placas}\n18 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 200 / 200\nClases: Paladín\n[q2]Equipar: Cada 2 s, el daño de tu siguiente Tormenta divina aumenta un 6%. Se acumula hasta 30 veces.\n[q]\"¿No lo ven, hermanos y hermanas? Solo hay una manera de erradicar a la Plaga de la superficie de Azeroth.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151814] = {name = "[q5]Corazón del vacío", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Tela}\n5 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de celeridad + 5 p.\nDurabilidad 200 / 200\nClases: Sacerdote\n[q2]Equipar: Erupción del vacío inflige un 75% más de daño y te sana por un 25% del daño infligido.\n[q]\"El Vacío no carece de contenido. Está lleno de malicia, desesperación y muerte.\"\nPrecio de venta:"}
