MultiLanguageItemData['mx'][151817] = {name = "[q5]Maldición de la inquietud", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nEspalda\n3 armadura\n+3 agilidad\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nClases: Pícaro\n[q2]Equipar: Hojas inquietas reduce el tiempo de reutilización de Subidón de adrenalina 0.5 s más por punto de combo gastado.\n[q2]Equipar: Hojas inquietas reduce el tiempo de reutilización de Maldición de los Filos del terror 0.25 s por punto de combo gastado.\n[q]\"Enseguida nos ponemos inquietos. Necesitamos hacer algo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151818] = {name = "[q5]El muerto primigenio", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Manos} {Cuero}\n5 armadura\n+4 agilidad\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 70 / 70\nClases: Pícaro\n[q2]Equipar: Durante 2 s después de activar Símbolos de la muerte, Golpesombra genera 3 puntos de combo adicionales y Puñalada genera 4 puntos de combo adicionales. (500ms de reutilización)\n[q]\"Al final la muerte nos llega a todos...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151819] = {name = "[q5]Corazón abrasador", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Manos} {Malla}\n7 armadura\n+4 [Agilidad o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 70 / 70\nClases: Chamán\n[q2]Equipar: Tienes un [ Golpe de tormenta : 0.12% / 0.10%] de probabilidad por punto de Vorágine utilizado de obtener Ascensión durante 10 s.\n[q]\"La esencia de miles de elementales ardientes se encuentra infundida en estos guantes, pero extrañamente se sienten fríos al tacto.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151821] = {name = "[q5]Cosechador maestro", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Tela}\n5 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 200 / 200\nClases: Brujo\n[q2]Equipar: Demonología\n Cada fragmento de alma que gastas tiene un 3% de probabilidad de otorgarte Cosecha de almas durante 8 s.\n\nDestrucción\n Cada fragmento de alma que gastas tiene un 6% de probabilidad de otorgarte Cosecha de almas durante 8 s.\n\nAflicción\n Cada fragmento de alma que gastas tiene un 9% de probabilidad de otorgarte Cosecha de almas durante 8 s.\n[q]\"Las almas más fuertes son producto del sufrimiento.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151822] = {name = "[q5]Espejo de sangre de Ararat", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Piernas} {Placas}\n16 armadura\n+5 fuerza\n+7 aguante\n[q2]+ 5 Versatilidad\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 145 / 145\nClases: Guerrero\n[q2]Equipar: Bloquear con escudo y Reflejo de hechizos obtienen 1 cargas más.\n[q]\"Su sangre, derramada por dragones, dioses y demonios, imbuye el acero reluciente. Incansable, protege a sus amigos incluso desde el más allá.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151823] = {name = "[q5]El ojo de la gran tormenta", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cabeza} {Placas}\n13 armadura\n+5 fuerza\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 120 / 120\nClases: Guerrero\n[q2]Equipar: Filotormenta aumenta un 10% tu velocidad de movimiento y un 2% el daño que infliges durante 6 s, aumenta periódicamente y se acumula hasta 6 veces.\n[q]\"En el ojo del tornado, no hay arriba ni abajo, no hay suelo ni cielo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151824] = {name = "[q5]Rabiosos valarjar", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Piernas} {Placas}\n16 armadura\n+5 fuerza\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 6 p.\nDurabilidad 145 / 145\nClases: Guerrero\n[q2]Equipar: El golpe crítico de Desenfreno contra el objetivo principal genera 6 p. de ira.\n[q]\"No son famosos por su sutileza.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][151825] = {name = "[q2]Cuerno de Hatuun", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Invoca acechacrestas krokul desde las sombras para que te ayuden en la batalla. (30 Seg Reutilización)\n[q]\"Que el llamado de la batalla resuene. ¡Luchamos como uno!\""}
