MultiLanguageItemData['mx'][152559] = {name = "Poción de muerte resucitada", additional_info = "[q2]Uso: Te potencia con magia de las sombras durante 25 s para que tus habilidades que infligen daño a distancia tengan una probabilidad de lanzar una descarga mortal que se vuelve más intensa con la distancia que recorre e inflige hasta 331209 p. de daño de las sombras. (5 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][152560] = {name = "Poción de sangre explosiva", additional_info = "[q2]Uso: Insufla tu sangre con calor durante 25 s para que tus ataques cuerpo a cuerpo tengan la probabilidad de crear una explosión de sangre que inflige 5371 p. de daño físico, dividido de forma equitativa entre todos los enemigos cercanos. (5 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][152561] = {name = "Poción de reposición", additional_info = "[q2]Uso: Hace que quien lo ingiera entre en un estado de concentración elevada en el que puede restaurar hasta ( 601 * 10) p. de maná durante 10 s, pero está indefenso hasta que se rompa la concentración. (5 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][152564] = {name = "Festín de pescado", additional_info = "[q2]Uso: ¡Prepara un festín de pescado para alimentar hasta 50 personas en tu banda o grupo!\n\n Restaura 28846 p. de salud y 14423 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos obtendrás todos los poderes de un pez.\nPrecio de venta:"}
MultiLanguageItemData['mx'][152565] = {name = "Receta: Festín de pescado", additional_info = "Rango 1\nSe liga al recogerlo\n[q2]Uso: Te enseña a preparar un Festín de pescado.\n[q2]Prepara un festín de pescado.\nRequiere Cocina de Legion (1)\nRequiere ser buen amigo de la Guardiana Raynae\nPrecio de venta:\nFestín de pescado\n[q2]Uso: ¡Prepara un festín de pescado para alimentar hasta 50 personas en tu banda o grupo!\n\n Restaura 28846 p. de salud y 14423 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos obtendrás todos los poderes de un pez.\nPrecio de venta:\nRequiere Pez reina maldito , Perca branquiamusgo , Salmón de Altamontaña , Rayatormenta , Koi de escamas rúnicas , Barracuda negra"}
