MultiLanguageItemData['mx'][153485] = {name = "[q4]Dirigible de la Luna Negra", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Haz clic derecho para invocar y retirar a tu Dirigible de la Luna Negra. Esta montura cambia según tu ubicación y el nivel de tu habilidad de montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Silas pensó en usar su flota de zepelines para hacer publicidad, pero finalmente decidió que venderlos en persona era toda la publicidad que necesitaba.\"\nVendedora:\nLhara\nZona:\nIsla Luna Negra\nCosto:\n1000"}
MultiLanguageItemData['mx'][153486] = {name = "Púa venenosa intacta", additional_info = "Objeto de misión\n[q]\"Se usan con los arpones equilibrados para aturdir a las presas de gran tamaño.\""}
MultiLanguageItemData['mx'][153487] = {name = "Granada de descombobulación orgánica", additional_info = "[q2]Uso: Arroja una bomba que al detonar invoca a 5 ovejas mecánicas. Los enemigos que entren en contacto con las ovejas quedarán polimorfados durante 20 s. No funciona contra objetivos de nivel superior a 50. (1 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][153490] = {name = "F.R.I.T.O.", additional_info = "[q2]Uso: Inflige 4180 p. de daño de fuego a todos los enemigos que están en un radio de 5 m. (5 Min Reutilización)\n[q]\"Fabricación de refracción ígnea termofísica y oscilante. NO APTO para cocinar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][153493] = {name = "[q4]Dragón de tormenta del Gladiador demoníaco", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a un Dragón de tormenta del Gladiador demoníaco.\n[q2]Invoca y retira a tu Dragón de tormenta del Gladiador demoníaco .\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta criatura nacida en las montañas de Stormheim es una temible fusión de tormenta y escamas, capaz de iluminar el cielo con sus llamas en busca de su presa.\"\nLogro:\nGladiador: Legion, temporada 7\nCategoría:\nJugador contra Jugador"}
MultiLanguageItemData['mx'][153494] = {name = "Propagador de peste termoacelerado", additional_info = "[q2]Uso: Crea un área de veneno que inflige 1003 p. de daño a los enemigos en su interior cada 3 s. Dura 15 s. (5 Min Reutilización)"}
