MultiLanguageItemData['mx'][155820] = {name = "[q2]Bombaespín", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Lanza un explosivo cargado con púas de jabaespín a la ubicación objetivo que inflige 3775 p. de daño físico a todos los enemigos que estén en un radio de 10 m y los aturde durante 3 s s. (2 Min Reutilización)\n[q]\"Repleta de púas de jabaespín.\""}
MultiLanguageItemData['mx'][155821] = {name = "[q2]Vial de baba viscosa", additional_info = "Se liga al recogerlo\n[q2]Uso: Te cubres con una baba viscosa que debilita el efecto de las púas empaladoras que usan los jabaespines espinafilada.\n[q]\"Miel mezclada con una combinación especial de ungüentos y aceites. ¡Todavía desprende un aroma dulce!\""}
