MultiLanguageItemData['mx'][163573] = {name = "[q4]Riendas de Crináurea", additional_info = "Único\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a Crináurea.\n[q2]Invoca y retira a Crináurea.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Lord Canto Tormenta codiciaba la maravillosa crin dorada de este caballo, así que ordenó a sus súbditos que lo robaran de la Finca Norwington de Tiragarde.\"\nZona:\nCanto Tormenta"}
MultiLanguageItemData['mx'][163574] = {name = "[q4]Riendas masticadas de la mula de carga aterrorizada", additional_info = "Único\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a una mula de carga aterrorizada.\n[q2]Invoca y retira a tu mula de carga aterrorizada.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Esta pobre mula estaba en Drustvar cuando las brujas se apoderaron de la zona. Ha visto demasiado.\"\nZona:\nDrustvar"}
MultiLanguageItemData['mx'][163575] = {name = "[q4]Riendas de un tragasangre domado", additional_info = "Único\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un buscavenas saltador.\n[q2]Invoca y retira a tu buscavenas saltador.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"No bastará con insecticida y una máscara para sobrevivir a los pantanos de Nazmir. ¡Lleva un garrote!\"\nZona:\nNazmir"}
MultiLanguageItemData['mx'][163576] = {name = "[q4]Carroñero de las dunas capturado", additional_info = "Único\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a un carroñero de las dunas.\n[q2]Invoca y retira a tu carroñero de las dunas.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Estos carroñeros resistentes pueden sobrevivir meses enteros en los páramos de Vol'dun con poquísima agua y comida.\"\nZona:\nVol'dun"}
