MultiLanguageItemData['mx'][163744] = {name = "[q3]Frescura de Ira Helada", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: Invoca una nevada ligera. (10 Min Reutilización)\n[q]\"Kor'gresh tenía esto guardado... en algún lugar.\""}
