MultiLanguageItemData['mx'][163753] = {name = "Blindaje de Forjahonda", additional_info = "[q7]Se liga a la tropa\nÚnico (5)\n[q2]Uso: Aplica el blindaje a tu armadura para reducir un 30% el daño físico recibido durante 10 min.\n\n Solo puede utilizarse en Expediciones insulares. (1 Min Reutilización)"}
