MultiLanguageItemData['mx'][168436] = {name = "[q6]Punta de estrella concentrada", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Espíritu de preservación en tu Corazón de Azeroth.\nPoder principal:\n Espíritu de preservación\nAlcance de 40 m Canalizado (Hechizo de 3 seg) 1 min de reutilización Canaliza un haz de energía sobre un aliado que lo sana por [( 1452 * (5) + 1452 ) * (1 + Versatilidad)] p. durante 3 s. \n Poder secundario:\n Espíritu devoto\nCada 5 s, obtienes Espíritu devoto, que hace que tu siguiente Sanación veloz sane 153 p. adicionales y se acumule hasta 3 veces.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][168439] = {name = "[q6]Polvo estelar espiralado", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Espíritu de preservación en tu Corazón de Azeroth.\nPoder principal:\n Espíritu de preservación\nAlcance de 40 m Canalizado (Hechizo de 3 seg) 1 min de reutilización Canaliza un haz de energía sobre un aliado que lo sana por [( 1452 * (5) + 1452 ) * (1 + Versatilidad)] p. durante 3 s. Hasta 6 aliados más que se encuentran en el haz también recuperan [ 145 * (1 + Versatilidad)] p. de salud cada 0.6 s. \n Poder secundario:\n Espíritu devoto\nCada 5 s, obtienes Espíritu devoto, que hace que tu siguiente Sanación veloz sane 153 p. adicionales y se acumule hasta 5 veces.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][168440] = {name = "[q6]Fragmento de estrella resplandeciente", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Espíritu de preservación en tu Corazón de Azeroth.\nAprende cualquier esencia de los Rajani o del Acuerdo de Uldum (rango 3) con otro personaje para desbloquear esta esencia.\nRequiere la reputación Venerado con los Rajani. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Espíritu de preservación\nAlcance de 40 m Canalizado (Hechizo de 3 seg) 1 min de reutilización Canaliza un haz de energía sobre un aliado que lo sana por [( 1452 * (5) + 1452 ) * (1 + Versatilidad)] p. durante 3 s. Hasta 6 aliados más que se encuentran en el haz también recuperan [ 145 * (1 + Versatilidad)] p. de salud cada 0.6 s.\n\n Cada vez que Espíritu de preservación sana al objetivo principal, obtienes una acumulación de Espíritu devoto. \n Poder secundario:\n Espíritu devoto\nCada 5 s, obtienes Espíritu devoto, que hace que tu siguiente Sanación veloz sane 153 p. adicionales y seacumule hasta 5 veces.\n\n Cada acumulación de Espíritu devoto que consumes aumenta la probabilidad de golpe crítico de tu siguiente Sanación veloz dentro de 15 s un 20%.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][168442] = {name = "[q6]Sangre turbia de los aniquilados", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Sangre del enemigo en tu Corazón de Azeroth.\nPoder principal:\n Sangre del enemigo\nInstante 2 min de reutilización El Corazón de Azeroth hace erupción violentamente e inflige 1739 p. de daño de las sombras a los enemigos en un radio de 12 m. Obtienes un 25% de probabilidad de golpe crítico contra los objetivos durante 10 s . \n Poder secundario:\n Bañado en sangre\nTus golpes críticos con hechizos y habilidades otorgan una acumulación de Bañado en sangre . Cuando consigues 40 acumulaciones, obtienes 125 p. de celeridad durante 8 s."}
MultiLanguageItemData['mx'][168443] = {name = "[q6]Sangre agitada de los dominados", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Sangre del enemigo en tu Corazón de Azeroth.\nRequiere el logro \"Camorrista del campo de batalla\". (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Sangre del enemigo\nInstante 1.5 min de reutilización El Corazón de Azeroth hace erupción violentamente e inflige 1739 p. de daño de las sombras a los enemigos en un radio de 12 m. Obtienes un 25% de probabilidad de golpe crítico contra los objetivos durante 10 s. \n Poder secundario:\n Bañado en sangre\nTus golpes críticos con hechizos y habilidades otorgan una acumulación de Bañado en sangre. Cuando tienes 40 acumulaciones, obtienes 125 p. de celeridad durante 8 s.\n\n Cada acumulación de Bañado en sangre otorga 2 p. de golpe crítico."}
MultiLanguageItemData['mx'][168444] = {name = "[q6]Sangre revuelta de los conquistados", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Sangre del enemigo en tu Corazón de Azeroth.\nRequiere el logro \"Estratega del campo de batalla\". (No se puede comprar si ya lo aprendiste).\nAprende Sangre del enemigo, Artificio del tiempo o Esfera de supresión (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Sangre del enemigo\nInstante 1.5 min de reutilización El Corazón de Azeroth hace erupción violentamente e inflige 1739 p. de daño de las sombras a los enemigos en un radio de 12 m. Obtienes un 25% de probabilidad de golpe crítico contra los objetivos durante 10 s. Aumenta tu daño de golpe crítico un 25% durante 5 s. \n Poder secundario:\n Bañado en sangre\nTus golpes críticos con hechizos y habilidades otorgan una acumulación de Bañado en sangre, lo que aumenta 2 p. el daño crítico. Cuando consigues 40 acumulaciones, obtienes 125 p. de celeridad durante 8 s.\n\n Bañado en sangre tiene un 25% de probabilidad de consumir solamente 30 acumulaciones."}
