MultiLanguageItemData['mx'][168536] = {name = "[q6]Formación de azerita recristalizante", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Dádiva imperecedera de Azeroth en tu Corazón de Azeroth.\nPoder principal:\n Dádiva imperecedera de Azeroth\nInstante 45 seg de reutilización Reduce todo el daño que recibes un 20% durante 4 s. \n Poder secundario:\n Azerita endurecida\nCuando tu salud cae por debajo del 35%, obtienes 799 p. de armadura durante 8 s.\n\n Este efecto solo puede ocurrir una vez cada 120 s. (2.5m de reutilización)"}
MultiLanguageItemData['mx'][168537] = {name = "[q6]Formación de azerita templada", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Dádiva imperecedera de Azeroth en tu Corazón de Azeroth.\nAprende Fuerza vital condensada, Conducto de vitalidad o Dádiva imperecedera de Azeroth (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Dádiva imperecedera de Azeroth\nInstante 45 seg de reutilización Reduce todo el daño que recibes un 40% durante 2 s, y luego un 20% durante los 2 s siguientes. \n Poder secundario:\n Azerita endurecida\nCuando tu salud cae por debajo del 35%, obtienes ( 799 * 200 / 100) p. de armadura durante 4 s, y luego 799 p. de armadura durante los 4 s siguientes.\n\n Este efecto solo puede ocurrir una vez cada 120 s. (2.5m de reutilización)"}
