MultiLanguageItemData['mx'][168558] = {name = "[q6]Fetiche de los calabozos profundos", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Ánima de vida y muerte en tu Corazón de Azeroth.\nPoder principal:\n Ánima de muerte\nInstante 2 min de reutilización Recurres a tu propia vitalidad para abrasar a tus enemigos e infligir un 10% de tu salud máxima como daño de fuego a todos los enemigos cercanos. Sanas un 5% de tu salud máxima por cada enemigo que golpeas, hasta un máximo de un 25% de tu salud máxima. \n Poder secundario:\n Ánima de vida\nUn torrente de energía de azerita te corre por las venas, aumenta 244 p. tu salud máxima cada 5 s y se acumula hasta 10 veces.\n\n Obtienes una acumulación de Ánima de vida cuando matas a un enemigo que otorga experiencia u honor.\n\n Este efecto se pierde si tu salud cae por debajo del 35%."}
MultiLanguageItemData['mx'][168559] = {name = "[q6]Fetiche de los laberintos ocultos", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Ánima de vida y muerte en tu Corazón de Azeroth.\nAprende Iris de enfoque, Invocación de la Protectora o Ánima de vida y muerte (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Ánima de muerte\nInstante 2 min de reutilización Recurres a tu propia vitalidad para abrasar a tus enemigos e infligir un 10% de tu salud máxima como daño de fuego a todos los enemigos cercanos. Sanas un 10% de tu salud máxima por cada enemigo que golpeas, hasta un máximo de un 50% de tu salud máxima. \n Poder secundario:\n Ánima de vida\nUn torrente de energía de azerita te corre por las venas, aumenta 244 p. tu salud máxima cada 5 s y se acumula hasta 10 veces. Cuando alcanzas el máximo de acumulaciones, sanas 185 p. de salud cada 5 s.\n\n Obtienes una acumulación de Ánima de vida cuando matas a un enemigo que otorga experiencia u honor.\n\n Este efecto se pierde si tu salud cae por debajo del 35%."}
MultiLanguageItemData['mx'][168560] = {name = "[q6]Fetiche de las catacumbas doradas", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Ánima de vida y muerte en tu Corazón de Azeroth.\nPoder principal:\n Ánima de muerte\nInstante 2 min de reutilización Recurres a tu propia vitalidad para abrasar a tus enemigos e infligir un 10% de tu salud máxima como daño de fuego a todos los enemigos cercanos. Sanas un 10% de tu salud máxima por cada enemigo que golpeas, hasta un máximo de un 50% de tu salud máxima. \n Poder secundario:\n Ánima de vida\nUn torrente de energía de azerita te corre por las venas, aumenta 244 p. tu salud máxima cada 5 s y se acumula hasta 10 veces. Cuando alcanzas el máximo de acumulaciones, sanas 185 p. de salud cada 5 s.\n\n Obtienes una acumulación de Ánima de vida cuando matas a un enemigo que otorga experiencia u honor.\n\n Este efecto se pierde si tu salud cae por debajo del 35%."}
MultiLanguageItemData['mx'][168566] = {name = "[q6]Unidad de enfriamiento de fuerza nula", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Dínamo de anulación en tu Corazón de Azeroth.\nRequiere la reputación Honorable con la Resistencia de Pernoxidado. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Barrera nulificadora potenciada\nInstante 2.25 min de reutilización Otorga una Barrera nulificadora potenciada que absorbe [ 11391 * (1 + Versatilidad)] p. de daño mágico durante 10 s. \n Poder secundario:\n Barrera nulificadora\nCada 15 s, obtienes una Barrera nulificadora que absorberá los próximos [ 2268 * (1 + Versatilidad)] p. de daño mágico que recibas durante 10 s."}
MultiLanguageItemData['mx'][168568] = {name = "[q6]Nulificador de fuerza nula", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Dínamo de anulación en tu Corazón de Azeroth.\nRequiere la reputación Venerado con la Resistencia de Pernoxidado. (No se puede comprar si ya lo aprendiste).\nAprende cualquier esencia de rango 3 de la Resistencia de Pernoxidado con otro personaje para desbloquear esta esencia.\nPoder principal:\n Barrera nulificadora potenciada\nInstante 2.25 min de reutilización Obtienes una Barrera nulificadora potenciada que absorbe [ 11391 * (1 + Versatilidad)] p. de daño mágico durante 10 s y elimina al instante todos los efectos dañinos de magia, maldición, veneno y enfermedad que tengas. \n Poder secundario:\n Barrera nulificadora\nCada 15 s, obtienes una Barrera nulificadora que absorberá los próximos [ 2268 * (1 + Versatilidad)] p. de daño mágico que recibas durante 10 s.\n\n Cuando Barrera nulificadora expira, implosiona e inflige daño de las sombras equivalente al monto total absorbido, dividido entre todos los enemigos cercanos."}
MultiLanguageItemData['mx'][168569] = {name = "[q6]Visualizador de fuerza nula", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Dínamo de anulación en tu Corazón de Azeroth.\nPoder principal:\n Barrera nulificadora potenciada\nInstante 2.25 min de reutilización Obtienes una Barrera nulificadora potenciada que absorbe [ 11391 * (1 + Versatilidad)] p. de daño mágico durante 10 s y elimina al instante todos los efectos dañinos de magia, maldición, veneno y enfermedad que tengas. \n Poder secundario:\n Barrera nulificadora\nCada 15 s, obtienes una Barrera nulificadora que absorberá los próximos [ 2268 * (1 + Versatilidad)] p. de daño mágico que recibas durante 10 s.\n\n Cuando Barrera nulificadora expira, implosiona e inflige daño de las sombras equivalente al monto total absorbido, dividido entre todos los enemigos cercanos."}
MultiLanguageItemData['mx'][168573] = {name = "[q6]Hoja resistente a la muerte", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Toque de la eternidad en tu Corazón de Azeroth.\nPoder principal:\n Toque de la eternidad\nEvita tu próxima muerte y, en cambio, regeneras un 20% de tu salud máxima y recibes un 85% menos de daño durante 3 s.\n\n No puede ocurrir más de una vez cada 10 min. \n Poder secundario:\n Voluntad de sobrevivir\nCuando tu salud se reduce por debajo de un 35%, obtienes 55 p. de evasión durante 15 s y tu próximo lanzamiento de Mitigación activa dura un 30% más . Esto solo puede ocurrir una vez cada 1.5 min.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción.\n[q]\"Florece al viento.\""}
MultiLanguageItemData['mx'][168574] = {name = "[q6]Corteza viva petrificada", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Toque de la eternidad en tu Corazón de Azeroth.\nPoder principal:\n Toque de la eternidad\nEvita tu próxima muerte y, en cambio, regeneras un 40% de tu salud máxima y recibes un 85% menos de daño durante 3 s.\n\n No puede ocurrir más de una vez cada 10 min. \n Poder secundario:\n Voluntad de sobrevivir\nCuando tu salud se reduce por debajo de un 35%, obtienes 55 p. de evasión durante 15 s y tu próximo lanzamiento de Mitigación activa dura un 30% más . Esto solo puede ocurrir una vez cada 60 s.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][168575] = {name = "[q6]Rama de anillos rejuvenecedores", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Toque de la eternidad en tu Corazón de Azeroth.\nAprende cualquier esencia de los Rajani o del Acuerdo de Uldum (rango 3) con otro personaje para desbloquear esta esencia.\nRequiere la reputación Venerado con los Rajani. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Toque de la eternidad\nEvita tu próxima muerte y, en cambio, regeneras un 40% de tu salud máxima y recibes un 85% menos de daño durante 3 s.\n\n Cuando evitas la muerte, se restablece el tiempo de reutilización de Muro de escudo .\n\n No puede ocurrir más de una vez cada 10 min. \n Poder secundario:\n Voluntad de sobrevivir\nCuando tu salud se reduce por debajo de un 35%, obtienes 55 p. de evasión durante 15 s y tu próximo lanzamiento de Mitigación activa durará un 50% más . Esto solo puede ocurrir una vez cada 60 s.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][168576] = {name = "[q6]Raíces de renacimiento magnífico", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Toque de la eternidad en tu Corazón de Azeroth.\nPoder principal:\n Toque de la eternidad\nEvita tu próxima muerte y, en cambio, regeneras un 40% de tu salud máxima y recibes un 85% menos de daño durante 3 s.\n\n Cuando evitas la muerte, se restablece el tiempo de reutilización de Muro de escudo .\n\n No puede ocurrir más de una vez cada 10 min. \n Poder secundario:\n Voluntad de sobrevivir\nCuando tu salud se reduce por debajo de un 35%, obtienes 55 p. de evasión durante 15 s y tu próximo lanzamiento de Mitigación activa durará un 50% más . Esto solo puede ocurrir una vez cada 60 s.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
