MultiLanguageItemData['mx'][168578] = {name = "[q6]Esfera de fuerza reprimida", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Esfera de supresión en tu Corazón de Azeroth.\nPoder principal:\n Pulso de supresión\nInstante 1 min de reutilización Libera un pulso potente de energía supresora que reduce un 70% la velocidad de movimiento de todos los enemigos en un radio de 15 m y reduce un 25% su velocidad de ataque durante 8 s. \n Poder secundario:\n Esfera de supresión\nRango ilimitado Cuando un enemigo te ataca cuerpo a cuerpo, su velocidad de movimiento se reduce un 30% y obtienes 64 p. de celeridad durante 5 s."}
MultiLanguageItemData['mx'][168579] = {name = "[q6]Esfera de furia desatada", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Esfera de supresión en tu Corazón de Azeroth.\nRequiere el logro \"Camorrista del campo de batalla\". (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Pulso de supresión\nInstante 45 seg de reutilización Libera un pulso potente de energía supresora que reduce un 70% la velocidad de movimiento de todos los enemigos en un radio de 15 m y reduce un 25% su velocidad de ataque durante 8 s. \n Poder secundario:\n Esfera de supresión\nRango ilimitado Cuando un enemigo te ataca cuerpo a cuerpo, su velocidad de movimiento se reduce un 30% y obtienes 64 p. de celeridad durante 7 s ."}
MultiLanguageItemData['mx'][168580] = {name = "[q6]Esfera de movilidad drenada", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Esfera de supresión en tu Corazón de Azeroth.\nRequiere el logro \"Estratega del campo de batalla\". (No se puede comprar si ya lo aprendiste).\nAprende Sangre del enemigo, Artificio del tiempo o Esfera de supresión (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Pulso de supresión\nInstante 45 seg de reutilización Libera un pulso potente de energía supresora que reduce un 70% la velocidad de movimiento de todos los enemigos en un radio de 15 m y reduce un 25% su velocidad de ataque durante 8 s.\n\n Si golpeas a un enemigo, obtienes un 50% de velocidad de movimiento durante 8 s. \n Poder secundario:\n Esfera de supresión\nRango ilimitado Cuando un enemigo te ataca cuerpo a cuerpo, su velocidad de movimiento se reduce un 30% y obtienes 64 p. de celeridad y velocidad durante 7 s ."}
