MultiLanguageItemData['mx'][168611] = {name = "[q6]Escama de ébano petrificada", additional_info = "Rango 1\nObjeto de misión\nÚnico\n[q2]Uso: Infunde el Crisol de Llamas en tu Corazón de Azeroth.\nPoder principal:\n Llama concentrada\nAlcance de 40 m Instante 30 seg de reutilización 1 carga Azota a tu objetivo con una esfera de llamas concentradas que inflige [ 824 * (1 + Versatilidad)] p. de daño de fuego a un enemigo o sana [ 824 * (1 + Versatilidad)] .\n\n Cada lanzamiento de Llama concentrada inflige o sana un 100% más. Esta bonificación se restablece cada tres lanzamientos. \n Poder secundario:\n Llama ancestral\nAproximadamente 3 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de cauterizar a tu objetivo e infligirle ( 351 * 5) p. de daño de fuego durante 10 s o de sanar a un aliado por ( 351 * 5) p. durante 10 s .\n[q]\"Esta escama antigua que personifica a la tierra ha sido templada por un fuego ebúrneo.\""}
MultiLanguageItemData['mx'][168612] = {name = "[q6]Escama de dragón de brillo onírico", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde el Crisol de Llamas en tu Corazón de Azeroth.\nPoder principal:\n Llama concentrada\nAlcance de 40 m Instante 30 seg de reutilización 1 carga Azota a tu objetivo con una esfera de llamas concentradas que inflige [ 824 * (1 + Versatilidad)] p. de daño de fuego a un enemigo o sana [ 824 * (1 + Versatilidad)] p. a un aliado, y luego quema al objetivo por un 75% más del daño o la sanación realizada durante 6 s.\n\n Cada lanzamiento de Llama concentrada inflige un 100% más de daño o sanación. Esta bonificación se restablece con cada tercer lanzamiento. \n Poder secundario:\n Llama ancestral\nAproximadamente 1.25 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de cauterizar a tu objetivo e infligirle [ 351 * 5 * (1.25)] p. de daño de fuego durante 10 s o de sanar a un aliado por [ 351 * 5 * (1.25)] p. durante 10 s.\n[q]\"La escama restaurada irradia el resplandor del Sueño Esmeralda y la esencia del Vuelo Verde.\""}
MultiLanguageItemData['mx'][168613] = {name = "[q6]Escama templada de la madre de linaje escarlata", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde el Crisol de Llamas en tu Corazón de Azeroth.\nAprende Crisol de Llamas (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Llama concentrada\nAlcance de 40 m Instante 30 seg de reutilización 1 carga Azota a tu objetivo con una esfera de llamas concentradas que inflige [ 824 * (1 + Versatilidad)] p. de daño de fuego a un enemigo o sana [ 824 * (1 + Versatilidad)] p. a un aliado, y luego quema al objetivo por un 75% más del daño o la sanación realizada durante 6 s.\n\n Cada lanzamiento de Llama concentrada inflige un 100% más de daño o sanación. Esta bonificación se restablece con cada tercer lanzamiento.\nMáx. de 2 cargas. \n Poder secundario:\n Llama ancestral\nAproximadamente 1.25 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de cauterizar a tu objetivo e infligirle [ 351 * 5 * (1.25)] p. de daño de fuego durante 10 s o de sanar a un aliado por [ 351 * 5 * (1.25)] p. durante 10 s. Este efecto se acumula hasta 3 veces.\n[q]\"Las llamas de la Protectora se agitan y bailan, repletas de energía vital, en la escama.\""}
MultiLanguageItemData['mx'][168614] = {name = "[q6]Escama cargada del Aspecto Azul", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde el Crisol de Llamas en tu Corazón de Azeroth.\nPoder principal:\n Llama concentrada\nAlcance de 40 m Instante 30 seg de reutilización 1 carga Azota a tu objetivo con una esfera de llamas concentradas que inflige [ 824 * (1 + Versatilidad)] p. de daño de fuego a un enemigo o sana [ 824 * (1 + Versatilidad)] p. a un aliado, y luego quema al objetivo por un 75% más del daño o la sanación realizada durante 6 s.\n\n Cada lanzamiento de Llama concentrada inflige un 100% más de daño o sanación. Esta bonificación se restablece con cada tercer lanzamiento.\nMáx. de 2 cargas. \n Poder secundario:\n Llama ancestral\nAproximadamente 1.25 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de cauterizar a tu objetivo e infligirle [ 351 * 5 * (1.25)] p. de daño de fuego durante 10 s o de sanar a un aliado por [ 351 * 5 * (1.25)] p. durante 10 s. Este efecto se acumula hasta 3 veces.\n[q]\"Una magia azul chispeante gira en torno a la escama en representación del otrora gran Aspecto.\""}
MultiLanguageItemData['mx'][168615] = {name = "[q6]Veta del mundo volátil", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Resonancia de veta del mundo en tu Corazón de Azeroth.\nPoder principal:\n Resonancia de veta del mundo\nInstante 1 min de reutilización Concentra energía en el Corazón de Azeroth, lo que hace que inmediatamente emerjan 2 fragmentos de sangrevida en el terreno cercano durante 12 s, y que aumente la estadística principal que se obtiene a partir de Fragmentos de sangrevida un 300% durante 18 s.\n\nFragmento de sangrevida\n Les otorga a ti y a otro aliado que use Resonancia de veta del mundo 13 p. de estadística principal mientras estén a un radio de 8 m del fragmento. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez. \n Poder secundario:\n Sangre de vida\nCada 18-25 s, un fragmento de sangrevida emerge del terreno cercano durante 12 s.\n\nFragmento de sangrevida\n Les otorga a ti y a cualquier otro aliado que use Resonancia de veta del mundo 13 p. para su estadística principal mientras estén en un radio de 12 m del fragmento de sangrevida. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez.\n[q]\"La veta del mundo emite una energía intensa que atrae a la azerita, lo que fortalece a su portador.\""}
MultiLanguageItemData['mx'][168616] = {name = "[q6]Veta del mundo robusta", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Resonancia de veta del mundo en tu Corazón de Azeroth.\nPoder principal:\n Resonancia de veta del mundo\nInstante 1 min de reutilización Concentra energía en el Corazón de Azeroth, lo que hace que inmediatamente emerjan 3 fragmentos de sangrevida en el terreno cercano durante 18 s, y que aumente la estadística principal que se obtiene a partir de Fragmentos de sangrevida un 300% durante 18 s.\n\nFragmento de sangrevida\n Les otorga a ti y a otro aliado que use Resonancia de veta del mundo 13 p. de estadística principal mientras estén a un radio de 8 m del fragmento. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez. \n Poder secundario:\n Sangre de vida\nCada 18-25 s, un fragmento de sangrevida emerge del terreno cercano durante 18 s.\n\nFragmento de sangrevida\n Les otorga a ti y a cualquier otro aliado que use Resonancia de veta del mundo 13 p. para su estadística principal mientras estén en un radio de 8 m del fragmento de sangrevida. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez.\n[q]\"La veta del mundo tiene una constitución sólida y parece fortalecer la azerita a su alrededor.\""}
