MultiLanguageItemData['mx'][168920] = {name = "[q6]Cuarzo temporal con incrustación de azerita", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Artificio del tiempo en tu Corazón de Azeroth.\nPoder principal:\n Punto muerto\nAlcance de 40 m Instante 3 min de reutilización Crea un vórtice temporal alrededor de un objetivo aliado que absorbe 34942 p. de daño y 34942 p. de sanación durante 4 s. Cuando expira, el daño y la sanación absorbidos se otorgan durante 10 s . \n Poder secundario:\n Artificio del tiempo\nAproximadamente 10 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de otorgar 72 p. de celeridad al objetivo durante 6 s.\n[q]\"Siempre hay tiempo para un descanso en la batalla.\""}
MultiLanguageItemData['mx'][168921] = {name = "[q6]Cuarzo temporal insuflado con azerita", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Artificio del tiempo en tu Corazón de Azeroth.\nRequiere el logro \"Camorrista del campo de batalla\". (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Punto muerto\nAlcance de 40 m Instante 3 min de reutilización Crea un vórtice temporal alrededor de un objetivo aliado que absorbe 34942 p. de daño y 34942 p. de sanación durante 6 s. Cuando expira, el daño y la sanación absorbidos se otorgan durante 10 s . \n Poder secundario:\n Artificio del tiempo\nAproximadamente 10 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de otorgar 86 p. de celeridad al objetivo durante 8 s.\n[q]\"Siempre hay tiempo para un descanso en la batalla.\""}
MultiLanguageItemData['mx'][168922] = {name = "[q6]Cuarzo temporal energizado con azerita", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Artificio del tiempo en tu Corazón de Azeroth.\nRequiere el logro \"Estratega del campo de batalla\". (No se puede comprar si ya lo aprendiste).\nAprende Sangre del enemigo, Artificio del tiempo o Esfera de supresión (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Punto muerto\nAlcance de 40 m Instante 3 min de reutilización Crea un vórtice temporal alrededor de un objetivo aliado que absorbe 34942 p. de daño y 34942 p. de sanación durante 6 s. Cuando expira, el daño y la sanación absorbidos se otorgan durante 10 s, y el daño se reduce un 20%. \n Poder secundario:\n Artificio del tiempo\nAproximadamente 10 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de otorgar 86 p. de celeridad y 72 p. de velocidad al objetivo durante 8 s.\n[q]\"Siempre hay tiempo para un descanso en la batalla.\""}
MultiLanguageItemData['mx'][168923] = {name = "[q6]Cuarzo temporal inmaculado", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Artificio del tiempo en tu Corazón de Azeroth.\nPoder principal:\n Punto muerto\nAlcance de 40 m Instante 3 min de reutilización Crea un vórtice temporal alrededor de un objetivo aliado que absorbe 34942 p. de daño y 34942 p. de sanación durante 6 s. Cuando expira, el daño y la sanación absorbidos se otorgan durante 10 s, y el daño se reduce un 20%. \n Poder secundario:\n Artificio del tiempo\nAproximadamente 10 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de otorgar 86 p. de celeridad y 72 p. de velocidad al objetivo durante 8 s.\n[q]\"Siempre hay tiempo para un descanso en la batalla.\""}
MultiLanguageItemData['mx'][168924] = {name = "[q6]Semilla de vida colmada", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Invocación de la Protectora en tu Corazón de Azeroth.\nPoder principal:\n Invocación de la Protectora\nHechizo de 2.5 seg 2.5 min de reutilización Implanta 30 semillas de Eonar divididas entre todos los aliados en un radio de 30 m.\n\n Semilla de Eonar\nSi el objetivo recibe daño, la semilla explota y lo sana 436 p. \n Poder secundario:\n Semilla de Eonar\nAproximadamente 15 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de implantar una semilla de Eonar en el objetivo durante 12 s s.\n\nSemilla de Eonar\nSi el objetivo recibe daño, la semilla explota y lo sana 436 p.\n[q]\"Eonar esparció las primeras semillas de vida por todo Azeroth. Sin embargo, solo algunas aún conservan el poder de la titán en su interior.\""}
MultiLanguageItemData['mx'][168925] = {name = "[q6]Semilla de abundancia autoduplicante", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Invocación de la Protectora en tu Corazón de Azeroth.\nPoder principal:\n Invocación de la Protectora\nHechizo de 2.5 seg 2.5 min de reutilización Implanta 40 semillas de Eonar divididas entre todos los aliados en un radio de 30 m.\n\n Semilla de Eonar\nSi el objetivo recibe daño, la semilla explota y lo sana 436 p. \n Poder secundario:\n Semilla de Eonar\nAproximadamente 15 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de implantar una semilla de Eonar en el objetivo durante 15 s.\n\nSemilla de Eonar\nSi el objetivo recibe daño, la semilla explota y lo sana 436 p.\n[q]\"Eonar esparció las primeras semillas de vida por todo Azeroth. Sin embargo, solo algunas aún conservan el poder de la titán en su interior.\""}
MultiLanguageItemData['mx'][168926] = {name = "[q6]Semilla de renovación perenne", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Invocación de la Protectora en tu Corazón de Azeroth.\nAprende Iris de enfoque, Invocación de la Protectora o Ánima de vida y muerte (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Invocación de la Protectora\nHechizo de 2.5 seg 2.5 min de reutilización Implanta 40 semillas de Eonar divididas entre todos los aliados en un radio de 30 m.\n\n Las semillas que expiran sin usarse reducen 2 s el tiempo de reutilización de esta habilidad.\n\n Semilla de Eonar\nSana 21 p. cada 1 s. Si el objetivo recibe daño, la semilla explota y lo sana 436 p. \n Poder secundario:\n Semilla de Eonar\nAproximadamente 15 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de implantar una semilla de Eonar en el objetivo durante 15 s.\n\nSemilla de Eonar\nSana 21 p. cada 1 s. Si el objetivo recibe daño, la semilla explota y lo sana 436 p.\n[q]\"Eonar esparció las primeras semillas de vida por todo Azeroth. Sin embargo, solo algunas aún conservan el poder de la titán en su interior.\""}
MultiLanguageItemData['mx'][168927] = {name = "[q6]Semilla de flores vibrantes", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Invocación de la Protectora en tu Corazón de Azeroth.\nPoder principal:\n Invocación de la Protectora\nHechizo de 2.5 seg 2.5 min de reutilización Implanta 40 semillas de Eonar divididas entre todos los aliados en un radio de 30 m.\n\n Las semillas que expiran sin usarse reducen 2 s el tiempo de reutilización de esta habilidad.\n\n Semilla de Eonar\nSana 21 p. cada 1 s. Si el objetivo recibe daño, la semilla explota y lo sana 436 p. \n Poder secundario:\n Semilla de Eonar\nAproximadamente 15 activaciones por minuto Tus sanaciones tienen una probabilidad muy alta de implantar una semilla de Eonar en el objetivo durante 15 s.\n\nSemilla de Eonar\nSana 21 p. cada 1 s. Si el objetivo recibe daño, la semilla explota y lo sana 436 p.\n[q]\"Eonar esparció las primeras semillas de vida por todo Azeroth. Sin embargo, solo algunas aún conservan el poder de la titán en su interior.\""}
MultiLanguageItemData['mx'][168928] = {name = "[q6]Tabilla de mareas de balance", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde La marea eternamente creciente en tu Corazón de Azeroth.\nRequiere la reputación Amistoso con los Desencadenados. (No se puede comprar si ya lo aprendiste).\nRequiere la reputación Amistoso con los Ankoanos. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Sobrecargar maná\nInstante 30 seg de reutilización Sobrecarga tu maná durante 8 s, lo que hace que cada hechizo que lances aumente tu sanación un 3%. Este efecto se acumula.\n\n Durante la sobrecarga, tu regeneración de maná se detiene . \n Poder secundario:\n La marea eternamente creciente\nAproximadamente 1.75 activaciones por minuto Tus sanaciones tienen una probabilidad de otorgar 115 p. de intelecto durante 10 s o 477 p. de maná. La probabilidad de recibir maná aumenta en relación con el maná faltante. (3.5s de reutilización)\n[q]\"Los susurros de Elune y Neptulon juegan sobre las mareas, sus palabras grabadas en la piedra son un tributo al equilibrio de sus poderes.\""}
MultiLanguageItemData['mx'][168929] = {name = "[q6]Códice de mareas sin fin", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde La marea eternamente creciente en tu Corazón de Azeroth.\nRequiere la reputación Honorable con los Desencadenados. (No se puede comprar si ya lo aprendiste).\nRequiere la reputación Honorable con los Ankoanos. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Sobrecargar maná\nInstante 30 seg de reutilización Sobrecarga tu maná durante 8 s, lo que hace que cada hechizo que lances aumente tu sanación un 4%. Este efecto se acumula.\n\n Durante la sobrecarga, tu regeneración de maná se detiene . \n Poder secundario:\n La marea eternamente creciente\nAproximadamente 1.75 activaciones por minuto Tus sanaciones tienen una probabilidad de otorgar [ 115 * (1.2)] p. de intelecto durante 10 s o [ 477 * (1.2)] p. de maná. La probabilidad de recibir maná aumenta en relación con el maná faltante. [La marea eternamente creciente: 20% de probabilidad de recibir ambos efectos ] (3.5s de reutilización)"}
MultiLanguageItemData['mx'][168930] = {name = "[q6]Tomo de las mareas de aceleración", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde La marea eternamente creciente en tu Corazón de Azeroth.\nAprende cualquier esencia de rango 3 de la reputación de Nazjatar con otro personaje para desbloquear esta esencia.\nRequiere la reputación Venerado con los Desencadenados. (No se puede comprar si ya lo aprendiste).\nRequiere la reputación Venerado con los Ankoanos. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Sobrecargar maná\nInstante 30 seg de reutilización Sobrecarga tu maná durante 8 s, lo que hace que cada hechizo que lances aumente tu sanación un 4%. Este efecto se acumula.\n\n Durante la sobrecarga, tu regeneración de maná se detiene y obtienes un 10% de celeridad. \n Poder secundario:\n La marea eternamente creciente\nAproximadamente 1.75 activaciones por minuto Tus sanaciones tienen una probabilidad de otorgar [ 115 * (1.2)] p. de intelecto durante 10 s o [ 477 * (1.2)] p. de maná. La probabilidad de recibir maná aumenta en relación con el maná faltante. 20% de probabilidad de recibir ambos efectos. (3.5s de reutilización)"}
