MultiLanguageItemData['mx'][168932] = {name = "[q6]Batería de existencia reactiva", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Pozo de la existencia en tu Corazón de Azeroth.\nRequiere la reputación Amistoso con la Resistencia de Pernoxidado. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Refrigerio\nAlcance de 100 m Instante 15 seg de reutilización Libera la sanación almacenada dentro del Pozo de la existencia hacia un aliado. Esta sanación se amplifica un 20 %. \n Poder secundario:\n Pozo de la existencia\n15% de tu sanación en exceso se almacena en el Pozo de la existencia. Cuando sanas a un objetivo cuya salud está por debajo del 40%, el Pozo le concede hasta 547 p. de su salud almacenada."}
MultiLanguageItemData['mx'][168933] = {name = "[q6]Capacitador de existencia mejorado", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Pozo de la existencia en tu Corazón de Azeroth.\nRequiere la reputación Honorable con la Resistencia de Pernoxidado. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Refrigerio\nAlcance de 100 m Instante 15 seg de reutilización Libera la sanación almacenada dentro del Pozo de la existencia hacia un aliado. Esta sanación se amplifica un 50%. \n Poder secundario:\n Pozo de la existencia\n15% de tu sanación en exceso se almacena en el Pozo de la existencia. Cuando sanas a un objetivo cuya salud está por debajo del 50%, el Pozo le concede hasta 547 p. de su salud almacenada."}
MultiLanguageItemData['mx'][168934] = {name = "[q6]Barra de existencia calibrada", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Pozo de la existencia en tu Corazón de Azeroth.\nRequiere la reputación Venerado con la Resistencia de Pernoxidado. (No se puede comprar si ya lo aprendiste).\nAprende cualquier esencia de rango 3 de la Resistencia de Pernoxidado con otro personaje para desbloquear esta esencia.\nPoder principal:\n Refrigerio\nAlcance de 100 m Instante 15 seg de reutilización Libera la sanación almacenada dentro del Pozo de la existencia hacia un aliado. Esta sanación se amplifica un 50%. El Pozo no liberará más sanación de la necesaria para sanar al objetivo por completo. \n Poder secundario:\n Pozo de la existencia\n15% de tu sanación en exceso se almacena en el Pozo de la existencia. Cuando sanas a un objetivo cuya salud está por debajo del 50%, el Pozo le concede hasta 547 p. de su salud almacenada.\n\n Cuando el Pozo almacena menos de 1398 p. de sanación, absorbe la sanación el doble de rápido."}
MultiLanguageItemData['mx'][168935] = {name = "[q6]Muestra de vibración de existencia", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Pozo de la existencia en tu Corazón de Azeroth.\nPoder principal:\n Refrigerio\nAlcance de 100 m Instante 15 seg de reutilización Libera la sanación almacenada dentro del Pozo de la existencia hacia un aliado. Esta sanación se amplifica un 50%. El Pozo no liberará más sanación de la necesaria para sanar al objetivo por completo. \n Poder secundario:\n Pozo de la existencia\n15% de tu sanación en exceso se almacena en el Pozo de la existencia. Cuando sanas a un objetivo cuya salud está por debajo del 50%, el Pozo le concede hasta 547 p. de su salud almacenada.\n\n Cuando el Pozo almacena menos de 1398 p. de sanación, absorbe la sanación el doble de rápido."}
MultiLanguageItemData['mx'][168936] = {name = "[q6]Resguardo de esperanza inquebrantable", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Resguardo inquebrantable en tu Corazón de Azeroth.\nPoder principal:\n Caparazón de guardián\nCanalizado (Hechizo de 4 seg) 3 min de reutilización Libera 12 esferas protectoras durante 4 s, que otorgan al primer aliado que tocan una barrera que absorbe 1840 p. de daño durante 10 s. \n Poder secundario:\n Resguardo inquebrantable\nCada 10 s, los aliados en un radio de 15 m obtienen un escudo que absorbe [ 113 * (1 + Versatilidad)] p. de daño, lo que se acumula hasta [ 848 * (1 + Versatilidad)] p.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][168937] = {name = "[q6]Resguardo de reciprocidad", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Resguardo inquebrantable en tu Corazón de Azeroth.\nPoder principal:\n Caparazón de guardián\nCanalizado (Hechizo de 4 seg) 3 min de reutilización Libera 12 esferas protectoras durante 4 s, que otorgan al primer aliado que tocan una barrera que absorbe 1840 p. de daño durante 10 s.\n\n Cada vez que lanzas una esfera protectora, obtienes un escudo de absorción equivalente a un 2% de tu salud máxima. \n Poder secundario:\n Resguardo inquebrantable\nCada 10 s, los aliados en un radio de 15 m obtienen un escudo que absorbe [ 113 * (1 + Versatilidad)] p. de daño, lo que se acumula hasta [ 848 * (1 + Versatilidad) * (1.2)] p.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción.\n[q]\"Trata a los demás como…\""}
MultiLanguageItemData['mx'][168938] = {name = "[q6]Resguardo de ayuda mutua", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Resguardo inquebrantable en tu Corazón de Azeroth.\nAprende cualquier esencia (rango 3) de Visiones horribles con otro personaje para desbloquear esta esencia.\nPoder principal:\n Caparazón de guardián\nCanalizado (Hechizo de 4 seg) 3 min de reutilización Libera 12 esferas protectoras durante 4 s, que otorgan al primer aliado que tocan una barrera que absorbe 1840 p. de daño durante 10 s.\n\n Cada vez que lanzas una esfera protectora, obtienes un escudo de absorción equivalente a un 2% de tu salud máxima.\n\n Cuando un aliado obtiene el escudo de absorción, tú y ese aliado sanan [ 346 * (1 + Versatilidad)]. \n Poder secundario:\n Resguardo inquebrantable\nCada 10 s, los aliados en un radio de 15 m obtienen un escudo que absorbe [ 113 * (1 + Versatilidad)] p. de daño, lo que se acumula hasta [ 848 * (1 + Versatilidad) * (1.2)] p.\n\n Los objetivos protegidos con Resguardo inquebrantable reciben un 3% menos de daño.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
