MultiLanguageItemData['mx'][169299] = {name = "Poción de furia desbocada", additional_info = "[q2]Uso: Te llenas de energía desenfrenada que les otorga a tus hechizos ofensivos y ataques la probabilidad de infligir 1344 p. más de daño de fuego a tu objetivo. Dura 1 min. (5 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169300] = {name = "Poción de alivio salvaje", additional_info = "[q2]Uso: Potencia tu mente y les otorga a tus habilidades de sanación la probabilidad de restaurar 2017 p. más de salud a tu objetivo. Dura 1 min. (5 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169301] = {name = "[q4]Compendio altonato de mareas arremolinadas", additional_info = "Se liga al equiparlo\nÚnico-Equipado\nAbalorio\n+7 intelecto\n[q2]Equipar: Tus hechizos de sanación tienen una probabilidad de otorgar a un aliado un escudo de absorción que absorbe hasta 153 p. de daño durante 12 s. Mientras el escudo está activo, la estadística principal del objetivo aumenta 6 p.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169302] = {name = "[q4]Compendio altonato del baluarte místico", additional_info = "Se liga al equiparlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Equipar: Cuando recibes daño, tienes una probabilidad de sanar por 78 p., obtener 9 p. de armadura durante 10 s, y acumular hasta ( 9 * 4) de armadura.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169303] = {name = "[q3]Brazales de dominio", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Saca músculo y aumenta la potencia de brazos durante 15 min. (45 Min Reutilización)\n[q]\"¿Tienes la fuerza para usarlos?\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][169304] = {name = "[q4]Cebo de Leviatán", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 intelecto\n[q2]Equipar: Tus habilidades que infligen daño tienen una probabilidad muy baja de invocar un Leviatán, que inflige [ 165 * (1 + Versatilidad)] p. de daño físico a tu objetivo.\n\n El daño que infliges también cultiva algas fluorescentes, que aumentan tu probabilidad de realizar la invocación.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169305] = {name = "[q4]Nautilo acuapotente", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 intelecto\n[q2]Uso: Libera una ola que choca contra tu objetivo y regresa a tu ubicación original. Inflige [ 24 * (5) * (1 + Versatilidad)] p. de daño de escarcha durante 4 s a los enemigos a su paso. Atrapa la ola para reducir 30 s el tiempo de reutilización de esta habilidad. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169306] = {name = "[q4]Llave de portal de Za'qul", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Aumenta tu índice de celeridad + 10 p.\n[q2]Equipar: Tus habilidades tienen una probabilidad baja de crear una Grieta del Vacío cerca durante 30 s. Acercarse a una Grieta del Vacío creará un portal durante 10 s. Si te paras en el portal, recibirás 28 p. de intelecto.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169307] = {name = "[q4]Visión de muerte", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Uso: Revela la muerte inminente de tu enemigo, lo que aumenta 30 p. tu celeridad durante 10 s. Por cada 10% de salud que le falta a tu objetivo, obtienes 4 p. más de celeridad. (1 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169308] = {name = "[q4]Cadena de sufrimiento", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Uso: Transfiere un 50% del daño que recibes a un aliado en un radio de 25 m durante 25 s, hasta 1644 p. de daño. Si tu objetivo se aleja del radio de alcance o su salud cae por debajo del 25%, el efecto termina. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169309] = {name = "[q4]Saco de huevos de zoatroide", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 intelecto\n[q2]Equipar: Lanzar una sanación de un solo objetivo tiene una probabilidad de invocar un zoatroide sobre tu objetivo que absorbe [ 76 * (1 + Versatilidad)] p. de daño y otorga hasta 11 p. de versatilidad según la absorción restante. Cada vez que gastas un 10% de maná, nutres a tus zoatroides y agregas [ 8 * (1 + Versatilidad)] p. de absorción y 1 p. de versatilidad.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169310] = {name = "[q4]Erizo de mar sanguinario", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Equipar: Un 10% del daño recibido te otorga Sangre curativa, hasta [ 315 * (1 + Versatilidad)] p. en total. Cada 3 s, gastas [ 41 * (1 + Versatilidad)] p. de Sangre curativa para sanarte si recibiste daño.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169311] = {name = "[q4]Coral afilado de Aspafresno", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Uso: Inflige [ 25 * (1 + Versatilidad)] p. de daño físico y le aplica Coral afilado a tu objetivo, lo que otorga a tus habilidades que infligen daño contra el objetivo una alta probabilidad de infligir [ 25 * (1 + Versatilidad)] p. de daño físico y agregar una acumulación de Coral afilado.\n\n Cuando esta habilidad se reactiva, le quita Coral afilado a tu objetivo y te otorga 3 p. de golpe crítico por acumulación durante 20 s. (20 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169312] = {name = "[q4]Herbadusa luminosa", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 intelecto\n[q2]Equipar: Tus sanaciones tienen la probabilidad de otorgar Luminiscencia a tu aliado más herido en un radio de 40 m. Los aliados con Luminiscencia reciben un 10% más de sanación, hasta un total de [ 87 * (1 + Versatilidad)] p. de sanación adicionales.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169313] = {name = "[q4]Ampolla de la tempestad arcana", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Equipar: Tus habilidades que infligen daño tienen una probabilidad baja de rodearte con una Tempestad arcana durante 20 s que inflige 5 p. de daño arcano cada 2 s a los enemigos cercanos. La Tempestad se acelera cada vez que golpea a un enemigo solitario e inflige daño con más frecuencia.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169314] = {name = "[q4]Fuente de poder de Azshara", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Aumenta tu índice de golpe crítico + 10 p.\n[q2]Uso: Canaliza magia latente durante un máximo de 4 s y aumenta 30 p. tu estadística principal. La duración se extiende por cada segundo de canalización, hasta 30 s. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169315] = {name = "[q4]Edictos de los Infieles", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Equipar: Cada 40 segundos, obtienes una absorción que evita que recibas [ 262 * (1 + Versatilidad)] p. de daño físico . Si la absorción se consume obtienes Fanatismo, y las siguientes absorciones evitan que recibas un 10% más de daño, hasta un máximo de un 100%.\n[q2]Uso: Declara el Edicto de la bruja del mar y hace que esta habilidad absorba daño mágico y restablece Fanatismo. (40 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169316] = {name = "[q4]Sentencia suspendida", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 intelecto\n[q2]Equipar: Aplaza [ 7 * (1 + Versatilidad)] p. de sanación cada 3 segundos. Moverse libera la sanación aplazada, lo que restaura salud a tus 3 aliados más heridos.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169317] = {name = "[q4]Piedra de ligación de encantadora", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]+ 10 Versatilidad\n[q2]Equipar: Tus habilidades tienen una probabilidad de otorgarte 15 p. de tu estadística principal durante 30 s.\nPrecio de venta:"}
MultiLanguageItemData['mx'][169318] = {name = "[q4]Colmillos de electromordedor", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza o Intelecto]\n[q2]Uso: Aumenta 23 p. tu celeridad durante 30 s. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][169319] = {name = "[q4]Vaina de tinta goteante", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+7 [Agilidad o Fuerza]\n[q2]Equipar: Tus habilidades que infligen daño a enemigos que tienen más de un 30% de salud tienen una probabilidad muy alta de aplicar Tinta conductora. Cuando la salud de un enemigo cae por debajo de un 30%, Tinta conductora inflige [ 26 * (1 + Versatilidad)] p. de daño de naturaleza por cada acumulación.\nPrecio de venta:"}
