MultiLanguageItemData['mx'][170208] = {name = "[q2]Receta: Poción de furia desbocada", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar una Poción de furia desbocada con más eficiencia.\n[q2]Probabilidad de crear varias pociones.\nRequiere Alquimia kultirana (170)\nPrecio de venta: \nPoción de furia desbocada\n[q2]Uso: Te llenas de energía desenfrenada que les otorga a tus hechizos ofensivos y ataques la probabilidad de infligir 1344 p. más de daño de fuego a tu objetivo. Dura 1 min. (5 Min Reutilización)\nPrecio de venta:\nRequiere Zin'antida (6), Vial de cristal"}
MultiLanguageItemData['mx'][170209] = {name = "[q2]Receta: Poción de alivio salvaje", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar una Poción de alivio salvaje con más eficiencia.\n[q2]Probabilidad de crear varias pociones.\nRequiere Alquimia kultirana (170)\nPrecio de venta: \nPoción de alivio salvaje\n[q2]Uso: Potencia tu mente y les otorga a tus habilidades de sanación la probabilidad de restaurar 2017 p. más de salud a tu objetivo. Dura 1 min. (5 Min Reutilización)\nPrecio de venta:\nRequiere Zin'antida (6), Vial de cristal"}
MultiLanguageItemData['mx'][170210] = {name = "[q2]Receta: Poción de sanación abisal", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar una Poción de sanación abisal con más eficiencia.\n[q2]Probabilidad de crear varias pociones.\nRequiere Alquimia kultirana (170)\nPrecio de venta: \nPoción de sanación abisal\n[q2]Uso: Restaura 16000 p. de salud. (5 Min Reutilización)\nPrecio de venta:\nRequiere Zin'antida (2), Vial de cristal"}
MultiLanguageItemData['mx'][170211] = {name = "[q2]Receta: Festín Especial Sabroso con Todos los Ingredientes Nutritivos", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a crear un Festín Especial Sabroso con Todos los Ingredientes Nutritivos con más eficiencia.\n[q2]Prepara F.E.S.T.I.N.es con más eficiencia y con muchos menos materiales.\nRequiere Cocina kultirana (175)\nPrecio de venta: \nFestín Especial Sabroso con Todos los Ingredientes Nutritivos\n[q2]Uso: ¡Prepara un F.E.S.T.Í.N. para alimentar hasta a 35 personas de tu grupo o banda!\n\n Restablece 50769 p. de salud y 30769 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 50 p. de una estadística durante 1 h.\nPrecio de venta: \nRequiere Pez víbora (15), Sardinilla ionizada (15), Lomo fibroso (15), Anca carnosa (15), Patata fresca (20), Cajón de R.E.P.U.E.S.T.O."}
MultiLanguageItemData['mx'][170212] = {name = "[q2]Receta: Mecabocados", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar mecabocados.\n[q2]Prepara mecabocados.\nRequiere Cocina kultirana (150)\nPrecio de venta: \nMecabocados\n[q2]Uso: ¿Comerme?\n[q]\"¡Contienen una rueda dentada metalcrispy!\"\nPrecio de venta: \nRequiere Piezas de repuesto (25)"}
MultiLanguageItemData['mx'][170213] = {name = "[q3]Fórmula: Pellejo de naga", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar un Pellejo de naga con más eficiencia.\n[q2]Encanta un arma de forma permanente con un hechizo de protección naga. Cuando bloqueas, esquivas o paras, hay una probabilidad de aumentar 4 p. tu fuerza o agilidad durante 15 s. Además, mientras este efecto está activo, tu piel se cubre de escamas gruesas que absorben 1573 p. de daño. No se puede aplicar a objetos de nivel superior a 376.\n\n Materiales reducidos enormemente.\nRequiere Encantamiento kultirano (175)\nPrecio de venta:"}
