MultiLanguageItemData['mx'][172912] = {name = "Botas de redistribución de velocidad", additional_info = "Se liga al usarlo\n[q2]Uso: Redistribuye una parte significativa del daño que recibirías de tu próxima caída a enemigos cercanos. Dura 10 s.\n\n No puede usarse en estancias. (5 Min Reutilización)\nRequiere Ingeniería de Shadowlands (1)\n[q]\"¡Te permite realizar un aterrizaje superheroico!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][172914] = {name = "Cañón de interferencia gravimétrica", additional_info = "Se liga al usarlo\n[q2]Uso: Desestabiliza la gravedad en una ubicación seleccionada, lo que entorpece el movimiento de los enemigos cercanos durante 10 s y los lanza por los aires o en cualquier dirección.\n\n A menos que algo salga mal.\nRequiere Ingeniería de Shadowlands (1)\n[q]\"¡¿Qué?! ¿Cómo que una pistola de agua? Esto es una magnífica pieza de artillería.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][172915] = {name = "TR4MP4-D3-4LM4", additional_info = "Se liga al usarlo\n[q2]Uso: Coloca un dispositivo de almacenamiento sobre el suelo que, una vez armado, se activa cuando un enemigo se para encima y lo destierra durante 1 min.\n\n A menos que algo salga mal.\n\n Se reduce el efecto contra jugadores. (3 Min Reutilización)\nRequiere Ingeniería de Shadowlands (1)\n[q]\"¡¿Con quién te comunicarás?!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][172917] = {name = "Modificación de cinturón: Mutador dimensional", additional_info = "[q2]Uso: Añade de forma permanente un dispositivo especializado en tu cinturón que te permite provocar miedo en un enemigo que esté a una distancia de ataque cuerpo a cuerpo durante 5 s.\n\n Solo se puede modificar el cinturón del ingeniero y, si se modifica, se ligará al alma.\n[q]\"¡No puedes embestir a aquello que eres incapaz de percibir visualmente!\""}
MultiLanguageItemData['mx'][172918] = {name = "Modificación de cinturón: Electrosalto", additional_info = "[q2]Uso: Añade de forma permanente un dispositivo especializado en tu cinturón que te permite provocar miedo en un enemigo que esté a una distancia de ataque cuerpo a cuerpo durante 5 s.\n\n Solo se puede modificar el cinturón del ingeniero y, si se modifica, se ligará al alma.\n[q]\"¡Monta el relámpago!\""}
MultiLanguageItemData['mx'][172919] = {name = "Modificación de cinturón: Vindicador de daños", additional_info = "[q2]Uso: Añade de forma permanente un dispositivo especializado en tu cinturón que te permite provocar miedo en un enemigo que esté a una distancia de ataque cuerpo a cuerpo durante 5 s.\n\n Solo se puede modificar el cinturón del ingeniero y, si se modifica, se ligará al alma.\n[q]\"Yo estoy compuesto de bandas altamente elásticas. Tú estás compuesto enteramente por un líquido adhesivo…\""}
