MultiLanguageItemData['mx'][173280] = {name = "[q6]Ficha de la puerta de la muerte", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Aliento de los moribundos en tu Corazón de Azeroth.\nPoder principal:\n Llamas segadoras\nAlcance de 40 m Instante 45 seg de reutilización Quema a tu objetivo con una descarga de azerita que inflige 3067 p. de daño de fuego. Si el objetivo tiene menos de 20% de salud , el tiempo de reutilización se reduce 30 s. \n Poder secundario:\n Golpes mortíferos\nAlcance de 40 m\n Aproximadamente 10 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de infligirle a tu objetivo 1244 p. de daño de fuego .\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][173281] = {name = "[q6]Ficha de la marca de la muerte", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Aliento de los moribundos en tu Corazón de Azeroth.\nPoder principal:\n Llamas segadoras\nAlcance de 40 m Instante 45 seg de reutilización Quema a tu objetivo con una descarga de azerita que inflige 3067 p. de daño de fuego. Si el objetivo tiene menos de un 20% o más de 80% de salud, el tiempo de reutilización se reduce 30 s. \n Poder secundario:\n Golpes mortíferos\nAlcance de 40 m\n Aproximadamente 10 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de infligirle 1244 p. de daño de fuego a tu objetivo y de sanarte por un 50% del daño infligido.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][173282] = {name = "[q6]Ficha del regocijo de la muerte", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Aliento de los moribundos en tu Corazón de Azeroth.\nAprende cualquier esencia de los Rajani o del Acuerdo de Uldum (rango 3) con otro personaje para desbloquear esta esencia.\nRequiere la reputación Venerado con el Acuerdo de Uldum. (No se puede comprar si ya lo aprendiste).\nPoder principal:\n Llamas segadoras\nAlcance de 40 m Instante 45 seg de reutilización Quema a tu objetivo con una descarga de azerita que inflige 3067 p. de daño de fuego. Si el objetivo tiene menos de 20% o más de 80% de salud, el tiempo de reutilización se reduce 30 s.\n\n Si las Llamas segadoras matan a un enemigo, su tiempo de reutilización se reduce a 5 s y su próximo uso inflige un 100% más de daño. \n Poder secundario:\n Golpes mortíferos\nAlcance de 40 m\n Aproximadamente 10 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de infligir 1244 p. de daño de fuego cuando golpean a tu objetivo y de sanarte por un 50% del daño infligido.\n\n Si tu objetivo tiene menos del 20% de salud, la probabilidad de infligir daño adicional aumenta un 400%.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción.\n[q]\"Un susurro del porvenir.\""}
MultiLanguageItemData['mx'][173283] = {name = "[q6]Ficha de una muerte brillante", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Aliento de los moribundos en tu Corazón de Azeroth.\nPoder principal:\n Llamas segadoras\nAlcance de 40 m Instante 45 seg de reutilización Quema a tu objetivo con una descarga de azerita que inflige 3067 p. de daño de fuego. Si el objetivo tiene menos de 20% o más de 80% de salud, el tiempo de reutilización se reduce 30 s.\n\n Si las Llamas segadoras matan a un enemigo, su tiempo de reutilización se reduce a 5 s y su próximo uso inflige un 100% más de daño. \n Poder secundario:\n Golpes mortíferos\nAlcance de 40 m\n Aproximadamente 10 activaciones por minuto Tus hechizos y habilidades tienen la probabilidad de infligir 1244 p. de daño de fuego cuando golpean a tu objetivo y de sanarte por un 50% del daño infligido.\n\n Si tu objetivo tiene menos del 20% de salud, la probabilidad de infligir daño adicional aumenta un 400%.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
