MultiLanguageItemData['mx'][173308] = {name = "[q6]Marca del deber escandaloso", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Fuerza del celador en tu Corazón de Azeroth.\nPoder principal:\n Protector vigilante\nInstante 2 min de reutilización Provoca a todos los enemigos cercanos, los obliga a atacarte durante 6 s . \n Poder secundario:\n Robustez\nCada 2 s, almacena 188 p. de sanación, hasta un máximo de ([Total Health] * 0.1) p. Cuando esquivas o paras un ataque, sanas la cantidad acumulada.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción.\n[q]\"Los enfrentamientos no se temen, se aceptan.\""}
MultiLanguageItemData['mx'][173309] = {name = "[q6]Técnica del bailarín de agua", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Fuerza del celador en tu Corazón de Azeroth.\nPoder principal:\n Protector vigilante\nInstante 2 min de reutilización Provoca a todos los enemigos cercanos, los obliga a atacarte durante 6 s y aumenta tu probabilidad de esquivar un 15% durante 6 s. \n Poder secundario:\n Robustez\nCada 2 s, almacena [ 158 * (1 + Versatilidad) * (1.25)] p. de sanación, hasta un máximo de ([Total Health] * 0.1) p. Cuando esquivas o paras un ataque, sanas la cantidad acumulada.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción.\n[q]\"¡Rápido... y repentino!\""}
MultiLanguageItemData['mx'][173310] = {name = "[q6]Manual de tácticas desequilibradas", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde Fuerza del celador en tu Corazón de Azeroth.\nAprende cualquier esencia (rango 3) de Visiones horribles con otro personaje para desbloquear esta esencia.\nPoder principal:\n Protector vigilante\nInstante 2 min de reutilización Provoca a todos los enemigos cercanos, los obliga a atacarte durante 6 s y aumenta tu probabilidad de esquivar un 15% durante 6 s.\n\n Les infliges un 50% más de daño a los objetivos afectados por tu Protector vigilante. \n Poder secundario:\n Robustez\nCada 2 s, almacena [ 158 * (1 + Versatilidad) * (1.25)] p. de sanación, hasta un máximo de ([Total Health] * 0.1) p. Cuando esquivas o paras un ataque, sanas la cantidad acumulada.\n\n La salud máxima de todos los jugadores con especialización de tanque de tu grupo o banda aumenta un 3%. Este efecto se acumula.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
