MultiLanguageItemData['mx'][173883] = {name = "[q6]Gotas del Vacío replicante", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde El Vacío amorfo en tu Corazón de Azeroth.\nPoder principal:\n Réplica de conocimiento\nAlcance de 40 m\n Hechizo de 1.5 seg Replica la energía en el Corazón de Azeroth de tu objetivo, lo que otorga acceso al rango 1 de su esencia principal actual durante los próximos 15 s. El Vacío amorfo tendrá un tiempo de reutilización un 50% más extenso que el tiempo de reutilización básico de la esencia que replicaste.\n\n No funciona con esencias pasivas. \n Poder secundario:\n Presencia simbiótica\nAlcance de 40 m Cada vez que un aliado en un radio de 40 m usa una esencia de azerita, obtienes 22 p. de [Primary Stat] durante 20 s.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción.\n[q]\"Insidioso, pero sumamente poderoso.\""}
MultiLanguageItemData['mx'][173884] = {name = "[q6]Gota del Vacío floreciente", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde El Vacío amorfo en tu Corazón de Azeroth.\nPoder principal:\n Réplica de conocimiento\nAlcance de 40 m\n Hechizo de 1.5 seg Replica la energía en el Corazón de Azeroth de tu objetivo, lo que otorga acceso al rango 2 de su esencia principal actual durante los próximos 15 s. El Vacío amorfo tendrá un tiempo de reutilización un 40% más extenso que el tiempo de reutilización básico de la esencia que replicaste.\n\n No funciona con esencias pasivas. \n Poder secundario:\n Presencia simbiótica\nCada vez que un aliado en un radio de 40 m usa una esencia de azerita, obtienes [ 22 * (1.25)] p. de [Primary Stat] durante 20 s.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][173885] = {name = "[q6]Gota del Vacío volátil", additional_info = "Rango 3\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde El Vacío amorfo en tu Corazón de Azeroth.\nAprende El Vacío amorfo (rango 3) con otro personaje para desbloquear esta esencia.\nPoder principal:\n Réplica de conocimiento\nAlcance de 40 m\n Hechizo de 1.5 seg Replica la energía en el Corazón de Azeroth de tu objetivo, lo que otorga acceso al rango 3 de su esencia principal actual durante los próximos 15 s. El Vacío amorfo tendrá un tiempo de reutilización un 30% más extenso que el tiempo de reutilización básico de la esencia que replicaste.\n\n No funciona con esencias pasivas. \n Poder secundario:\n Presencia simbiótica\nCada vez que un aliado en un radio de 40 m usa una esencia de azerita, obtienes [ 22 * (1.25)] p. de [Primary Stat] y 18 p. de celeridad durante 20 s.\n\n El aliado que usó la esencia de azerita también obtiene 18 p. de celeridad durante 20 s. Solo un aliado puede tener este efecto de celeridad a la vez.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][173886] = {name = "[q6]Gota del Vacío explosiva", additional_info = "Rango 4\nSe liga al recogerlo\nÚnico\n[q2]Uso: Infunde El Vacío amorfo en tu Corazón de Azeroth.\nPoder principal:\n Réplica de conocimiento\nAlcance de 40 m\n Hechizo de 1.5 seg Replica la energía en el Corazón de Azeroth de tu objetivo, lo que otorga acceso al rango 3 de su esencia principal actual durante los próximos 15 s. El Vacío amorfo tendrá un tiempo de reutilización un 30% más extenso que el tiempo de reutilización básico de la esencia que replicaste.\n\n No funciona con esencias pasivas. \n Poder secundario:\n Presencia simbiótica\nCada vez que un aliado en un radio de 40 m usa una esencia de azerita, obtienes [ 22 * (1.25)] p. de [Primary Stat] y 18 p. de celeridad durante 20 s.\n\n El aliado que usó la esencia de azerita también obtiene 18 p. de celeridad durante 20 s. Solo un aliado puede tener este efecto de celeridad a la vez.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
MultiLanguageItemData['mx'][173887] = {name = "[q4]Yugo de Ha-Li", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"La camada de Ha-Li se siente a gusto cazando presas desprevenidas en los cielos azules de Pandaria.\"\nBotín:\nHa-Li\nZona:\nValle de la Flor Eterna"}
