MultiLanguageItemData['mx'][178576] = {name = "Celada de negociante antigua", additional_info = "Objeto de misión\n[q]\"La celada de un negociante de origen desconocido. Es notablemente diferente a la de los negociantes que has visto en Oribos.\""}
MultiLanguageItemData['mx'][178577] = {name = "Instrucciones de filacteria de Nalthor", additional_info = "Objeto de misión\n[q]\"Instrucciones para la creación de filacteria, un ritual nigromántico que los exánimes rara vez comparten con otros.\""}
MultiLanguageItemData['mx'][178578] = {name = "Muñeca extraña", additional_info = "Objeto de misión\n[q]\"Parece ser el juguete o muñeca de un niño, de forma rara y probablemente ajeno a Azeroth.\""}
MultiLanguageItemData['mx'][178579] = {name = "Registro perdido de Stradama", additional_info = "Objeto de misión\n[q]\"Un conjunto de listas conservadas meticulosamente donde se enumeran objetos y los charcos de baba donde se encuentran. Utiliza un sistema de coordenadas completamente desconocido para ti.\""}
MultiLanguageItemData['mx'][178580] = {name = "Moneda del campeón", additional_info = "Objeto de misión\n[q]\"Una moneda curiosa que se entrega a los campeones del Teatro del Dolor cuando ganan cierta cantidad de combates. No sirve como moneda corriente, solo con fines ceremoniales.\""}
MultiLanguageItemData['mx'][178581] = {name = "Larva de gorm atiborrada", additional_info = "Objeto de misión\n[q]\"Una larva de gorm esponjosa e inquieta que parece estar a punto de madurar.\""}
MultiLanguageItemData['mx'][178582] = {name = "Máscara de la muerte dorada", additional_info = "Objeto de misión\n[q]\"Una máscara que representa el semblante de Mueh'zala, probablemente de una civilización que lo adoraba.\""}
MultiLanguageItemData['mx'][178583] = {name = "Tomo de alquimia de dragador", additional_info = "Objeto de misión\n[q]\"Un libro que detalla distintos métodos para la creación y uso de dragadores.\""}
MultiLanguageItemData['mx'][178584] = {name = "Medallón de orientación", additional_info = "Objeto de misión\n[q]\"Un medallón perteneciente a Oribos usado para orientarse en las Tierras de las Sombras. Útil para un general al mando de un ejército, pero invaluable para los comerciantes itinerantes.\""}
MultiLanguageItemData['mx'][178585] = {name = "La llave olvidada", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión"}
MultiLanguageItemData['mx'][178586] = {name = "[q2]Armamentos kyrianos", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invoca un auxiliar para recuperar el objeto robado, lo que otorga puntos de reputación con los ciudadanos de Bastión.\n[q]\"Un conjunto de armas doradas de los habitantes de Bastión, obtenidas por medios desconocidos.\""}
MultiLanguageItemData['mx'][178587] = {name = "[q2]Armamentos maldraxxi", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invoca un sirviente esquelético para recuperar el objeto robado, lo que otorga una cantidad de puntos de reputación con los ciudadanos de Maldraxxus.\n[q]\"Un conjunto de armas ornamentadas con huesos de los habitantes de Maldraxxus, obtenidas por medios desconocidos.\""}
MultiLanguageItemData['mx'][178588] = {name = "[q2]Armamentos feéricos", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invoca un feeris para recuperar el objeto robado, lo que otorga puntos de reputación con los ciudadanos de Ardenweald.\n[q]\"Un conjunto de armas talladas en madera de los habitantes de Ardenweald, obtenidas por medios desconocidos.\""}
MultiLanguageItemData['mx'][178589] = {name = "[q2]Armamentos venthyrianos", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invoca un dragador para recuperar el objeto robado, lo que otorga puntos de reputación con los ciudadanos de Revendreth.\n[q]\"Un conjunto de armas ornamentadas de los habitantes de Revendreth, obtenidas por medios desconocidos.\""}
MultiLanguageItemData['mx'][178590] = {name = "[q3]Filohueso maldraxxi legendario", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invoca un sirviente esquelético para recuperar el objeto robado, lo que otorga una gran cantidad de puntos de reputación con los ciudadanos de Maldraxxus.\n[q]\"Pese a estar cubierta en sangre, esta arma está en íntegras condiciones y ha significado la muerte de miles en los campos de Maldraxxus.\""}
