MultiLanguageItemData['mx'][180721] = {name = "[q4]Venado rúnico luz onírica encantado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los venados rúnicos majestuosos tienen la capacidad de succionar ánima de la luz ambiental de Ardenweald con sus astas complejas. El ánima sirve como nutrición y como energía para la velocidad y la magia del venado rúnico.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180722] = {name = "[q4]Venado rúnico sombrahoja encantado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 39\nYa conocido\nPrecio de venta:\n[q]\"Un venado rúnico sombrahoja es capaz de devorar criaturas tan poderosas como una matriarca gorm para defender a su rebaño. Los Cazadores salvajes usan estas monturas para viajar a los rincones más peligrosos de las Tierras de las Sombras cuando deben defender su dominio de los que amenazan la naturaleza.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180723] = {name = "[q4]Venado rúnico del heraldo encantado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los venados rúnicos del heraldo protegen ferozmente sus arboledas de semillas silvestres. Cuando las arboledas empezaron a decaer, la furia comenzó a cegar a muchos venados rúnicos.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180724] = {name = "[q4]Venado rúnico invernato encantado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereMarasmius\n: Venerado\nPrecio de venta:\n[q]\"Los venados rúnicos invernato son la montura favorita de la propia Reina del invierno, quien solo otorga una criatura semejante a sus súbditos favoritos.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180725] = {name = "[q4]Mascaclaros espinafauces", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los jinetes spriggans atan cebos sin ánima en la punta de las varas frente a sus monturas gorms para guiarlas. Es... un arte imperfecto.\"\nBotín:\nDomador de gorm Tizo\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180726] = {name = "[q4]Fauceácida pálido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nDebes haber alcanzado la reputación Exaltado con los Maestros de puntadas.\nYa conocido\nObtén el logro Solo con lo esencial para comprar esta montura.\nPrecio de venta:\n[q]\"El ácido que contiene el icor de esta criatura destiñó todo el color de su caparazón, que ha quedado de un suave tono blanco nevado.\"\nFunción de Pacto:\nLa Corte de Brasas\nPacto:\nVenthyr\n\nFunción de Pacto:\nVivero de la Reina\nPacto:\nNoctifeéricos\n\nFunción de Pacto:\nSenda de Ascensión\nPacto:\nKyrian\n\nFunción de Pacto:\nFábrica de Abominaciones\nPacto:\nNecroseñores"}
MultiLanguageItemData['mx'][180727] = {name = "[q4]Corredor brillobruma", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los spriggans traviesos y los trotadores del valle tienen una enemistad natural. Ningún trotador del valle permitiría que un jinete spriggan lo monte, porque presienten su malevolencia interna. Esto enfurece a los spriggans tramposos, que se deleitan jugando bromas crueles a estas criaturas majestuosas.\"\nÁrea:\nEspesura Veloniebla\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180728] = {name = "[q4]Pezuñumbra presto", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"De acuerdo a las baladas de Ardenweald, el nacimiento de los correpenumbras se debe al deceso de un dios salvaje benevolente. Por eso, ver a un correpenumbra es una bendición y una maldición.\"\nBotín:\nYegua de pesadilla\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180729] = {name = "[q4]Polilla polumbría", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereCazadores salvajes\n: Exaltado\nYa conocido\nPrecio de venta:\n[q]\"Estas polillas de Ardenweald prefieren los bosques oscuros y húmedos al noroeste de Ardenweald, donde siempre florecen colonias fúngicas.\"\nVendedora:\nAithlyn\nZona:\nArdenweald\nFacción:\nLos Cazadores salvajes - Exaltado\nCosto:"}
MultiLanguageItemData['mx'][180730] = {name = "[q4]Merodeador lumipelaje salvaje", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"El brillante pelaje verde de este merodeador se distingue de los tonos azules y púrpura de Ardenweald, por lo que es mucho más fácil distinguir esta variedad en los bosques de medianoche.\"\nBotín:\nValfir, el Implacable\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageItemData['mx'][180731] = {name = "[q4]Cuna de semilla silvestre", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"El cargamento más preciado de todo Ardenweald —las semillas silvestres— se aloja en esta cuna tiernamente confeccionada. Está infundida con ánima para que pueda flotar sobre el suelo.\"\nTesoro:\nAlijo de la luna\nZona:\nArdenweald"}
