MultiLanguageItemData['mx'][181815] = {name = "[q4]Tauralus pezuñaósea acorazado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El tauralus es la montura predilecta de la Casa de los Elegidos y, cuando se lo expone a la batalla, se vuelve incluso más feroz y sanguinario.\"\nBotín:\nSabriel, la Rajahuesos\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][181816] = {name = "[q4]Sigilo de adaptación de Gladiador pecaminoso", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Medallones de Gladiador (1)\nAbalorio\n+28 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Elimina cualquier efecto de pérdida de control con una duración de 5 s o más. Este efecto solo ocurre una vez cada 1 min.\n\n[q]Distinción de Gladiador (0/2)\n[q0]Emblema de Gladiador\nMedallón de Gladiador\n[q0](2) Conjunto : Aumenta un 12% tu [Primary Stat] y un 15% tu aguante en Arenas, Campos de batalla y Modo de guerra.\nPrecio de venta:"}
MultiLanguageItemData['mx'][181817] = {name = "[q4]Alaflagelada de libramorte", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete"}
MultiLanguageItemData['mx'][181818] = {name = "[q4]Riendas masticadas de Alaflagelada inmaduro", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Alaflagelada inmaduro.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los alaflageladas son una fuerza necesaria en el ciclo de vida de las Tierras de las Sombras. Son presas y también depredadores en el duro entorno de Maldraxxus.\"\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][181819] = {name = "[q4]Riendas de colmituétano", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a Colmituétano.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Colmituétano, la progenie de Colmihueso, era respetada por Amarth, el Cosechador, por su apetito insaciable, incluso si interrumpía alguno de los experimentos que el comandante quería llevar a cabo.\"\nBotín:\nNalthor Friogénesis\nZona:\nLa Destrucción Necrótica (Mítico)\n\nBotín:\nAlijo del Contendiente\nZona:\nLa Destrucción Necrótica"}
MultiLanguageItemData['mx'][181820] = {name = "[q4]Tauralus de los Elegidos acorazado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El tauralus tiene dos colas, y ambas resultan necesarias para para ahuyentar alimañas zumbantes como los piojos sangrientos.\"\nLogro:\nCosas para hacer en la muerte\nCategoría:\nSagrarios de Pactos"}
MultiLanguageItemData['mx'][181821] = {name = "[q4]Tauralus pestilente acorazado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 39\nYa conocido\n\n\n[q]\"Un tauralus completamente acorazado puede soportar una increíble cantidad de daño sin caer, por lo que resulta un valioso aliado en la batalla.\"\nPacto:\nNecroseñores\nVendedora:\nSu Zettai\nZona:\nMaldraxxus\nCosto:\n3000"}
MultiLanguageItemData['mx'][181822] = {name = "[q4]Tauralus criado para guerra acorazado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los tauralus que sirven al ejército de Maldraxxus han perdido toda compasión después de incontables cruzas, y solo visten armadura cuando demuestran que ninguna espada ni hechizo podría impedirles llevar a su jinete a la victoria.\"\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
