MultiLanguageItemData['mx'][182074] = {name = "[q4]Tauralus de los Elegidos", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un tauralus es un valioso aliado en la batalla aunque no esté acorazado, porque con sus enormes cuernos puede penetrar hasta una armadura de placas.\"\nLogro:\nLa pandilla reunida\nCategoría:\nSagrarios de Pactos"}
MultiLanguageItemData['mx'][182075] = {name = "[q4]Tauralus pezuñaósea", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Sobran motivos por los que uno debería evitar pararse detrás de un tauralus. Las pezuñas y las colas que parecen látigos están al final de la lista.\"\nBotín:\nTahonta\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182076] = {name = "[q4]Tauralus pestilente", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 23\nYa conocido\n\n\n[q]\"El tauralus es considerado una criatura intrépida, aunque hace tiempo que los eruditos de Maldraxxus se preguntan si la falta de temor se debe al pequeño tamaño de su cerebro.\"\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182077] = {name = "[q4]Tauralus criado para guerra", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los soldados de Maldraxxus protegen las Tierras de las Sombras, y precisan una montura capaz y calma cuando la victoria parece inalcanzable.\"\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182078] = {name = "[q4]Roc de carne cosido al hueso", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Solo los sastres de carne que han demostrado dominar las magias de Maldraxxus tienen el poder para construir un roc de muerte de este tamaño.\"\nProfesión:\nCostura abominable\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182079] = {name = "[q4]Riendas cubiertas de baba de Roc de muerte descomunal", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Roc de muerte descomunal.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los rocs de muerte son monstruosidades cosidas a partir de vísceras, huesos y órganos descartados por no ser necesarios para construir soldados de la Casa de Ensamblajes.\"\nBotín:\nError violeta\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182080] = {name = "[q4]Roc de plaga depredador", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El hambre eterna de Gieger es legendaria en la Casa de Ensamblajes, y no hay bestia demasiado grande ni demasiado huesuda para su estómago enorme.\"\nBotín:\nGieger\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182081] = {name = "[q4]Riendas del garrasacre colosal", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Garrasacre colosal.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Solo los mejores maestros de establos de Maldraxxus son capaces de quebrantar la voluntad de los garrasacres colosales para ofrecerles a los campeones del Ejército Inmortal un aliado aterrador en las Tierras de las Sombras.\"\nBotín:\nSuministros del Ejército Inmortal\nZona:\nMaldraxxus"}
MultiLanguageItemData['mx'][182082] = {name = "[q4]Colmisangre escabroso", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereEl Ejército Inmortal\n: Exaltado\n\n\n[q]\"Solo los colmisangre que sobreviven al Concurso de Conquista tienen el derecho de convertirse en una montura digna del Ejército Inmortal.\"\nVendedor:\nNalcorn Talsen\nZona:\nMaldraxxus\nFacción\nEl Ejército Inmortal - Exaltado\nCosto:"}
