MultiLanguageItemData['mx'][182625] = {name = "[q5]Recuerdo de un Yugo permanente", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\nSe compra a cambio de honor al proveedor Zo'kuul. Debes haber desbloqueado Tallado rúnico para comprar este recuerdo.\n\n\nYugo de la eternidad Poder de talla de runas\nEl tiempo de reutilización de Atracción letal se reduce 3 s, y durante 3 s después de lanzar Atracción letal, puedes lanzar el hechizo una segunda vez sin importar su tiempo de reutilización.\nTallado rúnico en: Cintura, Pies\nFuente: Se compra a cambio de honor al proveedor Zo'kuul. Debes haber desbloqueado Tallado rúnico para comprar este recuerdo.\nRequiere: Caballero de la muerte"}
MultiLanguageItemData['mx'][182626] = {name = "[q5]Recuerdo de las Feromonas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nFeromonas Poder de talla de runas\nTú y tus esbirros obtienen un [ Sangre : 10% /\n\nEscarcha, Profano\n15% ] de celeridad cuando están dentro de tu Muerte y descomposición. Los enemigos que dañas con tu Muerte y descomposición tienen una probabilidad de acobardarse en el lugar durante 3 s.\nTallado rúnico en: Cabeza, Cuello, Hombro\nFuente: Misión: La Gran bóveda\nRequiere: Caballero de la muerte"}
MultiLanguageItemData['mx'][182627] = {name = "[q5]Recuerdo de Supercepa", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nSupercepa Poder de talla de runas"}
MultiLanguageItemData['mx'][182628] = {name = "[q5]Recuerdo de Bryndaor", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPoder de Bryndaor Poder de talla de runas\nGolpe letal devuelve un 15% del poder rúnico gastado si te sana por más de un 10% de tu salud máxima.\nTallado rúnico en: Pies, Espalda\nFuente: Botín: Torghast, la Torre de los Condenados. Mort'regar, nivel 3+\nRequiere: Caballero de la muerte (Sangre)"}
