MultiLanguageItemData['mx'][182631] = {name = "[q5]Recuerdo de un Aura vampírica", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nAura vampírica Poder de talla de runas\nSangre vampírica te otorga un 5% de robo de vida y su duración aumenta 3 s. Además, tu Sangre vampírica afecta a todos los miembros del grupo un 50% del efecto que tiene sobre ti.\nTallado rúnico en: Pecho, Dedo\nFuente: Botín: Torghast, la Torre de los Condenados. La Parte Alta, nivel 3+\nRequiere: Caballero de la muerte (Sangre)"}
MultiLanguageItemData['mx'][182632] = {name = "[q5]Recuerdo de cero absoluto", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nCero absoluto Poder de talla de runas\nFuria de vermis de escarcha reduce su tiempo de reutilización un 50% y congela a todos los enemigos durante 3 s.\nTallado rúnico en: Cuello, Muñecas\nFuente: Botín: Torghast, la Torre de los Condenados. Intersticio Despiadado, nivel 3+\nRequiere: Caballero de la muerte (Escarcha)"}
