MultiLanguageItemData['mx'][182665] = {name = "Receta: Pecados de virtud", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a trasmutar pecados de virtud.\nRequiere Alquimia de Shadowlands (150)\nPrecio de venta:\nBolsa de menas oscura\nSe liga al recogerlo\n[q]\"Una bolsa con minerales de las Tierras de las Sombras.\"\n[q2]<Click derecho para abrir>\nRequiere Piedra porosa (4), Piedra sombreada (2)"}
MultiLanguageItemData['mx'][182666] = {name = "[q3]Fórmula: Barra de eletio encantado", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar una barra de eletio encantado.\nRequiere Encantamiento de Shadowlands (115)\nPrecio de venta:\n[q2]Barra de eletio encantado\nMaterial de profesión\n[q]\"Material que crean los jugadores con habilidad en encantamiento.\"\nPrecio de venta: \nRequiere Polvo de alma , Mena de eletio (2)"}
MultiLanguageItemData['mx'][182667] = {name = "[q2]Luz concentrada", additional_info = "Se liga al recogerlo\n[q2]Uso: Agrega este conducto a tu colección en la Forja de lazos.\n\n\nLa probabilidad de efecto crítico de Choque sagrado aumenta un 5.0% ."}
MultiLanguageItemData['mx'][182668] = {name = "[q2]Receta: Festín de hedonismo glotón", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a crear un festín de hedonismo glotón.\nRequiere Cocina de Shadowlands (75)\nRequiereCorte de Cosechadores\n: Reverenciado\nYa conocido\nPrecio de venta: \nFestín de hedonismo glotón\n[q2]Uso: ¡Prepara un festín de hedonismo glotón para alimentar hasta 35 personas de tu grupo o banda!\n\n Restaura 173077 p. de salud y 138461 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 53 p. de una estadística durante 1 h.\nPrecio de venta: \nRequiere Piraña espinosa (10), Lucio branquiplateado (10), Costillas tenebrosas (10), Anca fantasmal (10), Bagre elíseo (5), Frutas y verduras de Azeroth traficadas (5), Leche de pastador rica (5), Harina trigo áureo (5)"}
MultiLanguageItemData['mx'][182669] = {name = "Patrón: Cinturón flojo", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un cinturón flojo.\nRequiere Peletería de Shadowlands (50)\nPrecio de venta:\nCinturón flojo\nComponente de fabricación opcional\n\n[q2]Otorga la siguiente propiedad: Mayor duración de Bien alimentado\n[q]\"Un componente opcional con el que se puede crear una pieza de armadura para aumentar la duración de los efectos de Bien alimentado.\"\nPrecio de venta:\nRequiere Cuero desolado (20), Hueso pálido (20)"}
MultiLanguageItemData['mx'][182670] = {name = "Planos: Faja reforzada", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar una faja reforzada.\n[q2]Crea una faja reforzada, un componente opcional con el que puede crearse una pieza de armadura que permite que el portador no pierda la potenciación de Bien alimentado al morir en una Arena o Campo de batalla.\nRequiere Herrería de Shadowlands (50)\nPrecio de venta:\nFaja reforzada\nComponente de fabricación opcional\n\n[q2]Otorga la siguiente propiedad: Conservas Bien alimentado al morir en una Arena o Campo de batalla\n[q]\"Un componente opcional con el que se puede crear una pieza de armadura que impide que el portador pierda la potenciación de Bien alimentado al morir en una arena o campo de batalla.\"\nPrecio de venta:\nRequiere Mena de lestrita (13), Flujo luminoso (2)"}
