MultiLanguageItemData['mx'][183254] = {name = "[q5]Recuerdo de una Orden temible", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nOrden temible Poder de talla de runas\nMatar tiene un 30% de probabilidad de invocar una bestia temible para atacar a tu objetivo.\nTallado rúnico en: Pecho, Dedo\nFuente: Botín: Torghast, la Torre de los Condenados. Salón de Skoldus, nivel 3+\nRequiere: Cazador (Bestias)"}
MultiLanguageItemData['mx'][183255] = {name = "[q5]Recuerdo del Despiertallamas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPicadura de cobra de despiertallamas Poder de talla de runas\nDisparo de cobra tiene un 50% de probabilidad de hacer que tu Matar no consuma enfoque. (Probabilidad de que accione: 50%)\nTallado rúnico en: Piernas, Pies\nFuente: Botín: Torghast, la Torre de los Condenados. La Fragua de Almas, nivel 3+\nRequiere: Cazador (Bestias)"}
