MultiLanguageItemData['mx'][183284] = {name = "[q5]Recuerdo de Escape de la realidad", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nEscape de la realidad Poder de talla de runas\nDespués de usar Trascendencia: Transferencia, puedes volver a usarla durante 10 s, sin importar cuál sea su tiempo de reutilización.\n\n Durante este período, si lanzas Vivificar sobre ti mismo, su sanación aumenta un 70% y recuperas un 50% de su costo.\nTallado rúnico en: Cuello, Pecho\nFuente: Misión: La Gran bóveda\nRequiere: Monje"}
MultiLanguageItemData['mx'][183285] = {name = "[q5]Recuerdo de las sobrevestes de certeza rauda", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\nSe compra a cambio de honor al proveedor Zo'kuul. Debes haber desbloqueado Tallado rúnico para comprar este recuerdo.\n\n\nA rodar Poder de talla de runas Instante\nDurante [ Torpedo de chi / Rodar], eres inmune a efectos de enraizamiento y frenado.\nTallado rúnico en: Cintura, Pies\nFuente: Se compra a cambio de honor al proveedor Zo'kuul. Debes haber desbloqueado Tallado rúnico para comprar este recuerdo.\nRequiere: Monje"}
MultiLanguageItemData['mx'][183286] = {name = "[q5]Recuerdo de Shaohao", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPoder de Shaohao Poder de talla de runas\nPalma del tigre tiene un 40% de probabilidad de infligir un 300% de daño normal y reducir 2 s más el tiempo de reutilización restante de tus brebajes.\nTallado rúnico en: Pecho, Dedo\nFuente: Botín: Torghast, la Torre de los Condenados. Mort'regar, nivel 3+\nRequiere: Monje (Maestro cervecero)"}
MultiLanguageItemData['mx'][183287] = {name = "[q5]Recuerdo de Pasiones calcinadas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPasiones calcinadas Poder de talla de runas\nTu Aliento de fuego incendia tu pierna derecha durante 8 s, lo que hace que Patada oscura y Patada giratoria de la grulla inflijan un 100% más de daño de fuego y restablezcan la duración de tu Aliento de fuego sobre tu objetivo.\nTallado rúnico en: Pies, Espalda\nFuente: Botín: Torghast, la Torre de los Condenados. Intersticio Despiadado, nivel 3+\nRequiere: Monje (Maestro cervecero)"}
