MultiLanguageItemData['mx'][184013] = {name = "[q4]Araña de guerra sañosa", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\nPrecio de venta: \n[q]\"Si ser un bullicioso miembro de la Horda no alcanza para inspirar suficiente temor en tu oponente, agrega una araña gigante.\"\nJcJ:\nShadowlands: Temporada 1\nRecompensa de temporada en arena o campos de batalla puntuados"}
MultiLanguageItemData['mx'][184014] = {name = "[q4]Araña de guerra sañosa", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\nPrecio de venta: \n[q]\"Si ser un miembro de la Alianza valeroso no alcanza para inspirar suficiente temor en tu oponente, agrega una araña gigante.\"\nJcJ:\nShadowlands: Temporada 1\nRecompensa de temporada en arena o campos de batalla puntuados"}
