MultiLanguageItemData['mx'][184016] = {name = "[q4]Ala de vagador", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 [Agilidad o Fuerza]\n[q2]Uso: Te conviertes en el depredador husmeador durante 10 s, lo que te otorga 69 p. de velocidad y te permite abalanzarte sobre el próximo enemigo dentro de un radio de 8 m para infligir 3874 p. de daño físico. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184017] = {name = "[q4]Correa de Bargast", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 [Agilidad o Fuerza]\n[q2]Uso: Crea un Lazo del montero con el objetivo aliado durante 30 s. 25% del daño que recibas se redirigirá a tu aliado enlazado, hasta un máximo de [ 11389 * (1 + Versatilidad)] p. de daño en total. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184018] = {name = "[q4]Corazón de Al'ar astillado", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 [Agilidad o Fuerza]\n[q2]Equipar: Absorbe hasta 10234 p. de daño de un ataque letal. Cuando ocurre este efecto, haces erupción con una ráfaga de llamas que inflige [ 2433 * (1 + Versatilidad)] p. de daño de fuego a los aliados y enemigos cercanos, y recuperas [ 7025 * (1 + Versatilidad)] p. de salud.\n\n Este efecto solo puede ocurrir una vez cada 8 min.\nPrecio de venta:"}
MultiLanguageItemData['mx'][184019] = {name = "[q4]Encendedor de almas", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 intelecto\n[q2]Uso: Activa Encendedor de almas y sacrifica hasta 2157 p. de salud durante 15 s para potenciar Ráfaga abrasadora.\n\n Reactívalo para lanzar Ráfaga abrasadora, que inflige [ 1541 * (1 + Versatilidad)] p. de daño de fuego divididos entre los enemigos en un cono de 40 m y también un 40% más de daño, según el tiempo que Encendedor de almas haya estado activo.\n\n El daño aumenta con cada enemigo golpeado, hasta un máximo de 5 enemigos. (Tiempo de reutilización: 1 min)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184020] = {name = "[q4]Penacho de plumaje humeante", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 intelecto\n[q2]Uso: Infunde a tu aliado con un penacho de plumas de fénix que lo sanan [ 5199 * (1 + Versatilidad)] p. después de 6 s. La sanación puede aumentar hasta un 25% según la salud faltante de tu objetivo. Si tu aliado sufre daño letal, este efecto se activa instantáneamente. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184021] = {name = "[q4]Glifo de asimilación", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 intelecto\n[q2]Uso: Inflige 1786 p. de daño arcano a un enemigo durante 10 s.\n\n Si tu objetivo muere mientras está bajo los efectos de Glifo de asimilación, tu maestría aumenta 160 p. durante un tiempo equivalente a 2 veces la duración restante del glifo. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184022] = {name = "[q4]Infusión consumidora", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 intelecto\n[q2]Equipar: Lanzar un hechizo que inflige daño hace que tu próxima sanación para un solo objetivo otorgue 138 p. de robo de vida durante 10 s. Este efecto solo puede ocurrir una vez cada 30 s.\nPrecio de venta:"}
MultiLanguageItemData['mx'][184023] = {name = "[q4]Púa glotona", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 fuerza\n[q2]Equipar: Tus habilidades que infligen daño tienen una gran probabilidad de infligir 116 p. de daño físico y sanarte un 300% del daño infligido. Si este efecto sana de más, inflige [ 98 * 5 * (1 + Versatilidad)] p. de daño físico divididos entre los enemigos cercanos durante 15 s, pero anula el efecto de robo de vida.\n\n El daño aumenta por cada enemigo golpeado, hasta un máximo de 5 enemigos.\nPrecio de venta:"}
MultiLanguageItemData['mx'][184024] = {name = "[q4]Partitura macabra", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 [Agilidad o Fuerza o Intelecto]\n[q2]Uso: Aparecen cuatro compañeros de baile en un patrón aleatorio a tu alrededor. Acercarte a cada uno te otorga 40 p. de celeridad y 23 p. de velocidad durante 20 s. Este efecto se acumula. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184025] = {name = "[q4]Recuerdo de pecados del pasado", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 [Agilidad o Fuerza]\n[q2]Uso: Tus siguientes 5 habilidades de daño aplican Mente devastada, lo que inflige 651 p. de daño de las sombras y aumenta el daño que recibe el objetivo de Mente devastada un 1% durante 5 s, se acumula hasta 25 veces. (1.5s de reutilización) (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][184026] = {name = "[q4]Cadena odiosa", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+28 agilidad\n[q2]Equipar: Mientras tu porcentaje de salud es superior al de tu objetivo, tus habilidades tienen una probabilidad muy alta de infligir [ 181 * (1 + Versatilidad)] p. de daño físico.\n\n Mientras tu porcentaje de salud es inferior al de tu objetivo, tus habilidades tienen una probabilidad muy alta de sanarte [ 247 * (1 + Versatilidad)] p. de salud.\nPrecio de venta:"}
MultiLanguageItemData['mx'][184027] = {name = "[q4]Heráldica de la Legión Pétrea", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+31 [Agilidad o Fuerza]\n[q2]Equipar: Jura lealtad a la Legión Pétrea y aumenta 43 p. tu versatilidad. Aumenta un 5% por cada legionario pétreo que hay en tu grupo.\nPrecio de venta:"}
MultiLanguageItemData['mx'][184028] = {name = "[q4]Cantoral de cabalista", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+31 intelecto\n[q2]Equipar: Te unes al coro carmesí. Cada minuto, tu golpe crítico aumenta ( 43 * 3) p. durante 30 s hasta volver a la normalidad. Este efecto aumenta un 5% por cada miembro del coro carmesí que hay en tu grupo.\nPrecio de venta:"}
