MultiLanguageItemData['mx'][186565] = {name = "[q5]Recuerdo de Transferencia desenfrenada", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nTransferencia desenfrenada Poder de talla de runas Instante\nLa fuerza obtenida por Hora de la muerte aumenta un 3% y perdura durante 2 s más. Mientras estás dentro de la zona de tu Hora de la muerte, tu generación de poder rúnico aumenta un 20%.\nTallado rúnico en: Pecho, Cintura\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Caballero de la muerte"}
MultiLanguageItemData['mx'][186566] = {name = "[q5]Recuerdo de Sentencia final", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nSentencia final Poder de talla de runas Instante\nCuando se aplica Cadenas para los indignos a un enemigo, obtienes al instante una runa y tu daño aumenta un 4%, hasta un máximo de 20% durante 15 s.\nTallado rúnico en: Cabeza, Hombro, Espalda\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Caballero de la muerte"}
MultiLanguageItemData['mx'][186567] = {name = "[q5]Recuerdo de Hambre insaciable", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nHambre insaciable Poder de talla de runas Instante\nCuando termina, Neblina pululante inflige ([86.42% of Attack Power]) p. de daño de las sombras a 5 enemigos cercanos, y te sana por una cantidad equivalente al 25% del daño infligido. El daño aumenta un 2% por cada 1 p. de poder rúnico gastados mientras la Neblina pululante esté activa.\nTallado rúnico en: Piernas, Pies\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Caballero de la muerte"}
MultiLanguageItemData['mx'][186568] = {name = "[q5]Recuerdo de Frenesí de la abominación", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nFrenesí de la abominación Poder de talla de runas Instante\nLa duración de Extremidad de abominación aumenta 4 s y la frecuencia con la que te otorga [ Sangre : Escudo óseo / Escarcha : Helada blanca / Profano : Corrupción rúnica ] aumenta 2 s. La primera vez que un enemigo recibe daño de Extremidad de abominación, recibe un 20% más de daño de ti durante 12 s. (20s de reutilización)\nTallado rúnico en: Pies, Muñecas, Manos\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Caballero de la muerte"}
MultiLanguageItemData['mx'][186569] = {name = "Nido de aguijoneador furioso", additional_info = "Objeto de misión\n[q2]Uso: Lanza el nido a un heraldo e interrumpe su concentración para que se vuelva vulnerable a los ataques. (15 Seg Reutilización)"}
MultiLanguageItemData['mx'][186570] = {name = "[q5]Recuerdo de Gloria", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nGloria Poder de talla de runas Instante\nEstandarte del conquistador afecta a 1 aliado más y cada [ Armas : 20 ] [ Furia : 25 /\n\nProtección\n10 ] p. de ira que gastas mientras está activo, aumenta 0.5 s la duración de tu estandarte.\nTallado rúnico en: Pecho, Cintura\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Guerrero"}
MultiLanguageItemData['mx'][186572] = {name = "[q5]Recuerdo de la oleada pecaminosa", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nOleada pecaminosa Poder de talla de runas Instante\nCondenar extiende [ Armas : 1.5 s la duración de Machaque colosal ] [ Furia : 2.0 s la duración de Temeridad /\n\nProtección\n2.5 s la duración de Avatar ] (500ms de reutilización)\nTallado rúnico en: Cabeza, Cuello, Hombro\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Guerrero"}
