MultiLanguageItemData['mx'][186576] = {name = "[q5]Recuerdo de Furia de la naturaleza", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nFuria de la naturaleza Poder de talla de runas Instante\nLa duración de Réplica ancestral aumenta 3 s y los enemigos reciben [([13.83% of Attack Power])o * 3] p. de daño de naturaleza durante 6 s. Se acumula hasta 6 veces.\nTallado rúnico en: Muñecas, Manos, Espalda\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Guerrero"}
MultiLanguageItemData['mx'][186577] = {name = "[q5]Recuerdo de enjambre desbocado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nEnjambre desbocado Poder de talla de runas Instante\nEnjambre adaptable tiene un 60% de probabilidad de dividirse en dos enjambres cada vez que salta.\nTallado rúnico en: Pecho, Muñecas\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto."}
