MultiLanguageItemData['mx'][186635] = {name = "[q5]Recuerdo de Placer pecaminoso", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPlacer pecaminoso Poder de talla de runas Instante\nConsumir [ Arcano : Lanzamiento libre ] [ Fuego : una carga de Explosión de fuego /\n\nEscarcha\nCongelación cerebral ] reduce 4 s del tiempo de reutilización de Espejos de tormento. Si se disipa Espejos de tormento, el tiempo de reutilización se reduce 45 s.\nTallado rúnico en: Piernas, Pies\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Mago"}
MultiLanguageItemData['mx'][186636] = {name = "[q3]Jaula de faucerratas", additional_info = "Torghast, la Torre de los Condenados\n[q2]Uso: Libera una colonia de faucerratas que atacan cuando se les ordena. (5 Min Reutilización)\n[q]\"Varias faucerratas te observan con ojos lastimosos a través de los barrotes.\""}
MultiLanguageItemData['mx'][186637] = {name = "[q4]Planeador de Tazavesh", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Todo tipo de negociantes utilizan estos planeadores para desplazarse por Tazavesh y otros puestos de avanzada similares. También los usan para transportar sus productos.\"\nLogro:\n¿Quién se va a dar cuenta?\nCategoría:\nCalabozo de Shadowlands"}
MultiLanguageItemData['mx'][186638] = {name = "[q4]Planeador de maestro de cártel", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Solo los líderes más ricos de los cárteles pueden adquirir los metales necesarios para fabricar el planeador de maestro de cártel.\"\nBotín:\nSo'leah\nZona:\nTazavesh, el Mercado Velado"}
MultiLanguageItemData['mx'][186639] = {name = "[q4]Planeador de consejero de Xy", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El cártel Xy comercia en muchas monedas, pero ninguna es tan valiosa para su círculo íntimo como la lealtad.\"\nFuente:\n[CENSURADO]"}
MultiLanguageItemData['mx'][186640] = {name = "[q4]Planeador de vándalo", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un planeador personalizado y poco común, usado habitualmente para reuniones clandestinas. Es tan silencioso que es casi imposible de detectar, lo que lo convierte en la herramienta predilecta de quienes trabajan en las sombras.\"\nFacción:\nVándalos de Forja de Maná\nReconocimiento:\n8\nUbicación:\nPunto Sombrío"}
MultiLanguageItemData['mx'][186641] = {name = "[q4]Arnés de magullador domado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cuando se trata de domar a los devoradores, todo lo que se necesita es un poco de ánima y mucha paciencia. Y muchas pociones de sanación.\"\nBotín:\nSuministros del Códice del archivista\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186642] = {name = "[q4]Riendas de Venganza", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Sylvanas perdió una parte de sí misma el día que Arthas le quitó la vida, y la oscuridad en su interior creció para llenar ese vacío.\"\nBotín:\nLady Sylvanas Brisaveloz\nZona:\nSagrario de Dominación\nDifficulty:\nMítica"}
MultiLanguageItemData['mx'][186643] = {name = "[q4]Riendas de la Errante", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Una cierva curiosa e inquisitiva. Su intención no es preocupar a su amo, pero se distrae con facilidad. Especialmente con todas las cosas nuevas que hay para ver en Korthia.\"\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186644] = {name = "[q4]Cueroesquirla de berilo", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estos cueroesquirlas se esconden fácilmente entre los arbustos bajos, y es raro encontrar a uno domesticado.\"\nBotín:\nSuministros de la Avanzada de la Muerte\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186645] = {name = "[q4]Cueroesquirla carmesí", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cuando arrastraron a Korthia a las Fauces, las pocas especies que sobrevivieron fueron las más tenaces.\"\nBotín:\nMalbog\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186646] = {name = "[q4]Umbragarra", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un cueroesquirla mayor. Dentro de todo, Umbragarra era bastante amigable con los korthianos. Se creía que había sido víctima de la calamidad\"\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186647] = {name = "[q4]Cueroesquirla ámbar", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereAvanzada de la Muerte\n: Reverenciado\nYa conocido\n\n\n[q]\"Los colores vívidos de la fauna korthiana indican que, o los animales tienen pocos depredadores, o tienen la fortaleza necesaria para defenderse.\"\nVendedora:\nDuquesa Mynx\nZona:\nKorthia\nFacción:\nAvanzada de la Muerte - Venerado\nCosto:\n5000"}
MultiLanguageItemData['mx'][186648] = {name = "[q4]Alatajo surcacielos", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereEl Códice de los Archivistas\n: Nivel 6\n\n\n[q]\"El cuero de este alatajo es ligero, lo que le permite volar, pero también es muy resistente, por lo que puede sobrevivir el paso hacia las Fauces.\"\nVendedor:\nArchivista Roh-Suir\nZona:\nKorthia\nFacción:\nEl Códice de los Archivistas - Nivel 6\nCosto:\n5000"}
MultiLanguageItemData['mx'][186649] = {name = "[q4]Alatajo feroz", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los alatajos por lo general mantienen la distancia con otras especies korthianas, pero, con tiempo y paciencia, se pueden domesticar.\"\nBotín:\nSuministros de la Avanzada de la Muerte\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186650] = {name = "[q3]Suministros de la Avanzada de la Muerte", additional_info = "[q7]Se liga a la tropa\nÚnico\n[q2]<Click derecho para abrir>\nPrecio de venta:"}
MultiLanguageItemData['mx'][186651] = {name = "[q4]Alatajo luxocaso", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los alatajos se pueden encontrar por todo Korthia. Arman sus nidos en colinas altas y árboles.\"\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186652] = {name = "[q4]Alatajo granate", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"En otra época, Korthia era famoso por sus flores rojas brillantes. Muchas especies las consumían o rodaban sobre ellas y, como consecuencia, adoptaban su tinte rojo.\"\nBotín:\nRelwik, el Desafiante\nZona:\nKorthia"}
MultiLanguageItemData['mx'][186653] = {name = "[q4]Brazal de Hrestimorak", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"La perfidia de Hrestimorak fue notoria cuando traicionó a su pueblo para conseguir poder. Al enfrentarse a la condenación en las Fauces, intentó derrocar al Carcelero... un acto ingenuo que solo le otorgaría una eternidad de tormento.\"\nLogro:\nGloria del asaltante dominante\nZona:\nSagrario de Dominación"}
MultiLanguageItemData['mx'][186654] = {name = "[q4]Brazalete de Salaranga", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Salaranga fue la más astuta de su pueblo y se escondió en las Madrigueras Bestiarias. Atacó al Desterrado con una horda de aliados bestiales, pero fue en vano.\"\nLogro:\nRompiendo las cadenas\nZona:\nKorthia y las Fauces"}
MultiLanguageItemData['mx'][186655] = {name = "[q4]Riendas de destrero jurafauces", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El destino de todos los caballos que sirven de montura.\"\nLogro:\nMaestro impecable\nZona:\nTorghast, la Torre de los Condenados"}
MultiLanguageItemData['mx'][186656] = {name = "[q4]Riendas de destrero penumbroso de sagrario", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Solo los tenientes más poderosos del Carcelero son dignos de recibir estos corceles que acechan los salones de la torre.\"\nBotín:\nLas nueve\nZona:\nSagrario de Dominación"}
MultiLanguageItemData['mx'][186657] = {name = "[q4]Riendas de destrero penumbroso ligado al alma", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Ve'nari tiene muchos métodos para escabullirse por las Fauces y frustrar los planes del Carcelero. Uno de tantos consiste en atar los esbirros del Carcelero.\"\nBotín:\nRegalo misterioso de Ve'nari\nZona:\nLas Fauces"}
MultiLanguageItemData['mx'][186659] = {name = "[q4]Riendas de destrero caído", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los aullidos del destrero resuenan por las Fauces mientras continúa su galope eterno por toda la tierra, buscando hasta el final una salida de los tomentos sin fin que lo han obligado a soportar.\"\nBotín:\nDestrero caído\nZona:\nLas Fauces"}
