MultiLanguageItemData['mx'][186671] = {name = "Técnica de Runa vantus: Sagrario de Dominación", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar una Runa vantus: Sagrario de Dominación.\nRequiere Inscripción de Shadowlands (100)\nPrecio de venta: \nRuna vantus: Sagrario de Dominación\n[q2]Uso: Te armonizas con las energías del jefe de banda del Sagrario de Dominación y aumentas 1875 p. tu versatilidad cuando luchas contra ese jefe. Este efecto dura una semana entera.\n\n Solo puedes usar una runa vantus por semana.\nPrecio de venta:\nRequiere Tinta luminosa (10), Tinta umbría (10), Tinta serena , Papiro oscuro"}
MultiLanguageItemData['mx'][186672] = {name = "Alas efímeras", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Salta hacia adelante con alas efímeras, lo que reduce la velocidad de caída durante 10 s. Luego salta a una ubicación cercana. (6 Seg Reutilización)"}
MultiLanguageItemData['mx'][186673] = {name = "[q5]Recuerdo de Afinidad de almas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nAfinidad de almas Nivel 80 Poder de talla de runas Instante\nTú y tu espíritu afín obtienen una estadística secundaría bonificada según su Pacto. Esta bonificación se divide a la mitad para tu espíritu afín. Sin embargo, ambas bonificaciones se duplican cuando el vínculo está potenciado.\n\nKyrian :La maestría aumenta 571 p.\nNoctifeéricos : La celeridad aumenta un 6%.\nVenthyr : La probabilidad de golpe crítico aumenta un 6%.\nNecroseñores : La versatilidad aumenta un 6%.\nTallado rúnico en: Cuello, Hombro\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Druida"}
MultiLanguageItemData['mx'][186676] = {name = "[q5]Recuerdo del Embate tóxico", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nEmbate tóxico Poder de talla de runas Instante\nCuando Sepsis termina sobre tu objetivo, [ Asesinato : obtienes Subidón de adrenalina y Hojas de las sombras ] [ Forajido : obtienes Hojas de las sombras y aplicas Vendetta a tu objetivo actual ] [ Sutileza : obtienes Subidón de adrenalina y aplicas Vendetta a tu objetivo actual ] durante 10 s.\nTallado rúnico en: Pecho, Piernas, Pies\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Pícaro"}
MultiLanguageItemData['mx'][186677] = {name = "[q0]Engarce metálico", additional_info = "Precio de venta:"}
MultiLanguageItemData['mx'][186678] = {name = "[q3]Alijo de armas fauceforjadas", additional_info = "Torghast, la Torre de los Condenados\n[q2]Uso: Las Armas fauceforjadas te ayudan en combate durante 2 min. (5 Min Reutilización)\n[q]\"Estas armas parecen tener vida propia.\""}
MultiLanguageItemData['mx'][186679] = {name = "[q3]Pergamino de dominación", additional_info = "Torghast, la Torre de los Condenados\n[q2]Uso: Somete a tu control a un objetivo enemigo que no sea de élite durante 2 min. Cuando la runa desaparece, el objetivo controlado explota e inflige daño a todos los que están cerca. (5 Min Reutilización)\n[q]\"No te quedes mirando las runas mucho tiempo.\""}
MultiLanguageItemData['mx'][186680] = {name = "[q2]Bota llena de oro", additional_info = "Se liga al recogerlo\n[q]\"No olvides que está llena de oro, podrías lastimarte un dedo.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageItemData['mx'][186684] = {name = "Recuerdos de tiempos más felices", additional_info = "[q2]Uso: Recuerda tiempos más felices en Oribos, antes de que las Fauces ganaran más poder. Dura 168 h.\n[q]\"No causa efecto alguno en la oscuridad que se avecina, pero hace que se vea más bonita.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][186685] = {name = "[q2]Fragmento de reliquia", additional_info = "Reliquias korthianas\nSe liga al recogerlo\n[q2]Uso: Entrega los fragmentos de reliquias al archivista Roh-Suir en el Relicario de Recuerdos y genera 1 p. de investigación catalogada.\n[q]\"Aún pueden apreciarse símbolos antiguos en la superficie de estos fragmentos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][186686] = {name = "[q3]Huesos oráculo pálidos", additional_info = "Se liga al usarlo\nJuguete\n[q2]Uso: Consulta los huesos para conocer tu futuro. (15 Min Reutilización)\n[q]\"Un conjunto de huesos pequeños con símbolos tallados que permiten al usuario conocer su futuro.\""}
MultiLanguageItemData['mx'][186687] = {name = "[q5]Recuerdo de Espíritus celestiales", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nEspíritus celestiales Poder de talla de runas Instante\nEl tiempo de reutilización de Convocar los espíritus se reduce un 50% y su duración se reduce un 25%. Convocar los espíritus tiene más probabilidades de lanzar un hechizo o habilidad excepcional.\nTallado rúnico en: Piernas, Pies\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Druida"}
MultiLanguageItemData['mx'][186688] = {name = "[q3]Cubo de lavado lleno de oro", additional_info = "Se liga al recogerlo\n[q]\"El asa ayuda mucho a mover el oro que contiene.\"\n[q2]<Click derecho para abrir>\nPrecio de venta:"}
