MultiLanguageItemData['mx'][186708] = {name = "[q2]Taza para pinceles llena de oro", additional_info = "Se liga al recogerlo\n[q]\"Nadie suele cuestionar los peculiares intereses de un dragador, en especial uno que brinda un servicio tan fundamental como la reparación de equipo.\"\n[q2]<Click derecho para abrir>\nPrecio de venta:"}
MultiLanguageItemData['mx'][186710] = {name = "[q5]Recuerdo del obediente", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nObediencia Poder de talla de runas Instante\nFlagelación ahora también aumenta tu versatilidad un 0.5%. Cada punto de combo gastado mientras Flagelación está activa reduce 1 s su tiempo de reutilización. (100ms de reutilización)\nTallado rúnico en: Cabeza, Espalda\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Pícaro"}
MultiLanguageItemData['mx'][186712] = {name = "[q5]Recuerdo de Púa mortal", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPúa mortal Poder de talla de runas Instante\nPúa ósea serrada tiene 2 cargas más y lanza 1 púas óseas más a los enemigos cercanos.\nTallado rúnico en: Muñecas, Manos\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Pícaro"}
MultiLanguageItemData['mx'][186713] = {name = "[q4]Anillo de control de Nilganihmaht", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"De todos los gigantes que se atrevieron a desafiar al Carcelero, Nilganihmaht fue el más arrogante. Por su transgresión, la mano cortada del gigante se escondió en un velo de tormentos, y los anillos que pueden volver a invocarla se esparcieron por todas las Fauces.\"\nZona:\nLas Fauces"}
MultiLanguageItemData['mx'][186714] = {name = "[q3]Informe de investigación: Cristal que todo lo ve", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te permite ver y encontrar criaturas que tienen fragmentos de reliquias de forma permanente.\nRequiere el nivel 2 de investigación con el Códice de los Archivistas.\n[q]\"Roh-Suir pudo reproducir la investigación en un cristal que todo lo ve, lo que te permitió colocar uno en el Bastón relicario para detectar otras reliquias.\""}
MultiLanguageItemData['mx'][186715] = {name = "[q3]Informe de investigación: Aleaciones mejoradas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te permite mejorar tus objetos de Korthia y las Fauces al rango 10.\n[q]\"El análisis de los efectos de la magia de dominación sobre objetos de Korthia y las Fauces ha posibilitado mejores aleaciones que nos permiten crear objetos más resistentes y poderosos.\""}
MultiLanguageItemData['mx'][186716] = {name = "[q3]Informe de investigación: Santuarios ancestrales", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te permite interactuar con las espadas que están cerca de santuarios ancestrales, lo que te otorga la habilidad de alcanzar reliquias inaccesibles.\nRequiere el nivel 5 de investigación con el Códice de los Archivistas.\n[q]\"Una investigación más profunda sobre la misteriosa clave de entendimiento que recuperaste de la Falla nos ha permitido comprender cómo interactuar con las antiguas espadas de los santuarios que se encuentran dispersas por Korthia.\""}
MultiLanguageItemData['mx'][186717] = {name = "[q3]Informe de investigación: Aleaciones adaptables", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te permite mejorar tus objetos de Korthia y las Fauces al rango 5.\nRequiere el nivel 6 de investigación con el Códice de los Archivistas y reconocimiento 61 o superior.\n[q]\"Las investigaciones adicionales a partir de la recuperación de reliquias han posibilitado el descubrimiento de nuevas aleaciones adaptables con las que podremos aumentar el poder de los objetos tocados por la magia de dominación en Korthia y las Fauces.\""}
MultiLanguageItemData['mx'][186718] = {name = "[q2]Kit de reparación de teletransportador", additional_info = "Se liga al recogerlo\nRequiere el nivel 3 de investigación con el Códice de los Archivistas.\n[q]\"Hay algo que es universal: hacia la derecha se aprieta, hacia la izquierda se afloja. Se necesita para reparar los teletransportadores antiguos de Korthia, lo que te permite acceder a bóvedas ocultas.\""}
MultiLanguageItemData['mx'][186721] = {name = "[q3]Tratado: Las abundantes reliquias de las Tierras de las Sombras", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te otorga de manera permanente la habilidad de encontrar reliquias que otorgan reputación adicional con las facciones de las zonas de las Tierras de las Sombras de forma permanente cuando completas misiones diarias y de mundo o cuando derrotas criaturas raras en sus reinos.\nRequiere el nivel 6 de investigación con el Códice de los Archivistas."}
MultiLanguageItemData['mx'][186722] = {name = "[q3]Tratado: El estudio del ánima y cómo aprovechar cada gota", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te otorga de forma permanente la habilidad de encontrar 25 más de ánima cuando completas misiones diarias y de mundo, despojas tesoros o matas criaturas raras en las Tierras de las Sombras.\nRequiere el nivel 5 de investigación con el Códice de los Archivistas."}
MultiLanguageItemData['mx'][186724] = {name = "[q2]Técnica: Contrato: Avanzada de la Muerte", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a crear un Contrato: Avanzada de la Muerte.\nRequiere Inscripción de Shadowlands (60)\nRequiereAvanzada de la Muerte\n: Reverenciado\nPrecio de venta: \nContrato: Avanzada de la Muerte\n[q2]Uso: Firma un contrato con la Avanzada de la Muerte que te permitirá ganar reputación con ellos cada vez que completes una misión de mundo en las Tierras de las Sombras.\nRequiereAvanzada de la Muerte\n: Amistoso\nRequiere Tinta luminosa , Tinta umbría , Papiro oscuro"}
MultiLanguageItemData['mx'][186725] = {name = "Pan de harina de hueso", additional_info = "[q2]Uso: Restaura ( 22500 / 5 * 20) p. de salud durante 20 s. Debes permanecer sentado mientras comes."}
