MultiLanguageItemData['mx'][187132] = {name = "[q5]Recuerdo de Estaciones de abundancia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nEstaciones de abundancia Poder de talla de runas Instante\nLanzar Bendición de verano otorga Equinoccio después de 10 s.\n\nEquinoccio: La efectividad de Bendición de verano aumenta un 100% durante 10 s.\nTallado rúnico en: Piernas, Pies\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Paladín"}
MultiLanguageItemData['mx'][187133] = {name = "[q3]Sombrerito embrujado", additional_info = "Corte de Brasas\nSe liga al recogerlo\nÚnico\n[q]\"Un regalo para tu mayordomo dragador que le brinda la opción de usar un sombrero de bruja.\""}
MultiLanguageItemData['mx'][187134] = {name = "[q4]Engarzador transaleación", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Agrega una ranura a un objeto de la temporada 2 de Shadowlands que no tenga una. Se puede usar en yelmos, collares, brazales, cinturones o anillos."}
MultiLanguageItemData['mx'][187136] = {name = "[q7]Informe de investigación: Técnicas de análisis de reliquias", additional_info = "[q7]Se liga a la tropa\nÚnico\n[q2]Uso: Obtienes un 50% más de reputación con el Códice de los Archivistas cuando le entregas reliquias al archivista.\nRequiere el nivel 6 de investigación con el Códice de los Archivistas.\n[q]\"Al perfeccionar las técnicas de investigación, el archivista puede recabar más conocimientos de cada fragmento que le entregan.\""}
MultiLanguageItemData['mx'][187137] = {name = "[q3]Informe de investigación: Técnicas de búsqueda de reliquias", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te otorga un 20% de probabilidad de encontrar más fragmentos de reliquias cuando despojas criaturas raras y tesoros en Korthia.\n[q]\"Saber cómo identificar las reliquias perdidas es fundamental para nuestros esfuerzos. En este informe se describen consejos para conseguir más fragmentos de reliquias de fuentes comunes en algunas ocasiones.\""}
MultiLanguageItemData['mx'][187138] = {name = "[q3]Informe de investigación: Primeras aleaciones", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te permite mejorar tus objetos de Korthia y las Fauces al rango 6.\nRequiere el nivel 6 de investigación con el Códice de los Archivistas y reconocimiento 75 o superior.\n[q]\"Ahora que contamos con el Códice de los Archivistas completo, comprendemos el poder coercitivo de la magia de dominación y su relación con las primeras aleaciones de las Tierras de las Sombras, lo que nos permite potenciar aún más tus objetos de Korthia y las Fauces.\""}
MultiLanguageItemData['mx'][187139] = {name = "[q3]Corazón de sombra embotellada", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Rompe el sello de la botella, lo que permite que la sombra que está adentro te posea un periodo corto. (1 Hora Reutilización)\n[q]\"Será mejor no alterar su contenido.\""}
MultiLanguageItemData['mx'][187140] = {name = "[q3]Anillo de duplicidad", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: Usa un poco de la magia restante en el anillo para invocar un reflejo exacto que copia tus acciones. (1 Hora Reutilización)"}
