MultiLanguageItemData['mx'][187223] = {name = "[q5]Recuerdo de las Semillas de crecimiento desenfrenado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nSemillas de crecimiento desenfrenado Poder de talla de runas Instante\nCada pulso del efecto de daño de Transfusión feérica reduce el tiempo de reutilización de Espíritu feral en 9.0 s y aumenta tu probabilidad de golpe crítico un 4% durante 15 s.\nTallado rúnico en: Cabeza, Manos\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Pícaro"}
MultiLanguageItemData['mx'][187224] = {name = "[q5]Recuerdo del Conducto elemental", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nConducto elemental Poder de talla de runas Instante\nUn máximo de 5 objetivos aliados sanados por Cosecha en cadena reciben Mareas vivas. Un máximo de 5 objetivos enemigos dañados por Cosecha en cadena reciben Choque de llamas. Los golpes críticos de Choque de llamas reducen 1.0 s el tiempo de reutilización de Cosecha en cadena.\nTallado rúnico en: Pecho, Muñecas\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto."}
MultiLanguageItemData['mx'][187225] = {name = "[q5]Recuerdo del Detritus de alma languideciente", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nDetritus de alma languideciente Poder de talla de runas Instante\nCuando Diezmo arrasador genera fragmentos de alma, obtienes un 100% más de velocidad de movimiento y un 45% de probabilidad de golpe crítico durante 8 s. Pero si Diezmo arrasador expira, obtienes un 33% más de velocidad de movimiento y un 15% más de probabilidad de golpe crítico.\nTallado rúnico en: Pecho, Muñecas, Espalda\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Brujo"}
MultiLanguageItemData['mx'][187226] = {name = "[q5]Recuerdo de los Fragmentos de aniquilación", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nFragmento de aniquilación Poder de talla de runas Instante\nDescarga exterminadora también aumenta un 100% la probabilidad de golpe crítico y un 50% el daño de golpe crítico de [ Destrucción : Incinerar / Drenar alma ] [ Demonología : Descarga demoníaca /\n\nAflicción\n Descarga de las sombras ]\nTallado rúnico en: Cintura, Piernas\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Brujo"}
MultiLanguageItemData['mx'][187227] = {name = "[q5]Recuerdo de la Cartera de alma decadente", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nCartera de alma decadente Poder de talla de runas Instante\nCada objetivo afectado por Podredumbre de alma aumenta tu celeridad y probabilidad de golpe crítico un 5% durante 8 s.\nTallado rúnico en: Pies, Manos\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Brujo"}
MultiLanguageItemData['mx'][187228] = {name = "[q5]Recuerdo de la Explosión perpetua contenida", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nExplosión perpetua contenida Poder de talla de runas Instante\nEl daño con el tiempo de Catástrofe inminente aumenta un 125%, más un 15% por cada objetivo enemigo alcanzado en el camino hasta el objetivo final, hasta un máximo de un 275%.\nTallado rúnico en: Cabeza, Cuello, Hombro\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Brujo"}
MultiLanguageItemData['mx'][187229] = {name = "[q5]Recuerdo del Pacto de los acechadores de almas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nPacto de los acechadores de almas Poder de talla de runas Instante\nCuando tu Flecha resonante inflige daño al objetivo, tu grupo obtiene un 10% más de probabilidad de golpe crítico durante 10 s. (1s de reutilización)\nTallado rúnico en: Cintura, Manos\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Cazador"}
MultiLanguageItemData['mx'][187230] = {name = "[q5]Recuerdo de la Bolsa de municiones", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nBolsa de municiones Poder de talla de runas Instante\nUn máximo de 2 objetivos golpeados por tu Chakram de la muerte también son golpeados por Disparo explosivo.\nTallado rúnico en: Cabeza, Muñecas\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Cazador"}
MultiLanguageItemData['mx'][187231] = {name = "[q5]Recuerdo de los Fragmentos de las astas antiguas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nFragmentos de las astas antiguas Poder de talla de runas Instante\nCuando Espíritus salvajes golpea a menos de 5 objetivos, hay un 100% de probabilidad de que Espíritus salvajes inflija daño por segunda vez.\nTallado rúnico en: Cuello, Pecho\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Cazador"}
MultiLanguageItemData['mx'][187232] = {name = "[q5]Recuerdo de la Faltriquera de fragmentos filosos", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Devuelve el siguiente recuerdo al tallarrunas:\n\n\nFaltriquera de fragmentos filosos Poder de talla de runas\nLos Disparos mortales bonificados de Tiro despellejador hacen que 6 objetivos en un radio de 12 m sangren un 60% del daño infligido por Disparo mortal durante 6 s.\nTallado rúnico en: Piernas, Pies\nFuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\nRequiere: Cazador"}
