MultiLanguageItemData['mx'][187629] = {name = "[q4]Piedra cuoreluz", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a la montura Vombata cuoreluz.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereLos Iluminados\n: Exaltado\n\n\n[q]\"Los Iluminados veneran a todas las creaciones de los Primeros, pero para muchos, los vombata de Zereth Mortis son los más queridos. Estas criaturas son fieles bestias de carga y amadas compañeras.\"\nVendedor:\nVilo\nZona:\nZereth Mortis\nFacción:\nLos Iluminados - Exaltado\nCosto:\n5000"}
MultiLanguageItemData['mx'][187630] = {name = "[q4]Huelecristales curioso", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"A la mayoría de los vombata les gusta excavar túneles en la tierra, pero estos rastreadores parecen tener una habilidad única para encontrar cristales enterrados en las profundidades y son capaces de acumular grandes cantidades.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187631] = {name = "[q4]Vombata oscurecido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El esquema para sintetizar a estos vombata oscurecidos parece haber aparecido como una reacción a la invasión de los jurafauces. Los vombata que emergieron se ven diferentes: más oscuros, como los invasores, pero se comportan normalmente.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187632] = {name = "[q4]Vombata ornamentado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los Iluminados consideran que los vombata rojos son criaturas de buena fortuna. Fue un vombata rojo el que estuvo presente cuando llegaron a Zereth Mortis.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187633] = {name = "[q2]Configuración de bufónido", additional_info = "Síntesis de protoformas\nMaterial de profesión\n[q]\"Una configuración mística utilizada para sintetizar un bufónido.\""}
MultiLanguageItemData['mx'][187634] = {name = "[q2]Configuración ambystana", additional_info = "Síntesis de protoformas\nMaterial de profesión\n[q]\"Una configuración mística utilizada para sintetizar un ambystano.\""}
MultiLanguageItemData['mx'][187635] = {name = "[q2]Configuración de cérvido", additional_info = "Síntesis de protoformas\nMaterial de profesión\n[q]\"Una configuración mística utilizada para sintetizar un cérvido.\""}
MultiLanguageItemData['mx'][187636] = {name = "[q2]Configuración de aurélida", additional_info = "Síntesis de protoformas\nMaterial de profesión\n[q]\"Una configuración mística utilizada para sintetizar una aurélida.\""}
MultiLanguageItemData['mx'][187637] = {name = "[q3]Mochila de Navarro", additional_info = "Se liga al recogerlo\n[q2]Uso: ¡Toma tu mochila favorita y vete! (5 Seg Reutilización)"}
MultiLanguageItemData['mx'][187638] = {name = "[q4]Trotamuertes", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estos cérvidos salvajes solo se sienten en paz cuando corren a lo largo de las tierras de la Muerte, o cuando viajan entre ellas.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187639] = {name = "[q4]Cérvido majestuoso pálido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Al observar a estas majestuosas criaturas, no es difícil ver cómo la idea de los cérvidos se desarrolló en los venados de Azeroth y otros mundos mortales.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187640] = {name = "[q4]Riendas de Protovenado consagrado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a la montura Protovenado consagrado.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereLos Iluminados\n: Reverenciado\n\n\n[q]\"Solo aquellos considerados en la más alta estima de los Iluminados reciben el honor de las riendas para este cérvido inusual.\"\nVendedor:\nVilo\nZona:\nZereth Mortis\nFacción:\nLos Iluminados - Venerado\nCosto:\n5000"}
MultiLanguageItemData['mx'][187641] = {name = "[q4]Riendas del zancudo de Zereth hendido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cualquiera haya sido el propósito de estos cérvidos, ya ha sido olvidado. Aunque no han caído presa de la dominación, han sido corrompidos por la presencia inesperada de jurafauces en el reino sagrado de Zereth Mortis.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187642] = {name = "[q4]Acechaguerras feroz", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar a un acechaguerras feroz.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta: \n[q]\"¡Pisotea a la Alianza mientras montas un majestuoso lobo de protoforma! ¡Por la Horda!\"\nJcJ:\nShadowlands: Temporada 4\nRecompensa de temporada en arena y campos de batalla puntuados"}
MultiLanguageItemData['mx'][187644] = {name = "[q4]Acechaguerras feroz", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar a un acechaguerras feroz.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta: \n[q]\"¡Pisotea a la Horda mientras montas un majestuoso lobo de protoforma! ¡Por la Alianza!\"\nJcJ:\nShadowlands: Temporada 4\nRecompensa de temporada en arena y campos de batalla puntuados"}
MultiLanguageItemData['mx'][187648] = {name = "Caldera vacía de sopa de piedra", additional_info = "[q2]Uso: Prepara una caldera de sopa de piedra que estará lista para agregarle ingredientes deliciosos. ¡Complétala para alimentar hasta 35 personas de tu grupo o banda!\n\n Una vez completa, restaura 173077 p. de salud y 138461 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 53 p. de una estadística durante 1 h.\nPrecio de venta:"}
MultiLanguageItemData['mx'][187650] = {name = "[q2]Bastón de energías dracónicas", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{5 - 7 p. de daño} {Velocidad 3.60}\n(1.7 p. de daño por segundo)\n+20 intelecto\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 6 p.\nClases: [Evoker]\nPrecio de venta:"}
