MultiLanguageItemData['mx'][187655] = {name = "[q2]Cubrepiernas de evocador", additional_info = "Se liga al recogerlo\n{Piernas} {Malla}\n10 armadura\n+5 [Agilidad o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]+ 4 Versatilidad\nClases: [Evoker]\nPrecio de venta:"}
