MultiLanguageItemData['mx'][187659] = {name = "[q2]Baúl del aventurero", additional_info = "Se liga al recogerlo\n[q]\"Contiene equipamiento para otras especializaciones de clase.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageItemData['mx'][187660] = {name = "[q4]Aleteadora avespoide", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Una aleteadora es una obrera avespoide sobredesarrollada y creada para llevar a un jinete. En lugar de buscar liderazgo en una reina, espera que el jinete sea su guía para todo.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187662] = {name = "Pegote extraño", additional_info = "Único\n[q]\"Esta sustancia parece atraer a las aurélidas de Zereth Mortis, pero no puede colocarse en ningún cebo. Alguien que conozca mejor a las criaturas de las profundidades podría saber qué hacer con esto.\""}
MultiLanguageItemData['mx'][187663] = {name = "[q4]Avespoide alabronce", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Las avespoides alabronce son el resultado del intento de sintetizar una reina avespoide sin que haya otros miembros de una colmena nueva. Aunque ningún mortal ha descubierto aún cómo sintetizar una colmena, las alabronce son de las monturas más confiables que encontrarás.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187664] = {name = "[q4]Rencoria forjada", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"No hay nada que te haga sentir más vivo que recorrer el reino de la Muerte sobre una criatura que te odia.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187665] = {name = "[q4]Zumbido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"¡Bzz bzz bzz, bzz bzz! Bzz bzz bzz bzz bzz. Bzz bzz bzz, bzz bzz bzz.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187666] = {name = "[q4]Cazador aladesértica", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"En servicio al gran Propósito, los cazadores aladesértica fueron diseñados para cubrir los cielos lejanos de los reinos perdidos de las Tierras de las Sombras.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187667] = {name = "[q4]Raptora fauceliente", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Desde la incursión del Carcelero, Zereth Mortis ha dado origen a raptora nuevos, capaces de resistir la influencia corruptora de las Fauces.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187668] = {name = "[q4]Zambullidor raptora", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El raptora zambullidor es una de las versiones más feroces de su clase, perfectamente adaptada para su nicho ecológico. Dado que no han necesitado otras modificaciones, los que se sintetizan hoy son idénticos a los que se creaban eones atrás.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187669] = {name = "[q4]Serenata", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estos helícidos hermosos solo salen por la noche. Cuando están contentos, sus caparazones emiten una melodía alegre.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187670] = {name = "[q4]Helícido de bronce", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Algunos helícidos de Zereth Mortis tienen caparazones metálicos extraños. Suelen ser de color broncíneo, idéntico al metal que cualquier minero principiante podría encontrar, excepto que la construcción de esta criatura excede notablemente la habilidad de cualquier principiante.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187671] = {name = "[q4]Prototipo de fugazópodo fallido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta criatura no fue diseñada por los Primeros, sino por una entidad desconocida que trataba de crear una criatura muy veloz. No hace falta decir que el intento falló, dada la lentitud de esta montura.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187672] = {name = "[q4]Helícido escarlata", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El tinte inusualmente rojizo de este helícido estaba claramente contemplado en su diseño, pero la única otra diferencia entre estos y otros helícidos es la extraña falta de baba.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187673] = {name = "[q4]Aurélida críptica", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los códigos de los Primeros escapan a la comprensión de cualquier mortal. Un efecto curioso del lenguaje es que, por motivos desconocidos, algunas aurélidas se sienten atraídas a los mortales que quieren revelar el misterio.\"\nLogro:\nDe la A a la Zereth\nCategoría:\nShadowlands"}
MultiLanguageItemData['mx'][187674] = {name = "[q4]Acechaabismos", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a un acechaabismos.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estas medusas fueron cazadas furtivamente en Zereth Mortis, y unas pocas se perdieron cuando el barco de los cazadores se hundió. Encontraron un nuevo hogar en las profundidades del Mare Magnum.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][187675] = {name = "[q4]Aurélida brillante", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Si bien fue creada para defender el Sepulcro de los Primeros, ahora que su función principal está terminada, obedece tus órdenes sumisamente.\"\nLogro:\nGloria del asaltante del Sepulcro\nCategoría:\nCalabozos y bandas"}
MultiLanguageItemData['mx'][187676] = {name = "[q4]Pólipo astrohondo", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a una aurélida astrohonda.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Como uno de los últimos pólipos de una criatura esquiva, esta aurélida se siente a gusto tanto en el agua como en el aire.\"\nBotín:\nHirukon\nZona:\nZereth Mortis"}
MultiLanguageItemData['mx'][187677] = {name = "[q4]Reptador genesíaco", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los Iluminados que han observado a los tarácnidos creen que esta variedad podría ser una de las primeras criaturas que pisó Zereth Mortis.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187678] = {name = "[q4]Trepador tarácnido", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estos tarácnidos habitan en los rincones más oscuros de Zereth Mortis y solo salen para cazar (o, a veces, llevar a un jinete de paseo).\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187679] = {name = "[q4]Arácnido inefable", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estos tarácnidos se rigen por un propósito desconocido para todos y responden únicamente a un llamado superior. Sea lo que sea, parece que incluye brindar ayuda de rutina a los mortales que necesitan viajar. Por ahora.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageItemData['mx'][187680] = {name = "[q4]Croador de guerra feroz", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar a un croador de guerra feroz.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta: \n[q]\"Estas criaturas muestran tanto entusiasmo por ir a la batalla que suelen croar algo que suena muy parecido a \"¡POR LA HORDA!\".\"\nJcJ:\nShadowlands: Temporada 3\nRecompensa de temporada en arena y campos de batalla puntuados"}
MultiLanguageItemData['mx'][187681] = {name = "[q4]Croador de guerra feroz", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar a un croador de guerra feroz.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta: \n[q]\"Estas criaturas muestran tanto entusiasmo por ir a la batalla que suelen croar algo que suena muy parecido a \"¡POR LA ALIANZA!\".\"\nJcJ:\nShadowlands: Temporada 3\nRecompensa de temporada en arena y campos de batalla puntuados"}
MultiLanguageItemData['mx'][187682] = {name = "[q4]Caminamuerte necrodistorsionado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Una energía pura y turbulenta unida en una forma cohesiva. Solo se someterá a la voluntad de aquellos que tengan la fuerza suficiente para dominarla.\"\nLogro:\nMaestro de piedra angular de Shadowlands: Tercera temporada\nCategoría:\nCalabozos"}
MultiLanguageItemData['mx'][187683] = {name = "[q4]Bufónido placaáurea", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Este bufónido acorazado siempre está listo para saltar a la batalla... Siempre y cuando esa batalla esté muy, muy cerca. En un instante, puede saltar varias veces y eventualmente llegar a la pelea.\"\nProfesión:\nSíntesis de protoformas"}
