MultiLanguageItemData['mx'][191668] = {name = "Ballena de piedra grabada", additional_info = "Objeto de misión\n[q]\"La aleta dorsal de una ballena sumergiéndose. Este tallado simboliza la renovación. Los bordes tienen las marcas de unos incisivos grandes y filosos.\""}
MultiLanguageItemData['mx'][191669] = {name = "Colmillo grabado", additional_info = "Objeto de misión\n[q]\"Un colmillo de mamut decorado con delicadeza en honor a quien provee. Cubierto de baba coagulada aún húmeda.\""}
MultiLanguageItemData['mx'][191670] = {name = "Sortija de plumas con cuentas", additional_info = "Objeto de misión\n[q]\"Plumas de águila entrelazadas en un hilo de cuero con cuentas, símbolo de la sensatez. Se pueden ver marcas de dientes en el cuero, y varias de las cuentas están rotas.\""}
MultiLanguageItemData['mx'][191671] = {name = "Efigie colmillarr fragmentada", additional_info = "Objeto de misión\n[q]\"Una efigie de huesos desgastada que representa a un venerado ancestro colmillarr. El medio está muy mordisqueado.\""}
MultiLanguageItemData['mx'][191672] = {name = "Marca del proveedor", additional_info = "Objeto de misión\n[q]\"Un tótem tallado en hueso con gran habilidad que representa a un jefe pescador colmillarr exitoso. Las marcas de dientes profundas han rajado el hueso.\""}
