MultiLanguageItemData['mx'][192495] = {name = "[q3]Hombre sigiloso 54 descompuesto", additional_info = "Se liga al usarlo\nJuguete\n[q2]Uso: Cubre al usuario con un campo de sigilo que le permite infiltrarse inadvertido. Al menos para eso servía antes. (5 Min Reutilización)\n[q]\"¡La invisibilidad es para perdedores!\""}
MultiLanguageItemData['mx'][192496] = {name = "Lanza de cazador exhumado", additional_info = "Objeto de misión\n[q]\"Esta lanza aún emana energía necrótica. Alguna vez perteneció a un poderoso cazador shikaar.\""}
MultiLanguageItemData['mx'][192523] = {name = "[q3]Protodraco renovado: Escamas verdes", additional_info = "Manuscrito de los vigías dracónicos\nSe liga al recogerlo\nÚnico\n[q2]Uso: Desbloquea esta opción de personalización para el Protodraco renovado en el estrado de transformación.\n[q]\"Un pergamino en el que se describe un poderoso protodraco con escamas de un verde vivo.\""}
MultiLanguageItemData['mx'][192524] = {name = "Orbe de vendavales primigenios", additional_info = "Objeto de misión\nÚnico\nRequiere nivel 10 - 70 ( 70)\n[q]\"Un orbe de aire helado que emite un tamborileo que denota su poder.\""}
MultiLanguageItemData['mx'][192545] = {name = "Fragmento de llama primigenia", additional_info = "Se liga al recogerlo\nÚnico (8)\n[q2]Uso: Combina 8 fragmentos de llama primigenia en el orbe de llamas primigenias.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Fragmentos cálidos de un orbe de fuego elemental.\""}
MultiLanguageItemData['mx'][192546] = {name = "Orbe de llamas primigenias", additional_info = "Objeto de misión\nÚnico\nRequiere nivel 10 - 70 ( 70)\n[q]\"Un orbe de calidez condensada que emite un tamborileo que denota su poder.\""}
