MultiLanguageItemData['mx'][192743] = {name = "Arbustina silvestre", additional_info = "Objeto de misión\n[q2]Uso: Alimenta a un pisabarro hambriento con una arbustina silvestre en un radio de 20 m. (3 Seg Reutilización)\n[q]\"Una explosión de menta fría con la crocancia perfecta.\""}
MultiLanguageItemData['mx'][192744] = {name = "Regalo de Gélik", additional_info = "Objeto de misión\n[q]\"Unas gemas frías, pero muy dinámicas.\""}
MultiLanguageItemData['mx'][192745] = {name = "La comedia titánica", additional_info = "Objeto de misión\n[q]\"Un recorrido satírico por el cosmos, desde el Sueño Esmeralda hasta las Tierras de las Sombras, dirigido por el vigía de los titanes Dantyr. Ni los titanes ni los Aspectos pudieron salvarse de la ira del autor, que dejó todos sus pecados al descubierto.\""}
