MultiLanguageItemData['mx'][192750] = {name = "Jabalina de hierro negro", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Lánzasela a un verasangre primigenio para bajarlo del cielo. (5 Seg Reutilización)"}
MultiLanguageItemData['mx'][192751] = {name = "[q4]Brúfalo tocado por la tormenta", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n[q]\"Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\""}
MultiLanguageItemData['mx'][192752] = {name = "Voluta de bastón", additional_info = "Objeto de misión\n[q]\"El enfoque desprendido de un bastón de caminante de tiempo roto.\""}
MultiLanguageItemData['mx'][192753] = {name = "Las escamas de la ira", additional_info = "Objeto de misión\n[q]\"Una respuesta brutalmente conmovedora a la orden impuesta por los Aspectos y sus aliados titánicos. Contada desde el punto de vista de un protodraco forzado a rebelarse tras ser marginado en la sociedad dracónica.\""}
MultiLanguageItemData['mx'][192754] = {name = "Dracuijote", additional_info = "Objeto de misión\n[q]\"La historia de un antiguo dragón verde que ya no podía distinguir la diferencia entre sus sueños y el mundo terrenal. Acompañado por un dragauro atribulado, Dracuijote se embarca en una misión fantasiosa para restaurar una era dorada imaginaria.\""}
MultiLanguageItemData['mx'][192755] = {name = "El señor de los colmillos", additional_info = "Objeto de misión\n[q]\"Un grupo de dracónidos veteranos y crías intrépidas forman una alianza para destruir un artefacto que contiene un poder temible y que solo puede extinguirse en las forjas del Aspecto demente que lo creó.\""}
MultiLanguageItemData['mx'][192756] = {name = "Rojo y negro: los vuelos", additional_info = "Objeto de misión\n[q]\"Un draco negro de clase baja no consigue conciliar su legado militar con su respeto por la inteligencia y el ingenio, y finalmente sucumbe a la desesperación por un amor no correspondido y el materialismo desenfrenado de los dragones.\""}
MultiLanguageItemData['mx'][192757] = {name = "Orgullo y protodracos", additional_info = "Objeto de misión\n[q]\"La historia de amor por excelencia. Emplazada en tiempos anteriores a los Aspectos, una joven protodraca prometedora tiene un encuentro desafortunado con un draco displicente. Su animosidad se transforma lentamente en aprecio y, con el tiempo, crece hasta convertirse en amor.\""}
MultiLanguageItemData['mx'][192758] = {name = "Rollo de cuerda pesada", additional_info = "Objeto de misión\n[q]\"\"Pesada\" según los dragonantes. Podrían arrojarse incluso piedras enormes con una sola soga.\""}
MultiLanguageItemData['mx'][192759] = {name = "Lanza juramagma", additional_info = "Objeto de misión\n[q]\"Apunta hacia un enemigo y realiza un movimiento con fuerza de atrás hacia adelante.\""}
MultiLanguageItemData['mx'][192761] = {name = "[q4]Libélula escurridiza domada", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 25 con la Expedición Dragontina.\n\n\n[q]\"Al abuelo Bigotes no le llevó mucho tiempo domesticar las libélulas escurridizas del Campamento Dragontino para que ayudaran a movilizar al personal y el cargamento de la Expedición.\"\nFacción:\nExpedición Dragontina\nReconocimiento:\n25\nVendedor:\nAbuelo Bigotes\nUbicación:\nCampamento Dragontino"}
MultiLanguageItemData['mx'][192762] = {name = "[q4]Libélula escurridiza azur", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 25 con la Expedición Dragontina.\n\n\n[q]\"Cuando el abuelo Bigotes finalmente les enseñó a llevar jinetes, las libélulas escurridizas azur demostraron ser capaces de formar un poderoso lazo de lealtad con ellos.\"\nFacción:\nExpedición Dragontina\nReconocimiento:\n25\nVendedor:\nAbuelo Bigotes\nUbicación:\nCampamento Dragontino\nCosto:\n5\n20\n750"}
MultiLanguageItemData['mx'][192764] = {name = "[q4]Libélula escurridiza glauca", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Las libélulas escurridizas glaucas son la montura perfecta para los exploradores de la Expedición Dragontina, porque son veloces y se mimetizan con el follaje de las Islas Dragón.\"\nFacción:\nExpedición Dragontina\nReconocimiento:\n25\nTesoro:\nMochila de explorador de expedición"}
MultiLanguageItemData['mx'][192765] = {name = "[q4]Arenero concedido", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un regalo del abuelo Bigotes. Estas caprichosas libélulas escurridizas ayudan a los Caminantes del Tiempo a arreglar las presentes (y futuras) calamidades temporales vinculadas con la arena.\"\nLogro:\nHora de cierre\nCategoría:\nExploración"}
MultiLanguageItemData['mx'][192766] = {name = "[q4]Libélula escurridiza ámbar", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un regalo del abuelo Bigotes para el puesto de venta. Las libélulas escurridizas ámbar son sorprendentemente dóciles.\"\nPuesto de venta"}
