MultiLanguageItemData['mx'][192768] = {name = "Disco titánico", additional_info = "Objeto de misión\n[q]\"El disco titánico tiene símbolos intrincados grabados y emite un brillo tenue.\""}
MultiLanguageItemData['mx'][192769] = {name = "[q0]Lanza quebrada", additional_info = "[q]\"Esta arma ya no sirve para el combate.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][192772] = {name = "[q4]Salamantra antigua", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Debido a su preferencia por las cuevas oscuras y aguas turbias, los avistamientos de esta variante única de salamantra son tan inusuales que muchos investigadores creían que se habían extinguido.\"\nBotín:\nEl Confín Prohibido"}
MultiLanguageItemData['mx'][192774] = {name = "[q4]Salamantra escamacoralina", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Después de que la tormenta de Raszageth amainara, esta raza acuática de salamantras, entre muchas maravillas más, se asentó en las costas.\"\nLogro:\nHacia la tormenta\nCategoría:\nExploración"}
MultiLanguageItemData['mx'][192775] = {name = "[q4]Salamantra tormentera", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"A veces, cuando las energías de tormenta infunden a alguna criatura, simplemente... se vuelve más grande y apacible. Pocas salamantras están dispuestas a dejar que las monten, pero estas hijas de la tormenta son una excepción notable.\"\nVendedora:\nMythressa\nCosto:\n2000"}
MultiLanguageItemData['mx'][192776] = {name = "Bellota de brasas inerte", additional_info = "Objeto de misión\n[q]\"Una semilla caliente al tacto que contiene suficiente energía para crecer hasta alcanzar alturas que dan vértigo.\""}
MultiLanguageItemData['mx'][192777] = {name = "[q4]Caparamagma", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"¿Quién es un buen caracolito recién forjado, hecho completamente de lava elemental? ¡Tú! ¡Claro que sí!\"\nObjeto:\nCaparazón de magma vacío\nZona:\nCostas del Despertar"}
MultiLanguageItemData['mx'][192779] = {name = "[q4]Babosa hirviente", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Arrastrada desde su abismo por la furia de los zaqalis.\"\nTesoro:\nAlijo hirviente\nZona:\nCaverna Zaralek"}
MultiLanguageItemData['mx'][192783] = {name = "Órdenes de la vanguardia nokhud", additional_info = "Objeto de misión\n[q]\"Robadas del cuerpo de un asesino nokhud.\"\n[q2]<Click derecho para leer>"}
MultiLanguageItemData['mx'][192784] = {name = "[q4]Caparazonte", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Alimentado con victoria y endurecido por la gloria, este caracol no es más que un justo tributo para su amo.\"\nLogro:\nGloria del héroe de Dragonflight"}
MultiLanguageItemData['mx'][192785] = {name = "[q4]Caracolental pegajoso", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Conformado por los restos de energías elementales de las tormentas primigenias, este molusco mágico es más rápido de lo que parece.\"\nBotín:\nEl Confín Prohibido"}
MultiLanguageItemData['mx'][192786] = {name = "[q4]Caparazón de caracol de mundo durmiente", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Para los rompemundos, un taburete portátil. Para ti, una montura fuerte.\"\nVendedora:\nVendedora Vexil\nZona:\nLas Costas del Despertar\nCosto:\n1000"}
MultiLanguageItemData['mx'][192788] = {name = "[q4]Mamut de tiro concedido", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un regalo de la exploradora Tomul para que, en los festines de Iskaara, nunca falte pescado para alimentar a los más necesitados.\"\nLogro:\nBallenas, bacalaos y besugos\nCategoría:\nExploración"}
MultiLanguageItemData['mx'][192790] = {name = "[q4]Mamut musgoso", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Conservado durante miles de años en piedra, la magia de bronce prácticamente ha convertido a este mamut en fósil otra vez.\"\nBotín:\nBóvedas de Zskera"}
MultiLanguageItemData['mx'][192791] = {name = "[q4]Portador llanero", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los mamuts de las Llanuras de Ohn'ahra no están acostumbrados a llevar personas, porque sus vecinos centauros no necesitan monturas. Pero pueden aprender a llevar jinetes. Algunos incluso se muestran muy entusiastas.\"\nEvento de mundo:\nCacería de los centauros (primera cacería de cada semana)"}
MultiLanguageItemData['mx'][192792] = {name = "[q4]Líder de manada truenoespín concedido", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un regalo de Merithra, que bendijo a estos truenoespines para que, sin importar dónde moraran los clanes Maruuk, siempre estuvieran bajo el cuidado del Vuelo Verde.\"\nLogro:\nUn centauro en el foco\nCategoría:\nExploración"}
MultiLanguageItemData['mx'][192793] = {name = "[q4]PH Thunder Lizard Black", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete"}
MultiLanguageItemData['mx'][192794] = {name = "[q4]PH Thunder Lizard Blue", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete"}
MultiLanguageItemData['mx'][192795] = {name = "Jarabe rejuvenecedor", additional_info = "Objeto de misión\n[q2]Uso: Vigoriza a un soldado gelikyr en la terraza inferior del Mirador Gelikyr.\n[q]\"Este vial contiene un líquido prismático viscoso.\""}
MultiLanguageItemData['mx'][192796] = {name = "[q4]Bestia de carga petrapiel de expedicionario", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Un explorador de verdad nunca se queda mucho tiempo en el mismo sitio. Para viajar es esencial contar con una bestia de carga fiable que tenga espalda fuerte y piernas robustas.\"\nVendedora:\nProveedora Aristta\nZona:\nThaldraszus\nCosto:\n20000"}
MultiLanguageItemData['mx'][192797] = {name = "[q2]Diente desechado de Gral", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+244 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Tus hechizos y habilidades que infligen daño tienen una alta probabilidad de invocar un espíritu de tiburón que inflige 4230 p. de daño de escarcha dividido entre tu objetivo y los enemigos cercanos.\n\n El daño aumenta por cada enemigo golpeado, hasta 5 enemigos.\nPrecio de venta:"}
MultiLanguageItemData['mx'][192799] = {name = "[q4]Riendas de Trueni", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a Trueni, trampera truenoespín. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Nada impedirá que Trueni cumpla con su misión de comer todas las frutas del mundo.\"\nMisión:\nCómo domar a tu truenoespín\nZona:\nLlanuras de Ohn'ahra"}
MultiLanguageItemData['mx'][192800] = {name = "[q4]Zancacuernos dermacielo", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"La inestabilidad de las tormentas primalistas en las diversas líneas temporales a veces provoca que las criaturas absorban la energía de las propias tormentas. Por lo general, estas criaturas se comportan de manera dócil con cualquiera que logre enfrentarse a la furia de estas anomalías cronomáticas.\"\nVendedora:\nBrendormi\nCosto:\n150\n3000"}
