MultiLanguageItemData['mx'][194022] = {name = "[q2]Papiro ornamentado: mitad superior", additional_info = "Se liga al equiparlo\nÚnico\n[q2]Uso: Combina las dos mitades de los pergaminos para formar un mapa.\n[q]\"En la parte superior del papiro se ve una gran extensión de agua, y varias representaciones de volcanes y ríos serpenteantes en toda la zona.\""}
MultiLanguageItemData['mx'][194023] = {name = "[q3]Mapa del tesoro: Las Costas del Despertar", additional_info = "Se liga al recogerlo\n[q2]Uso: Marca el mapa con las ubicaciones de varios tesoros en las Costas del Despertar.\n[q]\"La mancha oscura de la esquina inferior izquierda del mapa parece permanente. Es muy probable que lo que se encuentra en esta área no deba ser encontrado.\""}
MultiLanguageItemData['mx'][194024] = {name = "[q2]Papiro con vínculo rúnico: mitad superior", additional_info = "Se liga al equiparlo\nÚnico\n[q2]Uso: Combina las dos mitades de los pergaminos para formar un mapa.\n[q]\"A lo largo del papiro pueden verse varios ríos serpenteantes marcados con unos enormes símbolos similares a una cabeza.\""}
MultiLanguageItemData['mx'][194025] = {name = "[q2]Papiro con vínculo rúnico: mitad inferior", additional_info = "Se liga al equiparlo\nÚnico\n[q2]Uso: Combina las dos mitades de los pergaminos para formar un mapa.\n[q]\"El texto de la parte inferior del mapa está muy borroso y no puede leerse. Una enorme espiral que emana energía aparece en la esquina inferior izquierda del papiro.\""}
MultiLanguageItemData['mx'][194026] = {name = "[q3]Mapa del tesoro: El Trecho Azur", additional_info = "Se liga al recogerlo\n[q2]Uso: Marca el mapa con las ubicaciones de varios tesoros en el Trecho Azur.\n[q]\"El mapa está cubierto de ríos serpenteantes. Varios símbolos similares a una cabeza aparecen en distintas ubicaciones. Una enorme espiral que emana energía yace sola en el suroeste.\""}
