MultiLanguageItemData['mx'][194512] = {name = "Dispositivo arcano roto", additional_info = "Objeto de misión\n[q]\"Algo de magia arcana aún resplandece en este fragmento de dispositivo.\""}
MultiLanguageItemData['mx'][194513] = {name = "Colección de tomos", additional_info = "Objeto de misión\n[q]\"Estos tomos describen la historia de cómo era el Campamento Antonidas hace 10000 años.\""}
MultiLanguageItemData['mx'][194514] = {name = "Lista de invitados anticuada", additional_info = "Objeto de misión\n[q]\"Este viejo tomo contiene los nombres de los dragones que frecuentaban esta área. Dos nombres aparecen en casi todas las páginas: Malygos y Sindragosa.\""}
MultiLanguageItemData['mx'][194515] = {name = "Planificador de eventos decadente", additional_info = "Objeto de misión\n[q]\"Este libro detalla los distintos eventos que se organizaban en esta área. Todos parecen involucrar demostraciones arcanas para los otros vuelos y Aspectos.\""}
MultiLanguageItemData['mx'][194516] = {name = "Diario añejo", additional_info = "Objeto de misión\n[q]\"Estas páginas incluyen detalles sobre el cortejo entre dos dragones azules, Malygos y Sindragosa. Una de las notas indica que esto es \"parte de una serie\".\""}
MultiLanguageItemData['mx'][194517] = {name = "Textos fragmentados", additional_info = "Objeto de misión\n[q]\"Este libro describe a los dracónidos y dragauros que cuidaron de esta área cuando los dragones azules se marcharon. Muchas páginas lamentan la pérdida del \"júbilo\" por la ausencia de Sindragosa y Malygos.\""}
MultiLanguageItemData['mx'][194519] = {name = "Ayuda de Osoria", additional_info = "Objeto de misión\n[q2]Uso: Invoca a Osoria para que te lleve en el aire y ataque a los enemigos. Solo dentro de la Ciudadela Obsidiana. (5 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][194520] = {name = "Pergamino de conocimiento de caminante del tiempo", additional_info = "Objeto de misión\n[q]\"Este papiro contiene una gran cantidad de conocimiento sobre la magia del tiempo. Sientes que tu mente se retuerce si miras el papiro durante demasiado tiempo.\""}
MultiLanguageItemData['mx'][194521] = {name = "[q4]Draco salvaje de risco", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Sus nidos suelen estar construidos en las laderas más pronunciadas de los riscos de Thaldraszus, para refugiarse en los cielos rápidamente cuando hay peligro.\"\nLogro:\nIslas Dragón: Draco salvaje de risco"}
