MultiLanguageItemData['mx'][198073] = {name = "Karha, el Viento sereno", additional_info = "Objeto de misión\nÚnico\n[q]\"Karha era el bastón de Ganmat, el Sabio, un sabio de los vientos de Ohn'ara que curó a incontables aliados y derrotó aún más enemigos hace siglos.\""}
MultiLanguageItemData['mx'][198074] = {name = "Josanak, la Victoria certera", additional_info = "Objeto de misión\nÚnico\n[q]\"Josanak perteneció al guerrero invicto Zafil. Zafil siempre confió en su alabarda, y el clan siempre confió en él.\""}
MultiLanguageItemData['mx'][198075] = {name = "Tsegzaya, el Arco de zarzas", additional_info = "Objeto de misión\nÚnico\n[q]\"Una infinidad de flechas de Tsegzaya dieron en el blanco contra presas silvestres y los enemigos del Clan Teerai cuando Dihar tensaba el arco.\""}
