MultiLanguageItemData['mx'][198086] = {name = "[q4]Baraja de la Luna Negra: Inferno", additional_info = "Se liga al equiparlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+300 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Arroja un Infierno llameante al objetivo que inflige ( 78083 * .3)- 78083 p. de daño de fuego. El daño infligido depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198087] = {name = "[q4]Baraja de la Luna Negra: Helada", additional_info = "Se liga al equiparlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+300 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Inflige 15897 p. de daño de escarcha y aplica Helada del despertar a tu objetivo durante 4 a 12 s. Si el objetivo muere mientras Helada del despertar está activa, explota e inflige 39743 p. de daño de escarcha divididos entre los enemigos en un radio de 10 m. La duración depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198088] = {name = "[q4]Baraja de la Luna Negra: Baile", additional_info = "Se liga al equiparlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+300 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Invoca una Danza refrescante que rebota de 6 a 13 veces entre aliados y enemigos en un radio de 25 m, lo que inflige 9545 p. de daño de naturaleza o 5200 p. de sanación. La cantidad de veces que rebota depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198089] = {name = "[q4]Baraja de la Luna Negra: Vigía", additional_info = "Se liga al equiparlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+300 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Otorga la Bendición de vigía durante 5 a 12 s y un escudo de absorción por 62801 p. de daño.\n Si el escudo se agota mientras Bendición de vigía está activa, otorga 1469 p. de versatilidad durante el mismo tiempo. La duración depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
