MultiLanguageItemData['mx'][198441] = {name = "Frituras de truenoespín", additional_info = "[q2]Uso: Restaura ( 45000 / 5 * 20) p. de salud y ( 60000 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes.\n[q]\"La electricidad residual te da cosquillas en la lengua.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198442] = {name = "Encogedor de Pananotl", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q2]Uso: Encoge al taumaturgo y a los miembros del grupo en un radio de 40 m durante 10 min. (3 Seg Reutilización)\n[q]\"En la etiqueta con tachaduras se leen las siguientes palabras: \"Solo los mejores ingredientes provenientes de, eh... Confía en mí. ¡Es delicioso!\".\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198443] = {name = "Reliquia del Templo de los Titanes", additional_info = "Objeto de misión\n[q]\"Una reliquia peculiar del Templo de los Titanes.\""}
MultiLanguageItemData['mx'][198445] = {name = "Pimientos zandali asados", additional_info = "Objeto de misión\n[q]\"Dulces y con un sabor ahumado exquisito, pero ten cuidado con las semillas.\""}
MultiLanguageItemData['mx'][198446] = {name = "Cosecha de Suramar fina", additional_info = "Objeto de misión\n[q]\"Fruta seleccionada por expertos para satisfacer tu refinado paladar dracthyr.\""}
MultiLanguageItemData['mx'][198447] = {name = "Cangrejo de imitación importado por Pantoque", additional_info = "Objeto de misión\n[q]\"¡Los más salados o nada!\""}
MultiLanguageItemData['mx'][198448] = {name = "Suministros de Expedición Dragontina", additional_info = "Objeto de misión\n[q]\"Varios suministros que pertenecen a la Expedición Dragontina.\""}
MultiLanguageItemData['mx'][198449] = {name = "[q7]Faltriquera de maravillas prodigiosas", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Ábrela para obtener 1250 p. de flujo cósmico.\nRequiere la reputación Amistoso con los Iluminados.\n[q]\"Los Iluminados llevan estas faltriqueras cuando recorren Zereth Mortis, creyendo que esta práctica los acerca más a los Primeros.\""}
MultiLanguageItemData['mx'][198450] = {name = "Viejo caparazón de cangrejo", additional_info = "Se liga al recogerlo\n[q]\"Desechado hace mucho tiempo, el caparazón es suave y redondeado.\""}
MultiLanguageItemData['mx'][198451] = {name = "[q2]Ampolla de llamavida", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+382 [Agilidad o Fuerza]\n[q2]Uso: Destapa la ampolla y libera las llamas de vida que contiene, lo que inflige 28339 p. de daño divididos entre todos los enemigos y sana 42051 p. de salud divididos entre todos los aliados en un radio de 10 m. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198452] = {name = "Prototipo F", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 4 h\n[q2]Uso: Equipa el prototipo F.\n\n Puede usarse en la Ciudadela Obsidiana y campos de lava adyacentes.\n[q]\"Una de las tantas armas experimentales que nunca superaron la fase de prototipo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198453] = {name = "Granada de azerita inestable", additional_info = "Se liga al recogerlo\nDuración: 4 h\n[q2]Uso: Inflige de 29 a 43 p. de daño arcano a todos los enemigos que están en un radio de 7 m del impacto.\n\n Puede usarse en la Ciudadela Obsidiana y campos de lava adyacentes. (5 Seg Reutilización)\n[q]\"En el mercado negro se venden cajones enteros de estas granadas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198454] = {name = "[q3]Tratado dracónico sobre herrería", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de herrería de las Islas Dragón.\nRequiere Herrería de las Islas Dragón (25)\n[q]\"Contiene notas sobre distintos trucos del oficio usados por herreros. Solo puede estudiarse una vez por semana.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198455] = {name = "Raíces enredadas", additional_info = "Se liga al recogerlo\n[q]\"Marrones y verdes, duras y tiernas, todas mezcladas.\""}
MultiLanguageItemData['mx'][198456] = {name = "Pececillo ojoliva", additional_info = "Se liga al recogerlo\n[q]\"Un ojoliva joven, parcialmente transparente.\""}
MultiLanguageItemData['mx'][198457] = {name = "[q3]Patrón: Guardapolvo maestro", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un guardapolvo de plumas de peletero exquisito.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Centauros Maruuk y la profesión Peletería de las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198458] = {name = "[q3]Patrón: Cobertor resplandeciente", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar una cartuchera de herramientas de maestro joyero.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Colmillarr de Iskaara.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198459] = {name = "[q3]Patrón: Mochila rebosante de flores", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un paquete de botánica de herborista generoso.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Colmillarr de Iskaara.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198461] = {name = "[q3]Patrón: Guantes a prueba de descargas", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar unas manoplas a prueba de pinchazos de ingeniero magnífico.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Colmillarr de Iskaara.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198462] = {name = "[q3]Patrón: Delantal a prueba de quemaduras", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un delantal no inflamable de maestro herrero.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Centauros Maruuk y la profesión Peletería de las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198463] = {name = "[q3]Patrón: Sombrero de experto alquimista", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar una celada hidrófoba de alquimista espectacular.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Centauros Maruuk y la profesión Peletería de las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198464] = {name = "[q3]Patrón: Mochila reforzada", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un expositor de curtido de desollador excepcional.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Centauros Maruuk y la profesión Peletería de las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198465] = {name = "[q3]Patrón: Gorro de experto desollador", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un gorro de trampas de desollador resplandeciente.\nRequiere Peletería de las Islas Dragón (50)\nRequiere reconocimiento 18 con los Colmillarr de Iskaara.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198474] = {name = "[q3]Caballete de artista", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Inspírate. (30 Seg Reutilización)\n[q]\"No cualquiera puede convertirse en un gran artista, pero un gran artista puede venir de cualquier lugar.\""}
MultiLanguageItemData['mx'][198475] = {name = "[q3]Banda rota", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\n[q]\"Una parte de una banda dorada que se salió de una estatua mucho más grande.\""}
MultiLanguageItemData['mx'][198476] = {name = "Pintura de presentación", additional_info = "Objeto de misión\n[q]\"Una serie de pinceladas competentes retrata los Archivos Azur, cubiertos de nieve, a la distancia. Una obra melancólica.\""}
MultiLanguageItemData['mx'][198477] = {name = "[q4]Portabaraja de la Luna Negra: Helada", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+244 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Inflige 10372 p. de daño de escarcha y aplica Helada del despertar a tu objetivo durante 4 a 12 s. Si el objetivo muere mientras Helada del despertar está activa, explota e inflige 25929 p. de daño de escarcha divididos entre los enemigos en un radio de 10 m. La duración depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198478] = {name = "[q4]Portabaraja de la Luna Negra: Baile", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+244 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Invoca una Danza refrescante que rebota de 6 a 13 veces entre aliados y enemigos en un radio de 25 m, lo que inflige 6228 p. de daño de naturaleza o 4133 p. de sanación. La cantidad de veces que rebota depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198479] = {name = "Jinete del vendaval", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Monta el deslizador, lo que reduce tu velocidad de caída durante 2 min. Solo se puede usar en Kul Tiras. (3 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198480] = {name = "Los Estanques Resplandecientes", additional_info = "Objeto de misión\n[q]\"Una paleta delicada de rosado, rubí y verde glauco componen este cuadro a medio hacer de los Estanques de Vida.\""}
MultiLanguageItemData['mx'][198481] = {name = "[q4]Portabaraja de la Luna Negra: Vigía", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Baraja de la Luna Negra (1)\nAbalorio\n+244 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Equipar: Mezcla la baraja periódicamente durante el combate.\n[q2]Uso: Usar: Otorga la Bendición de vigía durante 5 a 12 s y un escudo de absorción por 51162 p. de daño.\n Si el escudo se agota mientras Bendición de vigía está activa, otorga 1230 p. de versatilidad durante el mismo tiempo. La duración depende del naipe que está en la parte superior de la baraja. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198482] = {name = "La Espiral de Kurganes", additional_info = "Objeto de misión\n[q]\"Unos patrones en espiral siguen las curvas de las suaves colinas verdes, y unos vientos ondulantes soplan los árboles en esta pintura de las Llanuras de Ohn'ahra.\""}
MultiLanguageItemData['mx'][198484] = {name = "Descomposición de Frondacuero", additional_info = "Objeto de misión\n[q]\"Una espesa niebla verde se cierne sobre un bosque en descomposición en esta pintura. El lienzo mismo despide un olor repugnante.\""}
MultiLanguageItemData['mx'][198486] = {name = "Parapente ventoescama", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te subes al planeador, lo que reduce tu velocidad de caída durante 2 min. Solo se puede usar en las Islas Dragón. (3 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][198487] = {name = "Agua iridiscente", additional_info = "Material de profesión\n[q]\"Un líquido ligero y burbujeante a menudo utilizado por escribas. Se puede comprar de vendedores.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198488] = {name = "[q2]Bastón del descubrimiento", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{33 - 46 p. de daño} {Velocidad 3.60}\n(11.0 p. de daño por segundo)\n+130 intelecto\n+44 aguante\n[q2]Aumenta tu índice de golpe crítico + 28 p.\n[q2]+ 30 Versatilidad\nDurabilidad 85 / 85\nPrecio de venta:"}
MultiLanguageItemData['mx'][198489] = {name = "[q2]Prisma onírico", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+382 intelecto\n[q2]Equipar: Tus hechizos de sanación tienen una probabilidad de sumirte en un sueño lúcido, lo que otorga más regeneración de maná y aumenta tu maestría 1402 p. durante 20 s.\nPrecio de venta:"}
MultiLanguageItemData['mx'][198490] = {name = "[q2]Brújula de Matagolpe", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+382 [Agilidad o Fuerza]\n[q2]Equipar: Tus ataques otorgan una probabilidad de que la brújula te marque una dirección, lo que aumenta 2043 p. tu golpe crítico, celeridad, maestría o versatilidad durante 12 s.\n[q]\"Los expedicionarios veteranos saben que una brújula es la mejor forma de salir de (y meterse en) problemas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198510] = {name = "[q3]Tratado dracónico sobre ingeniería", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de ingeniería de las Islas Dragón.\nRequiere Ingeniería de las Islas Dragón (25)\n[q]\"Contiene notas sobre distintos trucos del oficio usados por ingenieros. Solo puede estudiarse una vez por semana.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][198511] = {name = "Materiales de construcción", additional_info = "Objeto de misión\n[q]\"Los restos de un elemental de tierra. Llamarlos materiales de construcción es muy generoso.\""}
MultiLanguageItemData['mx'][198512] = {name = "Las grandes salas", additional_info = "Objeto de misión\n[q]\"Unos pilares altos y luces brillantes decoran esta pintura sin terminar, que es prácticamente un bosquejo de las Salas de Infusión.\""}
MultiLanguageItemData['mx'][198513] = {name = "La Academia", additional_info = "Objeto de misión\n[q]\"En esta pintura de la Academia Algeth'ar, unos estandartes coloridos de los vuelos cuelgan de una pared gigantesca, debajo de los cuales unos dracónidos juegan.\""}
MultiLanguageItemData['mx'][198514] = {name = "La bóveda sellada", additional_info = "Objeto de misión\n[q]\"Las manchas púrpuras y azules representan los brotes de magia arcana en esta pintura de la Bóveda Azur.\""}
MultiLanguageItemData['mx'][198515] = {name = "Los laboratorios de fuego", additional_info = "Objeto de misión\n[q]\"Esta pintura de Neltharus es poco más que una manchas poco definidas de color rojo, naranja y negro.\""}
MultiLanguageItemData['mx'][198516] = {name = "Última ilustración de Hudson", additional_info = "Objeto de misión\n[q]\"Un boceto inconcluso de Hudson y Ranpiata. Sus cabezas están cerca, sonriendo.\""}
MultiLanguageItemData['mx'][198517] = {name = "Piel de Konkhular", additional_info = "Objeto de misión\n[q]\"El color de esta piel se mezcla bien con las rocas y la tierra del área.\""}
