MultiLanguageItemData['mx'][198530] = {name = "Pimientos zandali crudos", additional_info = "Objeto de misión\n[q2]Uso: Los arroja al fuego en el Campamento Dragontino para preparar pimientos zandali asados. (3 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"Duros y de sabor demasiado intenso. No han sido cocinados.\""}
MultiLanguageItemData['mx'][198532] = {name = "[q2]Compás del cartógrafo", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+382 intelecto\n[q2]Equipar: Tus hechizos tienen una probabilidad de infligir 7802 p. de daño o realizar 11717 p. de sanación al objetivo con menos salud en un radio de 10 m según el hechizo que hayas lanzado.\n[q]\"Hay una cosa que distingue a un cartógrafo maestro de los demás: la precisión.\"\nPrecio de venta:"}
