MultiLanguageItemData['mx'][198537] = {name = "[q3]Trompeta de Taivan", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: Invoca a Taivan a tu lado. Taivan aumenta 1 p. la versatilidad de quienes lo rodean. (5 Min Reutilización)\n[q]\"A Taivan le encanta el sonido de esta trompeta hecha con cuerno de argali.\""}
MultiLanguageItemData['mx'][198538] = {name = "[q3]Mensaje sellado con magia", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"El papiro misterioso emana un polvo púrpura cautivador que se disipa después de un instante.\""}
